INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f42def0-8c47-4b9e-90e7-d51293cfa951', '晚思', '晚思', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["鶴下紫閣雲，沈沈翠微雨。","獨坐正無言，孤莊一聲杵。"]', '["鹤下紫閣云，沈沈翠微雨。","独坐正無言，孤莊一声杵。"]', '诗', 'shi', '', NULL, '晚思 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6c10d4b-8872-4b2d-bc25-ce9803757ae3', '贈空禪師', '贈空禪師', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["虎見修行久，松知夏臘高。","寒堂坐風雨，瞑目尚波濤。"]', '["虎见修行久，松知夏臘高。","寒堂坐风雨，瞑目尚波濤。"]', '诗', 'shi', '', NULL, '贈空禪師 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('127c839c-ba95-49f6-b7e0-07ece7bd0135', '西山寒日逢韋侍御', '西山寒日逢韋侍御', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["獬豸霜中貌，龍鍾病後顏。","慘傷此身事，風雪動江山。"]', '["獬豸霜中貌，龙鍾病後顏。","慘傷此身事，风雪动江山。"]', '诗', 'shi', '', NULL, '西山寒日逢韋侍御 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0952fff-6045-44ee-bc86-cf2192e23e7c', '題禪院', '題禪院', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["無花地亦香，有鶴松多直。","向此奚必孤，山僧盡相識。"]', '["無花地亦香，有鹤松多直。","向此奚必孤，山僧尽相識。"]', '诗', 'shi', '', NULL, '題禪院 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('374cf837-fba4-4c2c-9767-0a954a0830d0', '驚秋', '驚秋', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["鶯囀纔間關，蟬鳴旋蕭屑。","如何兩鬢毛，不作千枝雪。"]', '["鶯囀纔间关，蟬鳴旋蕭屑。","如何兩鬢毛，不作千枝雪。"]', '诗', 'shi', '', NULL, '驚秋 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8be2e543-a1f4-4672-a0f2-25e6df8fa430', '經劉校書墓', '經劉校书墓', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["遠冢松回曲渚風，一官聞是校書終。","霜情月思今何在，零落人間策子中。"]', '["远冢松回曲渚风，一官闻是校书終。","霜情月思今何在，零落人间策子中。"]', '诗', 'shi', '', NULL, '經劉校書墓 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d15c747c-5963-4992-b8fa-b566613c89d0', '蔣處士宅喜閑公至', '蔣处士宅喜闲公至', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["絕杯夏別螺江渡，單鉢春過處士齋。","嘗茗議空經不夜，照花明月影侵堦。"]', '["絕杯夏別螺江渡，單鉢春過处士斋。","嘗茗議空經不夜，照花明月影侵堦。"]', '诗', 'shi', '', NULL, '蔣處士宅喜閑公至 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbcf0b92-c243-49fc-b190-60d6de7379c6', '絕句', '絕句', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["銀地無塵金菊開，紫棃紅棗墮莓苔。","一泓秋水一輪月，今夜故人來不來。"]', '["銀地無塵金菊开，紫棃紅棗墮莓苔。","一泓秋水一輪月，今夜故人来不来。"]', '诗', 'shi', '', NULL, '絕句 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c3dbecb-f90b-4757-afc5-cf09a49f8d67', '句', '句', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["顏凋明鏡覺，思苦白雲知。","滄洲迷釣隱，紫閣負僧期。"]', '["顏凋明镜覺，思苦白云知。","滄洲迷釣隐，紫閣負僧期。"]', '诗', 'shi', '', NULL, '句 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d028ccdf-9ef8-4777-bce8-fcae79085318', '南陽道中作', '南陽道中作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["登郢屬歲陰，及宛懵所適。","復聞東漢主，遺此南都迹。","佳氣藹厥初，霸圖紛在昔。","茲邦稱貴近，與世嘗薰赫。","遭遇感風雲，變衰空草澤。","不識鄧公樹，猶傳陰后石。","驅馬歷闉闍，荆榛翳阡陌。","事去物無象，感來心不懌。","懷古對窮秋，興言傷遠客。","眇默遵岐路，辛勤弊行役。","雲雁號相呼，林麕走自索。","顧憶徇書劍，未嘗安枕席。","豈暇墨突黔，空持遼豕白。","迷復期非遠，歸歟賞農隙。"]', '["登郢屬歲陰，及宛懵所適。","复闻东漢主，遺此南都迹。","佳氣藹厥初，霸圖紛在昔。","茲邦稱貴近，與世嘗薰赫。","遭遇感风云，变衰空草澤。","不識鄧公樹，猶傳陰后石。","驱马歷闉闍，荆榛翳阡陌。","事去物無象，感来心不懌。","懷古对窮秋，兴言傷远客。","眇默遵岐路，辛勤弊行役。","云雁號相呼，林麕走自索。","顧憶徇书劍，未嘗安枕席。","豈暇墨突黔，空持遼豕白。","迷复期非远，归歟賞農隙。"]', '诗', 'shi', '', NULL, '南陽道中作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eae14fba-87b5-48d1-b270-353f76d2b898', '湘中作', '湘中作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["湘流繞南嶽，絕目轉青青。","懷祿未能已，瞻途屢所經。","煙嶼宜春望，林猿莫夜聽。","永路日多緒，孤舟天復冥。","浮沒從此去，嗟嗟勞我形。"]', '["湘流繞南嶽，絕目轉青青。","懷祿未能已，瞻途屢所經。","煙嶼宜春望，林猿莫夜听。","永路日多緒，孤舟天复冥。","浮沒從此去，嗟嗟勞我形。"]', '诗', 'shi', '', NULL, '湘中作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5b4ad26-6af5-4125-b43a-7840fc865f33', '彭蠡湖上', '彭蠡湖上', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["沿涉經大湖，湖流多行泆。","決晨趨北渚，逗浦已西日。","所適雖淹曠，中流且閑逸。","瑰詭良復多，感見乃非一。","廬山直陽滸，孤石當陰術。","一水雲際飛，數峰湖心出。","象類何交乣，形言豈深悉。","且知皆自然，高下無相恤。"]', '["沿涉經大湖，湖流多行泆。","決晨趨北渚，逗浦已西日。","所適雖淹曠，中流且闲逸。","瑰詭良复多，感见乃非一。","廬山直陽滸，孤石當陰術。","一水云際飞，數峰湖心出。","象類何交乣，形言豈深悉。","且知皆自然，高下無相恤。"]', '诗', 'shi', '', NULL, '彭蠡湖上 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dda856a1-8f74-47cf-bf5a-978a277d670c', '入廬山仰望瀑布水', '入廬山仰望瀑布水', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["絕頂有懸泉，喧喧出煙杪。","不知幾時歲，但見無昏曉。","閃閃青崖落，鮮鮮白日皎。","灑流濕行雲，濺沫驚飛鳥。","雷吼何噴薄，箭馳入窈窕。","昔聞山下蒙，今乃林巒表。","物情有詭激，坤元曷紛矯。","默然置此去，變化誰能了。"]', '["絕頂有懸泉，喧喧出煙杪。","不知幾时歲，但见無昏晓。","閃閃青崖落，鲜鲜白日皎。","灑流濕行云，濺沫驚飞鸟。","雷吼何噴薄，箭驰入窈窕。","昔闻山下蒙，今乃林巒表。","物情有詭激，坤元曷紛矯。","默然置此去，变化誰能了。"]', '诗', 'shi', '', NULL, '入廬山仰望瀑布水 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14514787-b0e7-4d45-81cb-7998ec8c49a6', '出爲豫章郡途次廬山東巖下', '出爲豫章郡途次廬山东巖下', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["茲山鎮何所，乃在澄湖陰。","下有蛟螭伏，上與虹蜺尋。","靈仙未始曠，窟宅何其深。","雙闕出雲峙，三宮入煙沈。","攀崖猶昔境，種杏非舊林。","想像終古跡，惆悵獨往心。","紛吾嬰世網，數載忝朝簪。","孤根自靡託，量力況不任。","多謝周身防，常恐橫議侵。","豈匪鵷鴻列，惕如泉壑臨。","迨茲刺江郡，來此滌塵襟。","有趣逢樵客，忘懷狎野禽。","棲閑義未果，用拙歡在今。","願言答休命，歸事丘中琴。"]', '["茲山鎮何所，乃在澄湖陰。","下有蛟螭伏，上與虹蜺尋。","靈仙未始曠，窟宅何其深。","雙闕出云峙，三宮入煙沈。","攀崖猶昔境，種杏非旧林。","想像終古跡，惆悵独往心。","紛吾嬰世網，數載忝朝簪。","孤根自靡託，量力況不任。","多謝周身防，常恐橫議侵。","豈匪鵷鴻列，惕如泉壑臨。","迨茲刺江郡，来此滌塵襟。","有趣逢樵客，忘懷狎野禽。","棲闲義未果，用拙歡在今。","願言答休命，归事丘中琴。"]', '诗', 'shi', '', NULL, '出爲豫章郡途次廬山東巖下 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c91e4c59-f6e7-4764-b866-083c2f4f2b13', '巡屬縣道中作', '巡屬縣道中作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["春令夙所奉，駕言遵此行。","途中却郡掾，林下招村氓。","至邑無紛劇，來人但歡迎。","豈伊念邦政，爾實在時清。","短才濫符竹，弱歲起柴荆。","再入江村道，永懷山藪情。","矧逢陽節獻，默聽時禽鳴。","迹與素心別，感從幽思盈。","流芳日不待，夙志蹇無成。","知命且何欲，所圖唯退耕。","華簪極身泰，衰鬢慙木榮。","苟得不可遂，吾其謝世嬰。"]', '["春令夙所奉，駕言遵此行。","途中却郡掾，林下招村氓。","至邑無紛劇，来人但歡迎。","豈伊念邦政，爾實在时清。","短才濫符竹，弱歲起柴荆。","再入江村道，永懷山藪情。","矧逢陽節獻，默听时禽鳴。","迹與素心別，感從幽思盈。","流芳日不待，夙志蹇無成。","知命且何欲，所圖唯退耕。","华簪極身泰，衰鬢慙木榮。","苟得不可遂，吾其謝世嬰。"]', '诗', 'shi', '', NULL, '巡屬縣道中作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3751feb5-8327-48f9-ad32-101a6b23ed7a', '夏日奉使南海在道中作', '夏日奉使南海在道中作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["緬然萬里露，赫曦三伏時。","飛走逃深林，流爍恐生疵。","行李豈無苦，而我方自怡。","肅事誠在公，拜慶遂及私。","展力慙淺效，銜恩感深慈。","且欲湯火蹈，況無鬼神欺。","朝發高山阿，夕濟長江湄。","秋瘴寧我毒，夏水胡不夷。","信知道存者，但問心所之。","呂梁有出入，乃覺非虛詞。"]', '["緬然万里露，赫曦三伏时。","飞走逃深林，流爍恐生疵。","行李豈無苦，而我方自怡。","肅事誠在公，拜慶遂及私。","展力慙淺效，銜恩感深慈。","且欲湯火蹈，況無鬼神欺。","朝發高山阿，夕濟长江湄。","秋瘴寧我毒，夏水胡不夷。","信知道存者，但问心所之。","呂梁有出入，乃覺非虛词。"]', '诗', 'shi', '', NULL, '夏日奉使南海在道中作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2546b734-e622-4e0d-9251-588bea723a85', '巡按自灕水南行', '巡按自灕水南行', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["理棹雖云遠，飲冰寧有惜。","況乃佳山川，怡然傲潭石。","奇峰岌前轉，茂樹隈中積。","猿鳥聲自呼，風泉氣相激。","目因詭容逆，心與清暉滌。","紛吾謬執簡，行郡將移檄。","即事聊獨歡，素懷豈兼適。","悠悠詠靡盬，庶以窮日夕。"]', '["理棹雖云远，饮冰寧有惜。","況乃佳山川，怡然傲潭石。","奇峰岌前轉，茂樹隈中積。","猿鸟声自呼，风泉氣相激。","目因詭容逆，心與清暉滌。","紛吾謬執簡，行郡將移檄。","即事聊独歡，素懷豈兼適。","悠悠詠靡盬，庶以窮日夕。"]', '诗', 'shi', '', NULL, '巡按自灕水南行 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0551aa37-4b0b-4818-9966-c4dc46f08a35', '使還都湘東作', '使還都湘东作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["倉庚昨歸候，陽鳥今去時。","感物遽如此，勞生安可思。","養真無上格，圖進豈前期。","清節往來苦，壯容離別衰。","盛明非不遇，弱操自云私。","孤楫清川泊，征衣寒露滋。","風朝津樹落，日夕嶺猿悲。","牽役而無悔，坐愁秪自怡。","當須報恩已，終爾謝塵緇。"]', '["倉庚昨归候，陽鸟今去时。","感物遽如此，勞生安可思。","養真無上格，圖進豈前期。","清節往来苦，壯容離別衰。","盛明非不遇，弱操自云私。","孤楫清川泊，征衣寒露滋。","风朝津樹落，日夕嶺猿悲。","牽役而無悔，坐愁秪自怡。","當須報恩已，終爾謝塵緇。"]', '诗', 'shi', '', NULL, '使還都湘東作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf44e73-4b66-4a18-b591-324ef9879cd5', '冬中至玉泉山寺屬窮陰冰閉崖谷無色及仲春行縣復往焉故有此作', '冬中至玉泉山寺屬窮陰冰閉崖谷無色及仲春行縣复往焉故有此作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["靈境信幽絕，芳時重暄妍。","再來及茲勝，一遇非無緣。","萬木柔可結，千花敷欲然。","松間鳴好鳥，竹下流清泉。","石壁開精舍，金光照法筵。","真空本自寂，假有聊相宣。","復此灰心者，仍追巢頂禪。","簡書雖有畏，身世亦相捐。"]', '["靈境信幽絕，芳时重暄妍。","再来及茲勝，一遇非無緣。","万木柔可結，千花敷欲然。","松间鳴好鸟，竹下流清泉。","石壁开精舍，金光照法筵。","真空本自寂，假有聊相宣。","复此灰心者，仍追巢頂禪。","簡书雖有畏，身世亦相捐。"]', '诗', 'shi', '', NULL, '冬中至玉泉山寺屬窮陰冰閉崖谷無色及仲春行縣復往焉故有此作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f47878a-5560-49b3-b5bd-ba3d9a67af39', '郢城西北有大古冢數十觀其封域多是楚時諸王而年代久遠不復可識唯直西有樊妃冢因後人爲植松柏故行路盡知之', '郢城西北有大古冢數十观其封域多是楚时諸王而年代久远不复可識唯直西有樊妃冢因後人爲植松柏故行路尽知之', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["蘋藻生南澗，蕙蘭秀中林。","嘉名有所在，芳氣無幽深。","楚子初逞志，樊妃嘗獻箴。","能令更擇士，非直罷從禽。","舊國皆湮滅，先王亦莫尋。","唯傳賢媛隴，猶結後人心。","牢落山川意，蕭疎松柏陰。","破牆時直上，荒徑或斜侵。","惠問終不絕，風流獨至今。","千春思窈窕，黃鳥復哀音。"]', '["蘋藻生南澗，蕙蘭秀中林。","嘉名有所在，芳氣無幽深。","楚子初逞志，樊妃嘗獻箴。","能令更擇士，非直罷從禽。","旧国皆湮滅，先王亦莫尋。","唯傳賢媛隴，猶結後人心。","牢落山川意，蕭疎松柏陰。","破牆时直上，荒徑或斜侵。","惠问終不絕，风流独至今。","千春思窈窕，黄鸟复哀音。"]', '诗', 'shi', '', NULL, '郢城西北有大古冢數十觀其封域多是楚時諸王而年代久遠不復可識唯直西有樊妃冢因後人爲植松柏故行路盡知之 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af03a160-91d9-4287-a65c-280c55f25067', '荆州作二首 一', '荆州作二首 一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["先達志其大，求意不約文。","士伸在知己，已況仕於君。","微誠夙所尚，細故不足云。","時來忽易失，事往良難分。","顧念凡近姿，焉欲殊常勳。","亦以行則是，豈必素有聞。","千慮且猶失，萬緒何其紛。","進士苟非黨，免相安得羣。","衆口金可鑠，孤心絲共棼。","意忠仗朋信，語勇同敗軍。","古劍徒有氣，幽蘭秪自薰。","高秩向所忝，於義如浮雲。"]', '["先達志其大，求意不約文。","士伸在知己，已況仕於君。","微誠夙所尚，細故不足云。","时来忽易失，事往良难分。","顧念凡近姿，焉欲殊常勳。","亦以行則是，豈必素有闻。","千慮且猶失，万緒何其紛。","進士苟非黨，免相安得羣。","衆口金可鑠，孤心絲共棼。","意忠仗朋信，語勇同敗軍。","古劍徒有氣，幽蘭秪自薰。","高秩向所忝，於義如浮云。"]', '诗', 'shi', '', NULL, '荆州作二首 一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af6305ad-f7e9-46fb-8b7b-5de448d3800d', '荆州作二首 二', '荆州作二首 二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["千載一遭遇，往賢所至難。","問余奚爲者，無階忽上摶。","明聖不世出，翼亮非苟安。","崇高自有配，孤陋何足干。","遇恩一時來，竊位三歲寒。","誰謂誠不盡，知窮力亦殫。","雖至負乘寇，初無挾術鑽。","浩蕩出江湖，翻覆如波瀾。","心傷不材樹，自念獨飛翰。","徇義在匹夫，報恩猶一餐。","況乃山海澤，效無毫髮端。","內訟已慙沮，積毀今摧殘。","胡爲復惕息，傷鳥畏虛彈。"]', '["千載一遭遇，往賢所至难。","问余奚爲者，無階忽上摶。","明聖不世出，翼亮非苟安。","崇高自有配，孤陋何足干。","遇恩一时来，竊位三歲寒。","誰謂誠不尽，知窮力亦殫。","雖至負乘寇，初無挾術鑽。","浩蕩出江湖，翻覆如波瀾。","心傷不材樹，自念独飞翰。","徇義在匹夫，報恩猶一餐。","況乃山海澤，效無毫髮端。","內訟已慙沮，積毀今摧殘。","胡爲复惕息，傷鸟畏虛彈。"]', '诗', 'shi', '', NULL, '荆州作二首 二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40c2882a-7e79-4915-a77a-95acb7cc4715', '在郡秋懷二首 一', '在郡秋懷二首 一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["秋風入前林，蕭瑟鳴高枝。","寂寞遊子思，寤歎何人知。","宦成名不立，志存歲已馳。","五十而無聞，古人深所疵。","平生去外飾，直道如不羈。","未得操割效，忽復寒暑移。","物情自古然，身退毀亦隨。","悠悠滄江渚，望望白雲涯。","露下霜且降，澤中草離披。","蘭艾若不分，安用馨香爲。"]', '["秋风入前林，蕭瑟鳴高枝。","寂寞游子思，寤歎何人知。","宦成名不立，志存歲已驰。","五十而無闻，古人深所疵。","平生去外飾，直道如不羈。","未得操割效，忽复寒暑移。","物情自古然，身退毀亦隨。","悠悠滄江渚，望望白云涯。","露下霜且降，澤中草離披。","蘭艾若不分，安用馨香爲。"]', '诗', 'shi', '', NULL, '在郡秋懷二首 一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7ed65df-dd08-4ffd-b3b5-82911b882ad1', '在郡秋懷二首 二', '在郡秋懷二首 二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["庭蕪生白露，歲候感遐心。","策蹇慙遠途，巢枝思故林。","小人恐致寇，終日如臨深。","魚鳥好自逸，池籠安所欽。","挂冠東都門，採蕨南山岑。","議道誠愧昔，覽分還愜今。","憮然憂成老，空爾白頭吟。"]', '["庭蕪生白露，歲候感遐心。","策蹇慙远途，巢枝思故林。","小人恐致寇，終日如臨深。","鱼鸟好自逸，池籠安所欽。","挂冠东都门，採蕨南山岑。","議道誠愧昔，覽分還愜今。","憮然憂成老，空爾白头吟。"]', '诗', 'shi', '', NULL, '在郡秋懷二首 二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e50a01e-f87e-467f-aae6-a4afe5522f07', '忝官二十年盡在內職及爲郡嘗積戀因賦詩焉', '忝官二十年尽在內職及爲郡嘗積戀因賦诗焉', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["江流去朝宗，晝夜茲不舍。","仲尼在川上，子牟存闕下。","聖達有由然，孰是無心者。","一郡苟能化，百城豈云寡。","愛禮誰爲羊，戀主吾猶馬。","感初時不載，思奮翼無假。","閑宇常自閉，沈心何用寫。","攬衣步前庭，登陴臨曠野。","白水生迢遞，清風寄瀟灑。","願言采芳澤，終朝不盈把。"]', '["江流去朝宗，晝夜茲不舍。","仲尼在川上，子牟存闕下。","聖達有由然，孰是無心者。","一郡苟能化，百城豈云寡。","愛禮誰爲羊，戀主吾猶马。","感初时不載，思奮翼無假。","闲宇常自閉，沈心何用寫。","攬衣步前庭，登陴臨曠野。","白水生迢遞，清风寄瀟灑。","願言采芳澤，終朝不盈把。"]', '诗', 'shi', '', NULL, '忝官二十年盡在內職及爲郡嘗積戀因賦詩焉 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2911bb59-187e-4e5c-849f-5933d8d352df', '二弟宰邑南海見羣鴈南飛因成詠以寄', '二弟宰邑南海见羣鴈南飞因成詠以寄', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["鴻雁自北來，嗷嗷度煙景。","常懷稻粱惠，豈憚江山永。","小大每相從，羽毛當自整。","雙鳧侶晨泛，獨鶴參宵警。","爲我更南飛，因書至梅嶺。"]', '["鴻雁自北来，嗷嗷度煙景。","常懷稻粱惠，豈憚江山永。","小大每相從，羽毛當自整。","雙鳧侶晨泛，独鹤參宵警。","爲我更南飞，因书至梅嶺。"]', '诗', 'shi', '', NULL, '二弟宰邑南海見羣鴈南飛因成詠以寄 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e87b912d-caf9-43b6-b564-8a9449982353', '將發還鄉示諸弟', '將發還乡示諸弟', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["歲陽亦頹止，林意日蕭摵。","云胡當此時，緬邁復爲客。","至愛孰能捨，名義來相迫。","負德良不貲，輸誠靡所惜。","一木逢廈構，纖塵願山益。","無力主君恩，寧利客卿璧。","去去榮歸養，憮然歎行役。"]', '["歲陽亦頹止，林意日蕭摵。","云胡當此时，緬邁复爲客。","至愛孰能捨，名義来相迫。","負德良不貲，輸誠靡所惜。","一木逢廈構，纖塵願山益。","無力主君恩，寧利客卿璧。","去去榮归養，憮然歎行役。"]', '诗', 'shi', '', NULL, '將發還鄉示諸弟 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147f1ae8-029a-4488-8cbe-5e3674106bef', '敘懷二首 一', '敘懷二首 一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["弱歲讀羣史，抗迹追古人。","被褐有懷玉，佩印從負薪。","志合豈兄弟，道行無賤貧。","孤根亦何賴，感激此爲鄰。"]', '["弱歲读羣史，抗迹追古人。","被褐有懷玉，佩印從負薪。","志合豈兄弟，道行無賤貧。","孤根亦何賴，感激此爲鄰。"]', '诗', 'shi', '', NULL, '敘懷二首 一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53bec44c-161e-45a2-8382-56f62206125a', '敘懷二首 二', '敘懷二首 二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["晚節從卑秩，岐路良非一。","既聞持兩端，復見挾三術。","木瓜誠有報，玉楮論無實。","已矣直躬者，平生壯圖失。","去去勿重陳，歸來茹芝朮。"]', '["晚節從卑秩，岐路良非一。","既闻持兩端，复见挾三術。","木瓜誠有報，玉楮論無實。","已矣直躬者，平生壯圖失。","去去勿重陳，归来茹芝朮。"]', '诗', 'shi', '', NULL, '敘懷二首 二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c490328-1b81-4bbc-9eaf-a23be0a8d648', '題畫山水障', '題畫山水障', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["心累猶不盡，果爲物外牽。","偶因耳目好，復假丹青妍。","嘗抱野間意，而迫區中緣。","塵事固已矣，秉意終不遷。","良工適我願，妙墨揮巖泉。","變化合羣有，高深侔自然。","置陳北堂上，倣像南山前。","靜無戶庭出，行已茲地偏。","萱草憂可樹，合歡忿益蠲。","所因本微物，況乃憑幽筌。","言象會自泯，意色聊自宣。","對玩有佳趣，使我心渺綿。"]', '["心累猶不尽，果爲物外牽。","偶因耳目好，复假丹青妍。","嘗抱野间意，而迫區中緣。","塵事固已矣，秉意終不遷。","良工適我願，妙墨揮巖泉。","变化合羣有，高深侔自然。","置陳北堂上，倣像南山前。","静無戶庭出，行已茲地偏。","萱草憂可樹，合歡忿益蠲。","所因本微物，況乃憑幽筌。","言象會自泯，意色聊自宣。","对玩有佳趣，使我心渺綿。"]', '诗', 'shi', '', NULL, '題畫山水障 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da66e474-0818-4e11-9b65-2a775faaff04', '奉和聖製瑞雪篇', '奉和聖製瑞雪篇', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["萬年春，三朝日，上御明臺旅庭實。","初瑞雪兮霏微，俄同雲兮蒙密。","此時騷切陰風生，先過金殿有餘清。","信宿嬋娟飛雪度，能使玉人俱掩嫮。","皓皓樓前月初白，紛紛陌上塵皆素。","昨訝驕陽積數旬，始知和氣待迎新。","匪惟在人利，曾是扶天意。","天意豈云遙，雪下不崇朝。","皇情玩無斁，雪委方盈尺。","草樹紛早榮，京坻宛先積。","君恩誠謂何，歲稔復人和。","預數斯箱慶，應如此雪多。","朝冕旒兮載悅，想籉笠兮農節。","倚瑤琴兮或歌，續薰風兮瑞雪。","福浸昌，應尤盛，瑞雪年年常感聖。","願以柏梁作，長爲柳花詠。"]', '["万年春，三朝日，上御明台旅庭實。","初瑞雪兮霏微，俄同云兮蒙密。","此时騷切陰风生，先過金殿有餘清。","信宿嬋娟飞雪度，能使玉人俱掩嫮。","皓皓楼前月初白，紛紛陌上塵皆素。","昨訝驕陽積數旬，始知和氣待迎新。","匪惟在人利，曾是扶天意。","天意豈云遙，雪下不崇朝。","皇情玩無斁，雪委方盈尺。","草樹紛早榮，京坻宛先積。","君恩誠謂何，歲稔复人和。","預數斯箱慶，應如此雪多。","朝冕旒兮載悅，想籉笠兮農節。","倚瑤琴兮或歌，續薰风兮瑞雪。","福浸昌，應尤盛，瑞雪年年常感聖。","願以柏梁作，长爲柳花詠。"]', '诗', 'shi', '', NULL, '奉和聖製瑞雪篇 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d1123c-827f-4953-a766-5aa6a24f41dd', '奉和聖製溫泉歌', '奉和聖製溫泉歌', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["有時神物待聖人，去後湯還冷，來時樹亦春。","今茲十月自東歸，羽斾逶迤上翠微。","溫谷葱葱佳氣色，離宮奕奕叶光輝。","臨渭川，近天邑。","浴日溫泉復在茲，羣仙洞府那相及。","吾君利物心，玄澤浸蒼黔。","漸漬神湯無疾苦，薰歌一曲感人深。"]', '["有时神物待聖人，去後湯還冷，来时樹亦春。","今茲十月自东归，羽斾逶迤上翠微。","溫谷葱葱佳氣色，離宮奕奕叶光輝。","臨渭川，近天邑。","浴日溫泉复在茲，羣仙洞府那相及。","吾君利物心，玄澤浸蒼黔。","漸漬神湯無疾苦，薰歌一曲感人深。"]', '诗', 'shi', '', NULL, '奉和聖製溫泉歌 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4c9badb-abd9-4465-a1cb-d4aeed309f3b', '南郊太尉酌獻武舞作凱安之樂', '南郊太尉酌獻武舞作凱安之乐', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["馨香惟后德，明命光天保。","肅祀崇聖靈，陳信表黃道。","玉戚初蹈厲，金匏既靜好。","介福何穰穰，精誠格穹昊。"]', '["馨香惟后德，明命光天保。","肅祀崇聖靈，陳信表黄道。","玉戚初蹈厲，金匏既静好。","介福何穰穰，精誠格穹昊。"]', '诗', 'shi', '', NULL, '南郊太尉酌獻武舞作凱安之樂 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7516502b-d130-4549-899a-8ff5b15b16dd', '奉和聖製經孔子舊宅', '奉和聖製經孔子旧宅', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["孔門太山下，不見登封時。","徒有先王法，今爲明主思。","恩加萬乘幸，禮致一牢祠。","舊宅千年外，光華空在茲。"]', '["孔门太山下，不见登封时。","徒有先王法，今爲明主思。","恩加万乘幸，禮致一牢祠。","旧宅千年外，光华空在茲。"]', '诗', 'shi', '', NULL, '奉和聖製經孔子舊宅 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de3ff7e-d9ec-41f8-ba0c-968b9b27be1c', '奉和聖製次瓊嶽韻', '奉和聖製次瓊嶽韻', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["山祗亦望幸，雲雨見靈心。","嶽館逢朝霽，關門解宿陰。","咸京天上近，清渭日邊臨。","我武因冬狩，何言是即禽。"]', '["山祗亦望幸，云雨见靈心。","嶽館逢朝霽，关门解宿陰。","咸京天上近，清渭日邊臨。","我武因冬狩，何言是即禽。"]', '诗', 'shi', '', NULL, '奉和聖製次瓊嶽韻 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2edca147-372f-465b-9481-f3d056cd0494', '奉和聖製送李尚書入蜀', '奉和聖製送李尚书入蜀', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["眷言感忠義，何有間山川。","徇節今如此，離情空復然。","皇心在勤恤，德澤委昭宣。","周月成功後，明年或勞還。"]', '["眷言感忠義，何有间山川。","徇節今如此，離情空复然。","皇心在勤恤，德澤委昭宣。","周月成功後，明年或勞還。"]', '诗', 'shi', '', NULL, '奉和聖製送李尚書入蜀 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eb324f2-ca2a-41e3-bffd-db9a439962ac', '奉和聖製初出洛城', '奉和聖製初出洛城', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["東土淹龍駕，西人望翠華。","山川祗詢物，宮觀豈爲家。","十月回星斗，千官捧日車。","洛陽無怨思，巡幸更非賒。"]', '["东土淹龙駕，西人望翠华。","山川祗詢物，宮观豈爲家。","十月回星斗，千官捧日车。","洛陽無怨思，巡幸更非賒。"]', '诗', 'shi', '', NULL, '奉和聖製初出洛城 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c2b5e9-57eb-442f-91a8-aa3a804ed45d', '奉和聖製途次陝州作', '奉和聖製途次陝州作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["馳道當河陝，陳詩問國風。","川原三晉別，襟帶兩京同。","後殿函關盡，前旌闕塞通。","行看洛陽陌，光景麗天中。"]', '["驰道當河陝，陳诗问国风。","川原三晉別，襟带兩京同。","後殿函关尽，前旌闕塞通。","行看洛陽陌，光景丽天中。"]', '诗', 'shi', '', NULL, '奉和聖製途次陝州作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d344c2d7-81fe-429e-83d6-903921727435', '勅賜寧王池宴', '勅賜寧王池宴', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["賢王有池館，明主賜春遊。","淑氣林間發，恩光水上浮。","徒慙和鼎地，終謝巨川舟。","皇澤空如此，輕生莫可酬。"]', '["賢王有池館，明主賜春游。","淑氣林间發，恩光水上浮。","徒慙和鼎地，終謝巨川舟。","皇澤空如此，轻生莫可酬。"]', '诗', 'shi', '', NULL, '勅賜寧王池宴 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e005d1a3-5710-4762-aa77-b40479deb759', '天津橋東旬宴得歌字韻', '天津橋东旬宴得歌字韻', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["清洛象天河，東流形勝多。","朝來逢宴喜，春盡却妍和。","泉鮪歡時躍，林鶯醉裏歌。"]', '["清洛象天河，东流形勝多。","朝来逢宴喜，春尽却妍和。","泉鮪歡时躍，林鶯醉裏歌。"]', '诗', 'shi', '', NULL, '天津橋東旬宴得歌字韻 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('188162e3-1363-4abf-adc6-76367dcbc45a', '上陽水窗旬宴得移字韻', '上陽水窗旬宴得移字韻', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["河漢非應到，汀洲忽在斯。","仍逢帝樂下，如逐海槎窺。","春賞時將換，皇恩歲不移。","今朝遊宴所，莫比天泉池。"]', '["河漢非應到，汀洲忽在斯。","仍逢帝乐下，如逐海槎窺。","春賞时將換，皇恩歲不移。","今朝游宴所，莫比天泉池。"]', '诗', 'shi', '', NULL, '上陽水窗旬宴得移字韻 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41a9682-a3ed-4712-9bd4-dd04debe2a42', '折楊柳', '折楊柳', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["纖纖折楊柳，持此寄情人。","一枝何足貴，憐是故園春。","遲景那能久，芳菲不及新。","更愁征戍客，容鬢老邊塵。"]', '["纖纖折楊柳，持此寄情人。","一枝何足貴，怜是故园春。","遲景那能久，芳菲不及新。","更愁征戍客，容鬢老邊塵。"]', '诗', 'shi', '', NULL, '折楊柳 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a55ab9-3ecd-4a29-a3da-9c39965d34d3', '剪綵', '剪綵', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["姹女矜容色，爲花不讓春。","既爭芳意早，誰待物華真。","葉作參差發，枝從點綴新。","自然無限態，長在豔陽晨。"]', '["姹女矜容色，爲花不讓春。","既爭芳意早，誰待物华真。","葉作參差發，枝從点綴新。","自然無限態，长在豔陽晨。"]', '诗', 'shi', '', NULL, '剪綵 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cf781b5-1221-4251-99ab-10b0e82ff8b1', '和崔黃門寓直夜聽蟬之作', '和崔黄门寓直夜听蟬之作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["蟬嘶玉樹枝，向夕惠風吹。","幸入連宵聽，應緣飲露知。","思深秋欲近，聲靜夜相宜。","不是黃金飾，清香徒爾爲。"]', '["蟬嘶玉樹枝，向夕惠风吹。","幸入連宵听，應緣饮露知。","思深秋欲近，声静夜相宜。","不是黄金飾，清香徒爾爲。"]', '诗', 'shi', '', NULL, '和崔黃門寓直夜聽蟬之作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9f94e75-7799-4224-b67d-46dc4a82fda6', '和姚令公從幸溫湯喜雪', '和姚令公從幸溫湯喜雪', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["萬乘飛黃馬，千金狐白裘。","正逢銀霰積，如向玉京遊。","瑞色鋪馳道，花文拂綵旒。","還聞吉甫頌，不共郢歌儔。"]', '["万乘飞黄马，千金狐白裘。","正逢銀霰積，如向玉京游。","瑞色鋪驰道，花文拂綵旒。","還闻吉甫頌，不共郢歌儔。"]', '诗', 'shi', '', NULL, '和姚令公從幸溫湯喜雪 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fb78b5e-232d-42ef-87a6-f47c68e8782f', '立春日晨起對積雪', '立春日晨起对積雪', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["忽對林亭雪，瑤華處處開。","今年迎氣始，昨夜伴春回。","玉潤窗前竹，花繁院裏梅。","東郊齋祭所，應見五神來。"]', '["忽对林亭雪，瑤华处处开。","今年迎氣始，昨夜伴春回。","玉潤窗前竹，花繁院裏梅。","东郊斋祭所，應见五神来。"]', '诗', 'shi', '', NULL, '立春日晨起對積雪 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9073ebeb-6c93-4eee-82d1-552596d2c299', '三月三日申王園亭宴集', '三月三日申王园亭宴集', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["稽亭追往事，睢苑勝前聞。","飛閣凌芳樹，華池落綵雲。","藉草人留酌，銜花鳥赴羣。","向來同賞處，惟恨碧林曛。"]', '["稽亭追往事，睢苑勝前闻。","飞閣凌芳樹，华池落綵云。","藉草人留酌，銜花鸟赴羣。","向来同賞处，惟恨碧林曛。"]', '诗', 'shi', '', NULL, '三月三日申王園亭宴集 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11d5c4f4-3e16-46ff-9b0d-49af0d413412', '三月三日登龍山', '三月三日登龙山', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["伊川與灞津，今日祓除人。","豈似龍山上，還同湘水濱。","衰顏憂更老，淑景望非春。","禊飲豈吾事，聊將偶俗塵。"]', '["伊川與灞津，今日祓除人。","豈似龙山上，還同湘水濱。","衰顏憂更老，淑景望非春。","禊饮豈吾事，聊將偶俗塵。"]', '诗', 'shi', '', NULL, '三月三日登龍山 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cca1d03f-9fc2-4224-9538-1353ebea09e9', '和王司馬折梅寄京邑昆弟', '和王司马折梅寄京邑昆弟', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["離別念同嬉，芬榮欲共持。","獨攀南國樹，遙寄北風時。","林惜迎春早，花愁去日遲。","還聞折梅處，更有棣華詩。"]', '["離別念同嬉，芬榮欲共持。","独攀南国樹，遙寄北风时。","林惜迎春早，花愁去日遲。","還闻折梅处，更有棣华诗。"]', '诗', 'shi', '', NULL, '和王司馬折梅寄京邑昆弟 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3c37ba4-57d4-4878-8b68-a2a4dd510fbf', '晚霽登王六東閣', '晚霽登王六东閣', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["試上江樓望，初逢山雨晴。","連空青嶂合，向晚白雲生。","彼美要殊觀，蕭條見遠情。","情來不可極，日暮水流清。"]', '["試上江楼望，初逢山雨晴。","連空青嶂合，向晚白云生。","彼美要殊观，蕭條见远情。","情来不可極，日暮水流清。"]', '诗', 'shi', '', NULL, '晚霽登王六東閣 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a42ae27-27d3-4ee0-a186-61359c052d0d', '蘇侍郎紫薇庭各賦一物得芍藥', '蘇侍郎紫薇庭各賦一物得芍藥', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["仙禁生紅藥，微芳不自持。","幸因清切地，還遇豔陽時。","名見桐君籙，香聞鄭國詩。","孤根若可用，非直愛華滋。"]', '["仙禁生紅藥，微芳不自持。","幸因清切地，還遇豔陽时。","名见桐君籙，香闻鄭国诗。","孤根若可用，非直愛华滋。"]', '诗', 'shi', '', NULL, '蘇侍郎紫薇庭各賦一物得芍藥 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13df8265-8a72-4922-876d-f84a855147fe', '和黃門盧侍御詠竹', '和黄门盧侍御詠竹', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["清切紫庭垂，葳蕤防露枝。","色無玄月變，聲有惠風吹。","高節人相重，虛心世所知。","鳳皇佳可食，一去一來儀。"]', '["清切紫庭垂，葳蕤防露枝。","色無玄月变，声有惠风吹。","高節人相重，虛心世所知。","鳳皇佳可食，一去一来儀。"]', '诗', 'shi', '', NULL, '和黃門盧侍御詠竹 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6033ba59-b72c-464e-905f-402fd9815ce7', '和韋尚書答梓州兄南亭宴集', '和韋尚书答梓州兄南亭宴集', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["棠棣聞餘興，烏衣有舊遊。","門前杜城陌，池上曲江流。","暇日嘗繁會，清風詠阻修。","始知西峙嶽，同氣此相求。"]', '["棠棣闻餘兴，烏衣有旧游。","门前杜城陌，池上曲江流。","暇日嘗繁會，清风詠阻修。","始知西峙嶽，同氣此相求。"]', '诗', 'shi', '', NULL, '和韋尚書答梓州兄南亭宴集 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5efb2a8-0a4b-417e-9e6a-b4143f7c873b', '答陳拾遺贈竹簪', '答陳拾遺贈竹簪', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["與君嘗此志，因物復知心。","遺我龍鍾節，非無玳瑁簪。","幽素宜相重，雕華豈所任。","爲君安首飾，懷此代兼金。"]', '["與君嘗此志，因物复知心。","遺我龙鍾節，非無玳瑁簪。","幽素宜相重，雕华豈所任。","爲君安首飾，懷此代兼金。"]', '诗', 'shi', '', NULL, '答陳拾遺贈竹簪 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97898374-3327-49fe-b8be-ed6b11467aed', '贈澧陽韋明府', '贈澧陽韋明府', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["君有百鍊刃，堪斷七重犀。","誰開太阿匣，持割武城雞。","竟與尚書佩，遙應天子提。","何時遇操宰，當使玉如泥。"]', '["君有百鍊刃，堪斷七重犀。","誰开太阿匣，持割武城雞。","竟與尚书佩，遙應天子提。","何时遇操宰，當使玉如泥。"]', '诗', 'shi', '', NULL, '贈澧陽韋明府 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a139bdc0-f4d6-48f1-9307-fec05f07cc38', '在洪州答綦毋學士', '在洪州答綦毋学士', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["旬雨不愆期，由來自若時。","爾無言郡政，吾豈欲天欺。","常念涓塵益，惟歡草樹滋。","課成非所擬，人望在東菑。"]', '["旬雨不愆期，由来自若时。","爾無言郡政，吾豈欲天欺。","常念涓塵益，惟歡草樹滋。","課成非所擬，人望在东菑。"]', '诗', 'shi', '', NULL, '在洪州答綦毋學士 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c5a804a-eddf-4b2b-8c7b-619262e61644', '酬王六霽後書懷見示', '酬王六霽後书懷见示', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["雲雨俱行罷，江天已洞開。","炎氛霽後滅，邊緒望中來。","作驥君垂耳，爲魚我曝鰓。","更憐湘水賦，還是洛陽才。"]', '["云雨俱行罷，江天已洞开。","炎氛霽後滅，邊緒望中来。","作驥君垂耳，爲鱼我曝鰓。","更怜湘水賦，還是洛陽才。"]', '诗', 'shi', '', NULL, '酬王六霽後書懷見示 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc671646-3d93-42f6-a6d4-d5372b7b6c98', '酬王六寒朝見詒', '酬王六寒朝见詒', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["賈生流寓日，揚子寂寥時。","在物多相背，唯君獨見思。","漁爲江上曲，雪作郢中詞。","忽枉兼金訊，長懷伐木詩。"]', '["賈生流寓日，揚子寂寥时。","在物多相背，唯君独见思。","漁爲江上曲，雪作郢中词。","忽枉兼金訊，长懷伐木诗。"]', '诗', 'shi', '', NULL, '酬王六寒朝見詒 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba228114-4d41-4101-94ee-b52c283ff21b', '林亭詠', '林亭詠', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["穿築非求麗，幽閑欲寄情。","偶懷因壤石，真意在蓬瀛。","苔益山文古，池添竹氣清。","從茲果蕭散，無事亦無營。"]', '["穿築非求丽，幽闲欲寄情。","偶懷因壤石，真意在蓬瀛。","苔益山文古，池添竹氣清。","從茲果蕭散，無事亦無營。"]', '诗', 'shi', '', NULL, '林亭詠 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb4d6479-b750-43ee-ae45-b0437fe1c2fe', '晨出郡舍林下', '晨出郡舍林下', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["晨興步北林，蕭散一開襟。","復見林上月，娟娟猶未沈。","片雲自孤遠，叢篠亦清深。","無事由來貴，方知物外心。"]', '["晨兴步北林，蕭散一开襟。","复见林上月，娟娟猶未沈。","片云自孤远，叢篠亦清深。","無事由来貴，方知物外心。"]', '诗', 'shi', '', NULL, '晨出郡舍林下 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e4866df-2a83-41a2-8efa-58ee7cdb40a6', '園中時蔬盡皆鋤理唯秋蘭數本委而不顧彼雖一物有足悲者遂賦二章 一', '园中时蔬尽皆鋤理唯秋蘭數本委而不顧彼雖一物有足悲者遂賦二章 一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["場藿已成歲，園葵亦向陽。","蘭時獨不偶，露節漸無芳。","旨異菁爲蓄，甘非蔗有漿。","人多利一飽，誰復惜馨香。"]', '["場藿已成歲，园葵亦向陽。","蘭时独不偶，露節漸無芳。","旨異菁爲蓄，甘非蔗有漿。","人多利一飽，誰复惜馨香。"]', '诗', 'shi', '', NULL, '園中時蔬盡皆鋤理唯秋蘭數本委而不顧彼雖一物有足悲者遂賦二章 一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f97a646-fec0-4cf6-9046-0d0036d6a8c5', '園中時蔬盡皆鋤理唯秋蘭數本委而不顧彼雖一物有足悲者遂賦二章 二', '园中时蔬尽皆鋤理唯秋蘭數本委而不顧彼雖一物有足悲者遂賦二章 二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["幸得不鋤去，孤苗守舊根。","無心羨旨蓄，豈欲近名園。","遇賞寧充佩，爲生莫礙門。","幽林芳意在，非是爲人論。"]', '["幸得不鋤去，孤苗守旧根。","無心羨旨蓄，豈欲近名园。","遇賞寧充佩，爲生莫礙门。","幽林芳意在，非是爲人論。"]', '诗', 'shi', '', NULL, '園中時蔬盡皆鋤理唯秋蘭數本委而不顧彼雖一物有足悲者遂賦二章 二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e2d526-e11f-41ef-981b-57f7370a74a8', '林亭寓言', '林亭寓言', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["林居逢歲晏，遇物使情多。","蘅茝不時與，芬榮奈汝何。","更憐籬下菊，無如松上蘿。","因依自有命，非是隔陽和。"]', '["林居逢歲晏，遇物使情多。","蘅茝不时與，芬榮奈汝何。","更怜籬下菊，無如松上蘿。","因依自有命，非是隔陽和。"]', '诗', 'shi', '', NULL, '林亭寓言 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc774df-bb8d-44ab-a247-2bc9489b53a5', '送使廣州', '送使廣州', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["家在湘源住，君今海嶠行。","經過正中道，相送倍爲情。","心逐書郵去，形隨世網嬰。","因聲謝遠別，緣義不緣名。"]', '["家在湘源住，君今海嶠行。","經過正中道，相送倍爲情。","心逐书郵去，形隨世網嬰。","因声謝远別，緣義不緣名。"]', '诗', 'shi', '', NULL, '送使廣州 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe82cd9-bd55-436d-9679-dd020a7f6351', '送姚評事入蜀各賦一物得卜肆', '送姚評事入蜀各賦一物得卜肆', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["蜀嚴化已久，沈冥空所思。","嘗聞賣卜處，猶憶下簾時。","驅傳應經此，懷賢倘問之。","歸來說往事，歷歷偶心期。"]', '["蜀嚴化已久，沈冥空所思。","嘗闻賣卜处，猶憶下簾时。","驱傳應經此，懷賢倘问之。","归来说往事，歷歷偶心期。"]', '诗', 'shi', '', NULL, '送姚評事入蜀各賦一物得卜肆 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a55d88c-4103-4c14-ac32-3f32dc37165c', '送竇校書見餞得雲中辨江樹', '送竇校书见餞得云中辨江樹', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["江水天連色，無涯淨野氛。","微明岸傍樹，凌亂渚前雲。","舉棹形徐轉，登艫意漸分。","渺茫從此去，空復惜離羣。"]', '["江水天連色，無涯淨野氛。","微明岸傍樹，凌亂渚前云。","舉棹形徐轉，登艫意漸分。","渺茫從此去，空复惜離羣。"]', '诗', 'shi', '', NULL, '送竇校書見餞得雲中辨江樹 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b12c6595-cb59-4fb0-8ca0-d7d968f1b80b', '餞王司馬入計同用洲字', '餞王司马入計同用洲字', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["元僚行上計，舉餞出林丘。","忽望題輿遠，空思解榻遊。","別筵鋪柳岸，征棹倚蘆洲。","獨歎湘江水，朝宗向北流。"]', '["元僚行上計，舉餞出林丘。","忽望題輿远，空思解榻游。","別筵鋪柳岸，征棹倚蘆洲。","独歎湘江水，朝宗向北流。"]', '诗', 'shi', '', NULL, '餞王司馬入計同用洲字 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f23f2b-7a80-457f-bf9d-b70627c5f87a', '東湖臨泛餞王司馬', '东湖臨泛餞王司马', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["南土秋雖半，東湖草未黃。","聊乘風日好，來汎芰荷香。","蘭棹無勞速，菱歌不厭長。","忽懷京洛去，難與共清光。"]', '["南土秋雖半，东湖草未黄。","聊乘风日好，来汎芰荷香。","蘭棹無勞速，菱歌不厭长。","忽懷京洛去，难與共清光。"]', '诗', 'shi', '', NULL, '東湖臨泛餞王司馬 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1558a170-9f05-4a1a-b907-b9f6061f4772', '餞濟陰梁明府各探一物得荷葉', '餞濟陰梁明府各探一物得荷葉', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["荷葉生幽渚，芳華信在茲。","朝朝空此地，采采欲因誰。","但恐星霜改，還將蒲稗衰。","懷君美人別，聊以贈心期。"]', '["荷葉生幽渚，芳华信在茲。","朝朝空此地，采采欲因誰。","但恐星霜改，還將蒲稗衰。","懷君美人別，聊以贈心期。"]', '诗', 'shi', '', NULL, '餞濟陰梁明府各探一物得荷葉 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e6b70c-4597-432b-a708-f5ada9e13f24', '餞陳學士還江南同用徵字', '餞陳学士還江南同用徵字', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["荷蓧旋江澳，銜杯餞霸陵。","別前林鳥息，歸處海煙凝。","風土鄉情接，雲山客念憑。","聖朝巖穴選，應待鶴書徵。"]', '["荷蓧旋江澳，銜杯餞霸陵。","別前林鸟息，归处海煙凝。","风土乡情接，云山客念憑。","聖朝巖穴選，應待鹤书徵。"]', '诗', 'shi', '', NULL, '餞陳學士還江南同用徵字 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca7182a2-f81a-421d-bc68-0c0bae3fd6f7', '通化門外送別', '通化门外送別', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["屢別容華改，長愁意緒微。","義將私愛隔，情與故人歸。","薄宦無時賞，勞生有事機。","離魂今夕夢，先繞舊林飛。"]', '["屢別容华改，长愁意緒微。","義將私愛隔，情與故人归。","薄宦無时賞，勞生有事機。","離魂今夕梦，先繞旧林飞。"]', '诗', 'shi', '', NULL, '通化門外送別 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5da44a-6a8d-4b0f-a9a5-857a973c415e', '送楊道士往天台', '送楊道士往天台', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["鬼谷還成道，天台去學仙。","行應松子化，留與世人傳。","此地煙波遠，何時羽駕旋？","當須一把袂，城郭共依然。"]', '["鬼谷還成道，天台去学仙。","行應松子化，留與世人傳。","此地煙波远，何时羽駕旋？","當須一把袂，城郭共依然。"]', '诗', 'shi', '', NULL, '送楊道士往天台 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c1ec5aa-1eb4-4032-8579-42bbbd7c8670', '送楊府李功曹', '送楊府李功曹', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["平生屬良友，結綬望光輝。","何知人事拙，相與宦情非。","別路穿林盡，征帆際海歸。","居然已多意，況復兩鄉違。"]', '["平生屬良友，結綬望光輝。","何知人事拙，相與宦情非。","別路穿林尽，征帆際海归。","居然已多意，況复兩乡違。"]', '诗', 'shi', '', NULL, '送楊府李功曹 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6bcc932-0955-4662-b64b-9ea6a2a73e66', '送宛句趙少府', '送宛句趙少府', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["解巾行作吏，尊酒謝離居。","修竹含清景，華池澹碧虛。","地將幽興愜，人與舊遊疎。","林下紛相送，多逢長者車。"]', '["解巾行作吏，尊酒謝離居。","修竹含清景，华池澹碧虛。","地將幽兴愜，人與旧游疎。","林下紛相送，多逢长者车。"]', '诗', 'shi', '', NULL, '送宛句趙少府 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7dd5fb5-96d1-4f6b-a198-c2e605d0b359', '送韋城李少府', '送韋城李少府', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["送客南昌尉，離亭西候春。","野花看欲盡，林鳥聽猶新。","別酒青門路，歸軒白馬津。","相知無遠近，萬里尚爲鄰。"]', '["送客南昌尉，離亭西候春。","野花看欲尽，林鸟听猶新。","別酒青门路，归軒白马津。","相知無远近，万里尚爲鄰。"]', '诗', 'shi', '', NULL, '送韋城李少府 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b88d32-d064-4302-86ba-19c61fc38ee0', '送蘇主簿赴偃師', '送蘇主簿赴偃師', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["我與文雄別，胡然邑吏歸。","賢人安下位，鷙鳥欲卑飛。","激節輕華冕，移官徇綵衣。","羨君行樂處，從此拜庭闈。"]', '["我與文雄別，胡然邑吏归。","賢人安下位，鷙鸟欲卑飞。","激節轻华冕，移官徇綵衣。","羨君行乐处，從此拜庭闈。"]', '诗', 'shi', '', NULL, '送蘇主簿赴偃師 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b187d7e-54d5-4cc5-a628-ca6ff1e8aff2', '送廣州周判官', '送廣州周判官', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["海郡雄蠻落，津亭壯越臺。","城隅百雉映，水曲萬家開。","里樹桄榔出，時禽翡翠來。","觀風猶未盡，早晚使車回。"]', '["海郡雄蠻落，津亭壯越台。","城隅百雉映，水曲万家开。","里樹桄榔出，时禽翡翠来。","观风猶未尽，早晚使车回。"]', '诗', 'shi', '', NULL, '送廣州周判官 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8dc1ddd-7118-41a3-890d-87f1bab28bd5', '郡江南上別孫侍御', '郡江南上別孫侍御', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["雲嶂天涯盡，川途海縣窮。","何言此地僻，忽與故人同。","身負邦君弩，情紆御史驄。","王程不我駐，離思逐秋風。"]', '["云嶂天涯尽，川途海縣窮。","何言此地僻，忽與故人同。","身負邦君弩，情紆御史驄。","王程不我駐，離思逐秋风。"]', '诗', 'shi', '', NULL, '郡江南上別孫侍御 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a57157fe-1c91-4a8e-aadf-8e7fb3960359', '道逢北使題贈京邑親知', '道逢北使題贈京邑親知', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["征驂稍靡靡，去國方遲遲。","路遶南登岸，情搖北上旗。","故人憐別日，旅雁逐歸時。"]', '["征驂稍靡靡，去国方遲遲。","路遶南登岸，情搖北上旗。","故人怜別日，旅雁逐归时。"]', '诗', 'shi', '', NULL, '道逢北使題贈京邑親知 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a723ee45-fd85-45da-a5b2-d6b7b1eea48f', '江上使風呈裴宣州耀卿', '江上使风呈裴宣州耀卿', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["江路與天連，風帆何淼然。","遙林浪出沒，孤舫鳥聯翩。","常愛千鈞重，深思萬事捐。","報恩非徇祿，還逐賈人船。"]', '["江路與天連，风帆何淼然。","遙林浪出沒，孤舫鸟聯翩。","常愛千鈞重，深思万事捐。","報恩非徇祿，還逐賈人船。"]', '诗', 'shi', '', NULL, '江上使風呈裴宣州耀卿 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d24c666-2922-4463-af1b-d48f6478c5e6', '溪行寄王震', '溪行寄王震', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["山氣朝來爽，溪流日向清。","遠心何處愜，閑棹此中行。","叢桂林間待，羣鷗水上迎。","徒然適我願，幽獨爲誰情。"]', '["山氣朝来爽，溪流日向清。","远心何处愜，闲棹此中行。","叢桂林间待，羣鷗水上迎。","徒然適我願，幽独爲誰情。"]', '诗', 'shi', '', NULL, '溪行寄王震 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88477520-e0c5-4d15-a954-9f9220baf4e9', '自豫章南還江上作', '自豫章南還江上作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["歸去南江水，磷磷見底清。","轉逢空闊處，聊洗滯留情。","浦樹遙如待，江鷗近若迎。","津途別有趣，況乃濯吾纓。"]', '["归去南江水，磷磷见底清。","轉逢空闊处，聊洗滯留情。","浦樹遙如待，江鷗近若迎。","津途別有趣，況乃濯吾纓。"]', '诗', 'shi', '', NULL, '自豫章南還江上作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61fe0569-f66c-4834-9ca8-5eb868ea75a8', '將至岳陽有懷趙二', '將至岳陽有懷趙二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["湘岸多深林，青冥晝結陰。","獨無謝客賞，況復賈生心。","草色雖云發，天光或未臨。","江潭非所遇，爲爾白頭吟。"]', '["湘岸多深林，青冥晝結陰。","独無謝客賞，況复賈生心。","草色雖云發，天光或未臨。","江潭非所遇，爲爾白头吟。"]', '诗', 'shi', '', NULL, '將至岳陽有懷趙二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c815659-b86f-4140-9788-9793892a5186', '使還湘水', '使還湘水', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["歸舟宛何處，正值楚江平。","夕逗煙村宿，朝緣浦樹行。","于役已彌歲，言旋今愜情。","鄉郊尚千里，流目夏雲生。"]', '["归舟宛何处，正值楚江平。","夕逗煙村宿，朝緣浦樹行。","于役已彌歲，言旋今愜情。","乡郊尚千里，流目夏云生。"]', '诗', 'shi', '', NULL, '使還湘水 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19a2ef2-1c93-4628-9e8e-5f2aa9af14eb', '初發道中寄遠', '初發道中寄远', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["日夜鄉山遠，秋風復此時。","舊聞胡馬思，今聽楚猿悲。","念別朝昏苦，懷歸歲月遲。","壯圖空不息，常恐髮如絲。"]', '["日夜乡山远，秋风复此时。","旧闻胡马思，今听楚猿悲。","念別朝昏苦，懷归歲月遲。","壯圖空不息，常恐髮如絲。"]', '诗', 'shi', '', NULL, '初發道中寄遠 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed6cca5-92e3-4d79-95b3-30fe0233ea46', '自湘水南行', '自湘水南行', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["落日摧行舫，逶迤洲渚間。","雖云有物役，乘此更休閑。","暝色生前浦，清暉發近山。","中流澹容與，唯愛鳥飛還。"]', '["落日摧行舫，逶迤洲渚间。","雖云有物役，乘此更休闲。","暝色生前浦，清暉發近山。","中流澹容與，唯愛鸟飞還。"]', '诗', 'shi', '', NULL, '自湘水南行 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7891eecb-7315-4992-8d23-dc1bc1670655', '初入湘中有喜', '初入湘中有喜', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["征鞍窮郢路，歸棹入湘流。","望鳥唯貪疾，聞猿亦罷愁。","兩邊楓作岸，數處橘爲洲。","却記從來意，翻疑夢裏遊。"]', '["征鞍窮郢路，归棹入湘流。","望鸟唯貪疾，闻猿亦罷愁。","兩邊楓作岸，數处橘爲洲。","却記從来意，翻疑梦裏游。"]', '诗', 'shi', '', NULL, '初入湘中有喜 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('300b1a29-6dbc-4978-8ae7-ec7d96df209c', '耒陽溪夜行', '耒陽溪夜行', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["乘夕棹歸舟，緣源路轉幽。","月明看嶺樹，風靜聽溪流。","嵐氣船間入，霜華衣上浮。","猿聲雖此夜，不是別家愁。"]', '["乘夕棹归舟，緣源路轉幽。","月明看嶺樹，风静听溪流。","嵐氣船间入，霜华衣上浮。","猿声雖此夜，不是別家愁。"]', '诗', 'shi', '', NULL, '耒陽溪夜行 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c95cedce-aa0e-438e-9beb-90a4ed153f90', '江上', '江上', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["長林何繚繞，遠水復悠悠。","盡日餘無見，爲心那不愁。","憶將親愛別，行爲主恩酬。","感激空如此，芳時屢已遒。"]', '["长林何繚繞，远水复悠悠。","尽日餘無见，爲心那不愁。","憶將親愛別，行爲主恩酬。","感激空如此，芳时屢已遒。"]', '诗', 'shi', '', NULL, '江上 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a042fcab-021e-4560-9dd1-d476d3e2328a', '自彭蠡湖初入江', '自彭蠡湖初入江', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["江岫殊空闊，雲煙處處浮。","上來羣噪鳥，中去獨行舟。","牢落誰相顧，逶迤日自愁。","更將心問影，于役復何求。"]', '["江岫殊空闊，云煙处处浮。","上来羣噪鸟，中去独行舟。","牢落誰相顧，逶迤日自愁。","更將心问影，于役复何求。"]', '诗', 'shi', '', NULL, '自彭蠡湖初入江 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ee2e38-b7b8-4dba-90b2-b5738ac9bee1', '赴使瀧峽', '赴使瀧峽', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["溪路日幽深，寒空入兩嶔。","霜清百丈水，風落萬重林。","夕鳥聯歸翼，秋猿斷去心。","別離多遠思，況乃歲方陰。"]', '["溪路日幽深，寒空入兩嶔。","霜清百丈水，风落万重林。","夕鸟聯归翼，秋猿斷去心。","別離多远思，況乃歲方陰。"]', '诗', 'shi', '', NULL, '赴使瀧峽 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9632216-d53c-4548-9fd7-da40dabefaba', '湖口望廬山瀑布泉', '湖口望廬山瀑布泉', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["萬丈洪泉落，迢迢半紫氛。","奔飛流雜樹，灑落出重雲。","日照虹蜺似，天清風雨聞。","靈山多秀色，空水共氤氳。"]', '["万丈洪泉落，迢迢半紫氛。","奔飞流杂樹，灑落出重云。","日照虹蜺似，天清风雨闻。","靈山多秀色，空水共氤氳。"]', '诗', 'shi', '', NULL, '湖口望廬山瀑布泉 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bab835c-8def-41e0-8c90-f1fe9a2daded', '湞陽峽', '湞陽峽', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["行舟傍越岑，窈窕越溪深。","水闇先秋冷，山晴當晝陰。","重林間五色，對壁聳千尋。","惜此生遐遠，誰知造化心。"]', '["行舟傍越岑，窈窕越溪深。","水闇先秋冷，山晴當晝陰。","重林间五色，对壁聳千尋。","惜此生遐远，誰知造化心。"]', '诗', 'shi', '', NULL, '湞陽峽 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95b1af8f-0e27-4687-913c-9c3e79dc9ee4', '使至廣州', '使至廣州', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["昔年嘗不調，茲地亦邅回。","本謂雙鳧少，何知駟馬來。","人非漢使橐，郡是越王臺。","去去雖殊事，山川長在哉。"]', '["昔年嘗不調，茲地亦邅回。","本謂雙鳧少，何知駟马来。","人非漢使橐，郡是越王台。","去去雖殊事，山川长在哉。"]', '诗', 'shi', '', NULL, '使至廣州 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad75cadd-fdf6-4c6b-a5bd-f12486a2ecd7', '春江晚景', '春江晚景', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["江林多秀發，雲日復相鮮。","征路那逢此，春心益渺然。","興來秪自得，佳氣莫能傳。","薄暮津亭下，餘花滿客船。"]', '["江林多秀發，云日复相鲜。","征路那逢此，春心益渺然。","兴来秪自得，佳氣莫能傳。","薄暮津亭下，餘花满客船。"]', '诗', 'shi', '', NULL, '春江晚景 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d74b17-1103-41a3-b832-e32f2b03cdb5', '與王六履震廣州津亭曉望', '與王六履震廣州津亭晓望', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["明發臨前渚，寒來淨遠空。","水紋天上碧，日氣海邊紅。","景物紛爲異，人情賴此同。","乘槎自有適，非欲破長風。"]', '["明發臨前渚，寒来淨远空。","水紋天上碧，日氣海邊紅。","景物紛爲異，人情賴此同。","乘槎自有適，非欲破长风。"]', '诗', 'shi', '', NULL, '與王六履震廣州津亭曉望 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1557ae63-96b7-4dc5-b746-ccdcdb4894b8', '初發曲江溪中', '初發曲江溪中', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["溪流清且深，松石復陰臨。","正爾可嘉處，胡爲無賞心。","我由不忍別，物亦有緣侵。","自匪常行邁，誰能知此音。"]', '["溪流清且深，松石复陰臨。","正爾可嘉处，胡爲無賞心。","我由不忍別，物亦有緣侵。","自匪常行邁，誰能知此音。"]', '诗', 'shi', '', NULL, '初發曲江溪中 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3d15485-8c59-4c34-8dd6-6af82c3850ef', '旅宿淮陽亭口號', '旅宿淮陽亭口號', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["日暮荒亭上，悠悠旅思多。","故鄉臨桂水，今夜渺星河。","暗草霜華發，空亭雁影過。","興來誰與晤，勞者自爲歌。"]', '["日暮荒亭上，悠悠旅思多。","故乡臨桂水，今夜渺星河。","暗草霜华發，空亭雁影過。","兴来誰與晤，勞者自爲歌。"]', '诗', 'shi', '', NULL, '旅宿淮陽亭口號 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c152693-c25f-45ce-8ef2-cbedce1a62bc', '望月懷遠', '望月懷远', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["海上生明月，天涯共此時。","情人怨遙夜，竟夕起相思。","滅燭憐光滿，披衣覺露滋。","不堪盈手贈，還寢夢佳期。"]', '["海上生明月，天涯共此时。","情人怨遙夜，竟夕起相思。","滅燭怜光满，披衣覺露滋。","不堪盈手贈，還寢梦佳期。"]', '诗', 'shi', '', NULL, '望月懷遠 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5c133e9-5a0b-4a8b-b9e5-dae5a857d1ab', '秋夕望月', '秋夕望月', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["清逈江城月，流光萬里同。","所思如夢裏，相望在庭中。","皎潔青苔露，蕭條黃葉風。","含情不得語，頻使桂華空。"]', '["清逈江城月，流光万里同。","所思如梦裏，相望在庭中。","皎潔青苔露，蕭條黄葉风。","含情不得語，頻使桂华空。"]', '诗', 'shi', '', NULL, '秋夕望月 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72f8a535-743c-42b8-ae57-d7d132468013', '詠燕', '詠燕', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["海燕何微眇，乘春亦蹔來。","豈知泥滓賤，秪見玉堂開。","繡戶時雙入，華軒日幾回。","無心與物競，鷹隼莫相猜。"]', '["海燕何微眇，乘春亦蹔来。","豈知泥滓賤，秪见玉堂开。","繡戶时雙入，华軒日幾回。","無心與物競，鷹隼莫相猜。"]', '诗', 'shi', '', NULL, '詠燕 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7acd3a73-d651-4c92-a43a-296916662ff3', '故刑部李尚書荆谷山集會', '故刑部李尚书荆谷山集會', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["嘗聞繼老耼，身退道彌耽。","結宇倚青壁，疎泉噴碧潭。","苔石隨人古，煙花寄酒酣。","山光紛向夕，歸興杜城南。"]', '["嘗闻繼老耼，身退道彌耽。","結宇倚青壁，疎泉噴碧潭。","苔石隨人古，煙花寄酒酣。","山光紛向夕，归兴杜城南。"]', '诗', 'shi', '', NULL, '故刑部李尚書荆谷山集會 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('203572ad-e792-4418-9ea5-fe0683a817b7', '戲題春意', '戲題春意', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["一作江南守，江林三四春。","相鳴不及鳥，相樂喜關人。","日守朱絲直，年催華髮新。","淮陽秪有臥，持此度芳辰。"]', '["一作江南守，江林三四春。","相鳴不及鸟，相乐喜关人。","日守朱絲直，年催华髮新。","淮陽秪有臥，持此度芳辰。"]', '诗', 'shi', '', NULL, '戲題春意 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c8012f-a33e-46aa-88aa-39d936052b42', '庭梅詠', '庭梅詠', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["芳意何能早，孤榮亦自危。","更憐花蔕弱，不受歲寒移。","朝雪那相妬，陰風已屢吹。","馨香雖尚爾，飄蕩復誰知。"]', '["芳意何能早，孤榮亦自危。","更怜花蔕弱，不受歲寒移。","朝雪那相妬，陰风已屢吹。","馨香雖尚爾，飄蕩复誰知。"]', '诗', 'shi', '', NULL, '庭梅詠 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41083533-dfc2-4cd9-8fcf-c556295c1561', '聽箏', '听箏', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["端居正無緒，那復發秦箏。","纖指傳新意，繁絃起怨情。","悠揚思欲絕，掩抑態還生。","豈是聲能感，人心自不平。"]', '["端居正無緒，那复發秦箏。","纖指傳新意，繁絃起怨情。","悠揚思欲絕，掩抑態還生。","豈是声能感，人心自不平。"]', '诗', 'shi', '', NULL, '聽箏 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72e57a19-316e-4a1c-98fd-021000e9faaa', '初秋憶金均兩弟', '初秋憶金均兩弟', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["江渚秋風至，他鄉離別心。","孤雲愁自遠，一葉感何深。","憂喜嘗同域，飛鳴忽異林。","青山西北望，堪作白頭吟。"]', '["江渚秋风至，他乡離別心。","孤云愁自远，一葉感何深。","憂喜嘗同域，飞鳴忽異林。","青山西北望，堪作白头吟。"]', '诗', 'shi', '', NULL, '初秋憶金均兩弟 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f724f80-bfea-4a7a-9389-89f2cbba6ecb', '秋懷', '秋懷', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["感惜芳時換，誰知客思懸。","憶隨鴻向煖，愁學馬思邊。","留滯機還息，紛拏網自牽。"]', '["感惜芳时換，誰知客思懸。","憶隨鴻向煖，愁学马思邊。","留滯機還息，紛拏網自牽。"]', '诗', 'shi', '', NULL, '秋懷 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8639576-404f-4384-ad76-055f85aafc23', '故刑部李尚書挽詞三首 一', '故刑部李尚书挽词三首 一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["仙宗出趙北，相業起山東。","明德嘗爲禮，嘉謀屢作忠。","論經白虎殿，獻賦甘泉宮。","與善今何在？蒼生望已空。"]', '["仙宗出趙北，相業起山东。","明德嘗爲禮，嘉謀屢作忠。","論經白虎殿，獻賦甘泉宮。","與善今何在？蒼生望已空。"]', '诗', 'shi', '', NULL, '故刑部李尚書挽詞三首 一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb22f551-1b39-4c82-9a56-e5f17de07a59', '故刑部李尚書挽詞三首 二', '故刑部李尚书挽词三首 二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["宿昔三台踐，榮華駟馬歸。","印從青瑣拜，翰入紫宸揮。","題劍恩方重，藏舟事已非。","龍門不可望，感激涕沾衣。"]', '["宿昔三台踐，榮华駟马归。","印從青瑣拜，翰入紫宸揮。","題劍恩方重，藏舟事已非。","龙门不可望，感激涕沾衣。"]', '诗', 'shi', '', NULL, '故刑部李尚書挽詞三首 二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f664c11b-b1cd-42b9-b4f0-68b47e616ec7', '故刑部李尚書挽詞三首 三', '故刑部李尚书挽词三首 三', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["永歎常山寶，沈埋京兆阡。","同盟會五月，華表記千年。","渺漫野中草，微茫空裏煙。","共悲人事絕，唯對杜陵田。"]', '["永歎常山寶，沈埋京兆阡。","同盟會五月，华表記千年。","渺漫野中草，微茫空裏煙。","共悲人事絕，唯对杜陵田。"]', '诗', 'shi', '', NULL, '故刑部李尚書挽詞三首 三 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4046bbe3-745d-4653-a42b-af497a04c4b1', '故徐州刺史贈吏部侍郎蘇公挽歌詞三首 一', '故徐州刺史贈吏部侍郎蘇公挽歌词三首 一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["韋玄方繼相，荀爽復齊名。","在貴兼天爵，能賢出世卿。","學聞金馬詔，神見玉人清。","藏壑今如此，爲山遂不成。"]', '["韋玄方繼相，荀爽复齊名。","在貴兼天爵，能賢出世卿。","学闻金马詔，神见玉人清。","藏壑今如此，爲山遂不成。"]', '诗', 'shi', '', NULL, '故徐州刺史贈吏部侍郎蘇公挽歌詞三首 一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b517389a-315d-479e-8ee5-6aaa35c5cb93', '故徐州刺史贈吏部侍郎蘇公挽歌詞三首 二', '故徐州刺史贈吏部侍郎蘇公挽歌词三首 二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["相如只謝病，子敬忽云亡。","豈悟瑤臺雪，分彫玉樹行。","清規留草議，故事在封章。","本謂山公啓，而今歿始揚。"]', '["相如只謝病，子敬忽云亡。","豈悟瑤台雪，分彫玉樹行。","清規留草議，故事在封章。","本謂山公啓，而今歿始揚。"]', '诗', 'shi', '', NULL, '故徐州刺史贈吏部侍郎蘇公挽歌詞三首 二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f882d209-a819-41aa-b0e7-eefa30d620f0', '故徐州刺史贈吏部侍郎蘇公挽歌詞三首 三', '故徐州刺史贈吏部侍郎蘇公挽歌词三首 三', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["返葬長安陌，秋風簫鼓悲。","奈何相送者，不是平生時。","寒影催年急，哀歌助晚遲。","寧知建旟罷，丹旐向京師。"]', '["返葬长安陌，秋风簫鼓悲。","奈何相送者，不是平生时。","寒影催年急，哀歌助晚遲。","寧知建旟罷，丹旐向京師。"]', '诗', 'shi', '', NULL, '故徐州刺史贈吏部侍郎蘇公挽歌詞三首 三 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b13ce6a7-15ab-46be-864e-316461c5dac4', '故滎陽君蘇氏挽歌詞三首 一', '故滎陽君蘇氏挽歌词三首 一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["門緒公侯列，嬪風詩禮行。","松蘿方有寄，桃李忽無成。","劍去雙龍別，雛哀九鳳鳴。","何言嶧山樹，還似半心生。"]', '["门緒公侯列，嬪风诗禮行。","松蘿方有寄，桃李忽無成。","劍去雙龙別，雛哀九鳳鳴。","何言嶧山樹，還似半心生。"]', '诗', 'shi', '', NULL, '故滎陽君蘇氏挽歌詞三首 一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc61c182-9db8-40d1-8303-40632cb307e3', '故滎陽君蘇氏挽歌詞三首 二', '故滎陽君蘇氏挽歌词三首 二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["永歎芳魂斷，行看草露滋。","二宗榮盛日，千古別離時。","竟罷生芻贈，空留畫扇悲。"]', '["永歎芳魂斷，行看草露滋。","二宗榮盛日，千古別離时。","竟罷生芻贈，空留畫扇悲。"]', '诗', 'shi', '', NULL, '故滎陽君蘇氏挽歌詞三首 二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606510b9-3076-41d4-84ce-5506da876a38', '故滎陽君蘇氏挽歌詞三首 三', '故滎陽君蘇氏挽歌词三首 三', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["縞服紛相送，玄扃翳不開。","更悲泉火滅，徒見柳車回。","舊室容衣奠，新塋拱樹栽。","唯應月照簟，潘岳此時哀。"]', '["縞服紛相送，玄扃翳不开。","更悲泉火滅，徒见柳车回。","旧室容衣奠，新塋拱樹栽。","唯應月照簟，潘岳此时哀。"]', '诗', 'shi', '', NULL, '故滎陽君蘇氏挽歌詞三首 三 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fa31da6-049e-47e3-a047-bc04819324f7', '眉州康司馬挽歌詞', '眉州康司马挽歌词', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["家受專門學，人稱入室賢。","劉楨徒有氣，管輅獨無年。","謫去長沙國，魂歸京兆阡。","從茲匣中劒，埋沒罷衝天。"]', '["家受專门学，人稱入室賢。","劉楨徒有氣，管輅独無年。","謫去长沙国，魂归京兆阡。","從茲匣中劒，埋沒罷衝天。"]', '诗', 'shi', '', NULL, '眉州康司馬挽歌詞 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('269d23e5-8f96-4b3b-91ff-a2132b3b1b5e', '奉和聖製早發三鄉山行', '奉和聖製早發三乡山行', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["羽衞森森西向秦，山川歷歷在清晨。","晴雲稍卷寒巖樹，宿雨能銷御路塵。","聖德由來合天道，靈符即此應時巡。","遺賢一一皆羈致，猶欲高深訪隱淪。"]', '["羽衞森森西向秦，山川歷歷在清晨。","晴云稍卷寒巖樹，宿雨能銷御路塵。","聖德由来合天道，靈符即此應时巡。","遺賢一一皆羈致，猶欲高深訪隐淪。"]', '诗', 'shi', '', NULL, '奉和聖製早發三鄉山行 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be90f21-23ca-4bb2-bc76-7f0d3a4d1673', '奉和聖製龍池篇', '奉和聖製龙池篇', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["天啓神龍生碧泉，泉水靈源浸迤延。","飛龍已向珠潭出，積水仍將銀漢連。","岸傍花柳看勝畫，浦上樓臺問是仙。","我后元符從此得，方爲萬歲壽圖川。"]', '["天啓神龙生碧泉，泉水靈源浸迤延。","飞龙已向珠潭出，積水仍將銀漢連。","岸傍花柳看勝畫，浦上楼台问是仙。","我后元符從此得，方爲万歲壽圖川。"]', '诗', 'shi', '', NULL, '奉和聖製龍池篇 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8719e483-1fbe-4129-a9a8-f8dcc36c30db', '奉和聖製南郊禮畢酺宴', '奉和聖製南郊禮畢酺宴', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["配天昭聖業，率土慶輝光。","春發三條路，酺開百戲場。","流恩均庶品，縱觀聚康莊。","妙舞來平樂，新聲出建章。","分曹日抱戴，赴節鳳歸昌。","幸奏承雲樂，同晞湛露陽。","氣和皆有感，澤厚自無疆。","飽德君臣醉，連歌奉柏梁。"]', '["配天昭聖業，率土慶輝光。","春發三條路，酺开百戲場。","流恩均庶品，縱观聚康莊。","妙舞来平乐，新声出建章。","分曹日抱戴，赴節鳳归昌。","幸奏承云乐，同晞湛露陽。","氣和皆有感，澤厚自無疆。","飽德君臣醉，連歌奉柏梁。"]', '诗', 'shi', '', NULL, '奉和聖製南郊禮畢酺宴 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2db5d9c4-0672-4c67-a17c-3d62ed5d766f', '奉和聖製早渡蒲津關', '奉和聖製早渡蒲津关', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["魏武中流處，軒皇問道回。","長堤春樹發，高掌曙雲開。","龍負王舟渡，人占仙氣來。","河津會日月，天仗役風雷。","東顧重關盡，西馳萬國陪。","還聞股肱郡，元首詠康哉。"]', '["魏武中流处，軒皇问道回。","长堤春樹發，高掌曙云开。","龙負王舟渡，人占仙氣来。","河津會日月，天仗役风雷。","东顧重关尽，西驰万国陪。","還闻股肱郡，元首詠康哉。"]', '诗', 'shi', '', NULL, '奉和聖製早渡蒲津關 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c5152c-16ba-4e50-a59d-2a53fe35727e', '奉和聖製同二相南出雀鼠谷', '奉和聖製同二相南出雀鼠谷', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["設險諸侯地，承平聖主巡。","東君朝二月，南斾擁三辰。","寒出重關盡，年隨行漏新。","瑞雲叢捧日，芳樹曲迎春。","舞詠先馳道，恩華及從臣。","汾川花鳥意，併奉屬車塵。"]', '["設險諸侯地，承平聖主巡。","东君朝二月，南斾擁三辰。","寒出重关尽，年隨行漏新。","瑞云叢捧日，芳樹曲迎春。","舞詠先驰道，恩华及從臣。","汾川花鸟意，併奉屬车塵。"]', '诗', 'shi', '', NULL, '奉和聖製同二相南出雀鼠谷 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('210fff42-e5ab-417b-892b-b7a8a00ca875', '奉和聖製經河上公廟', '奉和聖製經河上公廟', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["昔者河邊叟，誰知隱與仙。","姓名終不識，章句此空傳。","跡爲坐忘晦，言猶强著詮。","精靈竟何所，祠宇獨依然。","道在紆宸睠，風行動睿篇。","從茲化天下，清淨復何先。"]', '["昔者河邊叟，誰知隐與仙。","姓名終不識，章句此空傳。","跡爲坐忘晦，言猶强著詮。","精靈竟何所，祠宇独依然。","道在紆宸睠，风行动睿篇。","從茲化天下，清淨复何先。"]', '诗', 'shi', '', NULL, '奉和聖製經河上公廟 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d419996-527b-4c14-ba4c-4afac74fdf3f', '奉和聖製送尚書燕國公赴朔方', '奉和聖製送尚书燕国公赴朔方', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["宗臣事有征，廟筭在休兵。","天與三台座，人當萬里城。","朔南方偃革，河右暫揚旌。","寵錫從仙禁，光華出漢京。","山川勤遠畧，原隰軫皇情。","爲奏薰琴唱，仍題寶劒名。","聞風六郡伏，計日五戎平。","山甫歸應疾，留侯功復成。","歌鍾旋可望，袵席豈難行。","四牡何時入？吾君憶履聲。"]', '["宗臣事有征，廟筭在休兵。","天與三台座，人當万里城。","朔南方偃革，河右暫揚旌。","寵錫從仙禁，光华出漢京。","山川勤远畧，原隰軫皇情。","爲奏薰琴唱，仍題寶劒名。","闻风六郡伏，計日五戎平。","山甫归應疾，留侯功复成。","歌鍾旋可望，袵席豈难行。","四牡何时入？吾君憶履声。"]', '诗', 'shi', '', NULL, '奉和聖製送尚書燕國公赴朔方 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a247db3-7220-4022-8dde-432207780fdf', '奉和聖製途經華山', '奉和聖製途經华山', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["萬乘華山下，千巖雲漢中。","靈居雖窅密，睿覽忽玄同。","日月臨高掌，神仙仰大風。","攢峯勢岌岌，翊輦氣雄雄。","揆物知幽贊，銘勳表聖衷。","會應陪玉檢，來此告成功。"]', '["万乘华山下，千巖云漢中。","靈居雖窅密，睿覽忽玄同。","日月臨高掌，神仙仰大风。","攢峯勢岌岌，翊輦氣雄雄。","揆物知幽贊，銘勳表聖衷。","會應陪玉檢，来此告成功。"]', '诗', 'shi', '', NULL, '奉和聖製途經華山 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3037a96-1e76-4013-81e5-0dfd06cfb7e1', '奉和聖製早登太行山率爾言志', '奉和聖製早登太行山率爾言志', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["孟月攝提貞，乘時我后征。","晨嚴九折度，暮戒六軍行。","日御馳中道，風師卷太清。","戈鋋林表出，組練雪間明。","動植希皇豫，高深奉睿情。","陪遊七聖列，望幸百神迎。","氣色煙猶喜，恩光草尚榮。","之罘稱萬歲，今此復同聲。"]', '["孟月攝提貞，乘时我后征。","晨嚴九折度，暮戒六軍行。","日御驰中道，风師卷太清。","戈鋋林表出，組練雪间明。","动植希皇豫，高深奉睿情。","陪游七聖列，望幸百神迎。","氣色煙猶喜，恩光草尚榮。","之罘稱万歲，今此复同声。"]', '诗', 'shi', '', NULL, '奉和聖製早登太行山率爾言志 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9257c85b-961c-4165-a20e-bb58fd8bd2b5', '奉和聖製登封禮畢洛城酺宴', '奉和聖製登封禮畢洛城酺宴', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["大君畢能事，端扆樂成功。","運與千齡合，歡將萬國同。","漢酺歌聖酒，韶樂舞薰風。","河洛榮光遍，雲煙喜氣通。","春華頓覺早，天澤倍知崇。","草木皆沾被，猶言不在躬。"]', '["大君畢能事，端扆乐成功。","運與千齡合，歡將万国同。","漢酺歌聖酒，韶乐舞薰风。","河洛榮光遍，云煙喜氣通。","春华頓覺早，天澤倍知崇。","草木皆沾被，猶言不在躬。"]', '诗', 'shi', '', NULL, '奉和聖製登封禮畢洛城酺宴 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04dc7abc-8daa-4bcb-9742-401b0794ee12', '恩賜樂遊園宴應制', '恩賜乐游园宴應制', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["寶筵延厚命，供帳序羣公。","形勝宜春接，威儀建禮同。","晞陽人似露，解慍物從風。","朝慶千齡始，年華二月中。","輝光遍草木，和氣發絲桐。","歲歲無爲化，寧知樂九功。"]', '["寶筵延厚命，供帳序羣公。","形勝宜春接，威儀建禮同。","晞陽人似露，解慍物從风。","朝慶千齡始，年华二月中。","輝光遍草木，和氣發絲桐。","歲歲無爲化，寧知乐九功。"]', '诗', 'shi', '', NULL, '恩賜樂遊園宴應制 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61bcca0-a99e-4fab-a50f-5946a66d74f1', '奉和聖製過王濬墓', '奉和聖製過王濬墓', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["漢王思鉅鹿，晉將在弘農。","入蜀舉長筭，平吳成大功。","與渾雖不協，歸皓實爲雄。","孤績淪千載，流名感聖衷。","萬乘度荒隴，一顧凜生風。","古節猶不棄，今人爭效忠。"]', '["漢王思鉅鹿，晉將在弘農。","入蜀舉长筭，平吳成大功。","與渾雖不協，归皓實爲雄。","孤績淪千載，流名感聖衷。","万乘度荒隴，一顧凜生风。","古節猶不棄，今人爭效忠。"]', '诗', 'shi', '', NULL, '奉和聖製過王濬墓 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('715a22f8-0e05-4628-a8f4-f791f59b40a5', '奉和吏部崔尚書雨後大明朝堂望南山', '奉和吏部崔尚书雨後大明朝堂望南山', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["迢遞終南頂，朝朝閶闔前。","朅來青綺外，高在翠微先。","雙鳳褰爲闕，羣龍儼若仙。","還知到玄圃，更是謁甘泉。","夜雨塵初滅，秋空月正懸。","詭容紛入望，霽色宛成妍。","東極華陰踐，西彌嶓冢連。","奔峰出嶺外，瀑水落雲邊。","漢帝宮將苑，商君陌與阡。","林華鋪近甸，煙靄遶晴川。","既庶仁斯及，分憂政已宣。","山公啓事罷，吉甫頌聲傳。","濟濟金門步，洋洋玉樹篇。","徒歌雖有屬，清越豈同年。"]', '["迢遞終南頂，朝朝閶闔前。","朅来青綺外，高在翠微先。","雙鳳褰爲闕，羣龙儼若仙。","還知到玄圃，更是謁甘泉。","夜雨塵初滅，秋空月正懸。","詭容紛入望，霽色宛成妍。","东極华陰踐，西彌嶓冢連。","奔峰出嶺外，瀑水落云邊。","漢帝宮將苑，商君陌與阡。","林华鋪近甸，煙靄遶晴川。","既庶仁斯及，分憂政已宣。","山公啓事罷，吉甫頌声傳。","濟濟金门步，洋洋玉樹篇。","徒歌雖有屬，清越豈同年。"]', '诗', 'shi', '', NULL, '奉和吏部崔尚書雨後大明朝堂望南山 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a9517b6-1069-4c7e-8094-748f968d753b', '和崔尚書喜雨', '和崔尚书喜雨', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["積陽雖有晦，經月未爲灾。","上念人天重，先祈雲漢回。","仁心及草木，號令起風雷。","照爛陰霞止，交紛瑞雨來。","三辰破黍稷，四達屏氛埃。","池溜因添滿，林芳爲灑開。","聽中聲滴瀝，望處影徘徊。","惠澤成豐歲，昌言發上才。","無論驗石鼓，不是御雲臺。","直頌皇恩浹，崇朝遍九垓。"]', '["積陽雖有晦，經月未爲灾。","上念人天重，先祈云漢回。","仁心及草木，號令起风雷。","照爛陰霞止，交紛瑞雨来。","三辰破黍稷，四達屏氛埃。","池溜因添满，林芳爲灑开。","听中声滴瀝，望处影徘徊。","惠澤成豐歲，昌言發上才。","無論驗石鼓，不是御云台。","直頌皇恩浹，崇朝遍九垓。"]', '诗', 'shi', '', NULL, '和崔尚書喜雨 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('babd64aa-067a-412e-bd4c-c3b648d1073c', '和許給事中直夜簡諸公', '和許給事中直夜簡諸公', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["未央鐘漏晚，仙宇藹沈沈。","武衞千廬合，嚴扃萬戶深。","左掖知天近，南窗見月臨。","樹搖金掌露，庭徙玉樓陰。","他日聞更直，中宵屬所欽。","聲華大國寶，夙夜近臣心。","逸興乘高閣，雄飛在禁林。","寧思竊抃者，情發爲知音。"]', '["未央鐘漏晚，仙宇藹沈沈。","武衞千廬合，嚴扃万戶深。","左掖知天近，南窗见月臨。","樹搖金掌露，庭徙玉楼陰。","他日闻更直，中宵屬所欽。","声华大国寶，夙夜近臣心。","逸兴乘高閣，雄飞在禁林。","寧思竊抃者，情發爲知音。"]', '诗', 'shi', '', NULL, '和許給事中直夜簡諸公 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dfb6a8c-7ed7-4465-81a8-1cabe04b849d', '和蘇侍郎小園夕霽寄諸弟', '和蘇侍郎小园夕霽寄諸弟', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["清風閶闔至，軒蓋承明歸。","雲月愛秋景，林堂開夜扉。","何言兼濟日，尚與宴私違。","興逐蒹葭變，文因棠棣飛。","人倫用忠孝，帝德已光輝。","贈弟今爲貴，方知陸氏微。"]', '["清风閶闔至，軒蓋承明归。","云月愛秋景，林堂开夜扉。","何言兼濟日，尚與宴私違。","兴逐蒹葭变，文因棠棣飞。","人倫用忠孝，帝德已光輝。","贈弟今爲貴，方知陸氏微。"]', '诗', 'shi', '', NULL, '和蘇侍郎小園夕霽寄諸弟 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c453b832-1154-4a91-9e86-0779f5be008c', '酬宋使君見贈之作', '酬宋使君见贈之作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["時來不自意，宿昔謬樞衡。","翊聖負明主，妨賢媿友生。","罷歸猶右職，待罪尚南荆。","政有留棠舊，風因繼組成。","高軒問疾苦，烝庶荷仁明。","衰廢時所薄，秪言僚故情。"]', '["时来不自意，宿昔謬樞衡。","翊聖負明主，妨賢媿友生。","罷归猶右職，待罪尚南荆。","政有留棠旧，风因繼組成。","高軒问疾苦，烝庶荷仁明。","衰廢时所薄，秪言僚故情。"]', '诗', 'shi', '', NULL, '酬宋使君見贈之作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fba326d3-cb69-495b-8612-790a89eca98c', '酬宋使君見詒', '酬宋使君见詒', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["陟鄰初稟訓，獻策幸逢時。","朝列且云忝，君恩復若茲。","庭闈際海曲，軺傳荷天慈。","顧己歡烏鳥，聞君泣素絲。","才明應主召，福善豈神欺。","但願白心在，終然湼不淄。"]', '["陟鄰初稟訓，獻策幸逢时。","朝列且云忝，君恩复若茲。","庭闈際海曲，軺傳荷天慈。","顧己歡烏鸟，闻君泣素絲。","才明應主召，福善豈神欺。","但願白心在，終然湼不淄。"]', '诗', 'shi', '', NULL, '酬宋使君見詒 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4302630e-3456-4ecd-95c7-d4f05d69ed86', '酬通事舍人寓直見示篇中兼起居陸舍人景獻', '酬通事舍人寓直见示篇中兼起居陸舍人景獻', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["軒掖殊清秘，才華固在斯。","興因膏澤灑，情與惠風吹。","所美應人譽，何私亦我儀。","同聲感喬木，比翼謝長離。","價以陸生減，賢慙鮑叔知。","薄遊嘗獨媿，芳訊乃兼施。","此夜金閨籍，伊人瓊樹枝。","飛鳴復何遠，相顧幸媞媞。"]', '["軒掖殊清秘，才华固在斯。","兴因膏澤灑，情與惠风吹。","所美應人譽，何私亦我儀。","同声感喬木，比翼謝长離。","價以陸生減，賢慙鲍叔知。","薄游嘗独媿，芳訊乃兼施。","此夜金閨籍，伊人瓊樹枝。","飞鳴复何远，相顧幸媞媞。"]', '诗', 'shi', '', NULL, '酬通事舍人寓直見示篇中兼起居陸舍人景獻 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ab2af9-7d1e-4ddb-ac11-d98f8ebac600', '與袁補闕尋蔡拾遺會此公出行後蔡有五韻詩見贈以此篇答焉', '與袁補闕尋蔡拾遺會此公出行後蔡有五韻诗见贈以此篇答焉', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["轍迹陳家巷，詩書孟子鄰。","偶來乘興者，不值草玄人。","契是忘年合，情非累日申。","聞君還薄暮，見眷及茲辰。"]', '["轍迹陳家巷，诗书孟子鄰。","偶来乘兴者，不值草玄人。","契是忘年合，情非累日申。","闻君還薄暮，见眷及茲辰。"]', '诗', 'shi', '', NULL, '與袁補闕尋蔡拾遺會此公出行後蔡有五韻詩見贈以此篇答焉 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b38efa-5ae8-4a62-a1fd-bbe1fb46841f', '酬趙二侍御使西軍贈兩省舊僚之作', '酬趙二侍御使西軍贈兩省旧僚之作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["石室先鳴者，金門待制同。","操刀嘗願割，持斧竟稱雄。","應敵兵初起，緣邊虜欲空。","使車經隴月，征斾繞河風。","忽枉兼金訊，非徒秣馬功。","氣清蒲海曲，聲滿柏臺中。","顧己塵華省，欣君震遠戎。","明時獨匪報，嘗欲退微躬。"]', '["石室先鳴者，金门待制同。","操刀嘗願割，持斧竟稱雄。","應敵兵初起，緣邊虜欲空。","使车經隴月，征斾繞河风。","忽枉兼金訊，非徒秣马功。","氣清蒲海曲，声满柏台中。","顧己塵华省，欣君震远戎。","明时独匪報，嘗欲退微躬。"]', '诗', 'shi', '', NULL, '酬趙二侍御使西軍贈兩省舊僚之作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f5f278a-dde9-4ec0-84b0-9a15110bc045', '武司功初有幽庭春暄見貽夏首獲見以詩報焉', '武司功初有幽庭春暄见貽夏首獲见以诗報焉', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["芳月盡離居，幽懷重起予。","雖言春事晚，尚想物華初。","遲日皦方照，高齋澹復虛。","笋成林向密，花落樹應疎。","贈鯉情無間，求鶯思有餘。","暄妍不相待，含歎欲焉如。"]', '["芳月尽離居，幽懷重起予。","雖言春事晚，尚想物华初。","遲日皦方照，高斋澹复虛。","笋成林向密，花落樹應疎。","贈鯉情無间，求鶯思有餘。","暄妍不相待，含歎欲焉如。"]', '诗', 'shi', '', NULL, '武司功初有幽庭春暄見貽夏首獲見以詩報焉 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bda16b93-239d-418f-b1d6-bb842bb88d22', '酬王履震遊園林見貽', '酬王履震游园林见貽', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["宅生惟海縣，素業守郊園。","中覽霸王說，上徼明主恩。","一行罷蘭徑，數載歷金門。","既負潘生拙，俄從周任言。","逶迤戀軒陛，蕭散反丘樊。","舊逕稀人跡，前池耗水痕。","併看芳樹老，唯覺敝廬存。","自我棲幽谷，逢君翳覆盆。","孟軻應有命，賈誼得無冤。","江上行傷遠，林間偶避喧。","地偏人事絕，時霽鳥聲繁。","獨善心俱閉，窮居道共尊。","樂因南澗藻，憂豈北堂萱。","幽意加投漆，新詩重贈軒。","平生徇知己，窮達與君論。"]', '["宅生惟海縣，素業守郊园。","中覽霸王说，上徼明主恩。","一行罷蘭徑，數載歷金门。","既負潘生拙，俄從周任言。","逶迤戀軒陛，蕭散反丘樊。","旧逕稀人跡，前池耗水痕。","併看芳樹老，唯覺敝廬存。","自我棲幽谷，逢君翳覆盆。","孟軻應有命，賈誼得無冤。","江上行傷远，林间偶避喧。","地偏人事絕，时霽鸟声繁。","独善心俱閉，窮居道共尊。","乐因南澗藻，憂豈北堂萱。","幽意加投漆，新诗重贈軒。","平生徇知己，窮達與君論。"]', '诗', 'shi', '', NULL, '酬王履震遊園林見貽 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b404320a-cd54-40b0-a061-33d056514162', '餞王尚書出邊', '餞王尚书出邊', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["漢相推人傑，殷宗伐鬼方。","還聞出將重，坐見即戎良。","上策應爲豫，中權且用光。","令申兵氣倍，威憺虜魂亡。","樹比公孫大，城如道濟長。","夏雲登隴首，秋露泫遼陽。","武德舒宸睠，文思餞樂章。","感恩身既許，激節膽猶嘗。","祖帳傾朝列，軍麾駐道傍。","詩人何所詠，尚父欲鷹揚。"]', '["漢相推人傑，殷宗伐鬼方。","還闻出將重，坐见即戎良。","上策應爲豫，中權且用光。","令申兵氣倍，威憺虜魂亡。","樹比公孫大，城如道濟长。","夏云登隴首，秋露泫遼陽。","武德舒宸睠，文思餞乐章。","感恩身既許，激節膽猶嘗。","祖帳傾朝列，軍麾駐道傍。","诗人何所詠，尚父欲鷹揚。"]', '诗', 'shi', '', NULL, '餞王尚書出邊 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfcd275c-5a0c-43e6-9ecf-265ccab08b7b', '送趙都護赴安西', '送趙都護赴安西', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["將相有更踐，簡心良獨難。","遠圖嘗畫地，超拜乃登壇。","戎即崑山序，車同渤海單。","義無中國費，情必遠人安。","他日文兼武，而今栗且寬。","自然來月窟，何用刺樓蘭。","南至三冬晚，西馳萬里寒。","封侯自有處，征馬去嘽嘽。"]', '["將相有更踐，簡心良独难。","远圖嘗畫地，超拜乃登壇。","戎即崑山序，车同渤海單。","義無中国費，情必远人安。","他日文兼武，而今栗且寬。","自然来月窟，何用刺楼蘭。","南至三冬晚，西驰万里寒。","封侯自有处，征马去嘽嘽。"]', '诗', 'shi', '', NULL, '送趙都護赴安西 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cc342c6-de4a-4bb8-bd8a-aa10cb9ba715', '奉使自藍田玉山南行', '奉使自藍田玉山南行', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["征驂入雲壑，始憶步金門。","通籍微軀幸，歸途明主恩。","匪唯徇行役，兼得慰晨昏。","是節暑云熾，紛吾心所尊。","海縣且悠緬，山郵日駿奔。","徒知惡囂事，未暇息陰論。","嶢武經陳迹，衡湘指故園。","水聞南澗險，煙望北林繁。","遠靄千巖合，幽聲百籟喧。","陰泉夏猶凍，陽景晝方暾。","懿此高深極，徒令夢想存。","盛明期有報，長往復奚言。"]', '["征驂入云壑，始憶步金门。","通籍微軀幸，归途明主恩。","匪唯徇行役，兼得慰晨昏。","是節暑云熾，紛吾心所尊。","海縣且悠緬，山郵日駿奔。","徒知惡囂事，未暇息陰論。","嶢武經陳迹，衡湘指故园。","水闻南澗險，煙望北林繁。","远靄千巖合，幽声百籟喧。","陰泉夏猶凍，陽景晝方暾。","懿此高深極，徒令梦想存。","盛明期有報，长往复奚言。"]', '诗', 'shi', '', NULL, '奉使自藍田玉山南行 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ef17e6-53df-41a1-8b83-dde7dffbcf27', '賀給事嘗詣蔡起居郊館有詩因命同作', '賀給事嘗詣蔡起居郊館有诗因命同作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["記言聞直史，築室面層阿。","豈不承明入，終云幽意多。","沈冥高士致，休澣故人過。","前嶺遊氛滅，中林芳氣和。","茲辰阻佳趣，望美獨如何。"]', '["記言闻直史，築室面層阿。","豈不承明入，終云幽意多。","沈冥高士致，休澣故人過。","前嶺游氛滅，中林芳氣和。","茲辰阻佳趣，望美独如何。"]', '诗', 'shi', '', NULL, '賀給事嘗詣蔡起居郊館有詩因命同作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83c77296-bbc6-4528-84cf-d52b67fead5a', '南山下舊居閑放', '南山下旧居闲放', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["秪役已云久，乘閑返服初。","塊然屏塵事，幽獨坐林閭。","清曠前山遠，紛喧此地疎。","喬木凌青靄，修篁媚綠渠。","耳和繡翼鳥，目暢錦鱗魚。","寂寞心還間，飄颻體自虛。","興來命旨酒，臨罷閱仙書。","但樂多幽意，寧知有毀譽。","尚想爭名者，誰云要路居。","都忘下流歎，傾奪竟何如。"]', '["秪役已云久，乘闲返服初。","塊然屏塵事，幽独坐林閭。","清曠前山远，紛喧此地疎。","喬木凌青靄，修篁媚綠渠。","耳和繡翼鸟，目暢錦鱗鱼。","寂寞心還间，飄颻體自虛。","兴来命旨酒，臨罷閱仙书。","但乐多幽意，寧知有毀譽。","尚想爭名者，誰云要路居。","都忘下流歎，傾奪竟何如。"]', '诗', 'shi', '', NULL, '南山下舊居閑放 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c445310-bbba-4296-89aa-e2bf7c7976a6', '高齋閑望言懷', '高斋闲望言懷', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["高齋復晴景，延眺屬清秋。","風物動歸思，煙林生遠愁。","紛吾自窮海，薄宦此中州。","取路無高足，隨波適下流。","歲華空冉冉，心曲且悠悠。","坐惜芳時歇，胡然久滯留。"]', '["高斋复晴景，延眺屬清秋。","风物动归思，煙林生远愁。","紛吾自窮海，薄宦此中州。","取路無高足，隨波適下流。","歲华空冉冉，心曲且悠悠。","坐惜芳时歇，胡然久滯留。"]', '诗', 'shi', '', NULL, '高齋閑望言懷 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee8be0b9-f285-47aa-bfa6-74c9feda6dac', '別鄉人南還', '別乡人南還', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["橘柚南中暖，桑榆北地陰。","何言榮落異，因見別離心。","吾亦江鄉子，思歸夢寐深。","聞君去水宿，結思渺雲林。","牽綴從浮事，遲回謝所欽。","東南行舫遠，秋浦念猿吟。"]', '["橘柚南中暖，桑榆北地陰。","何言榮落異，因见別離心。","吾亦江乡子，思归梦寐深。","闻君去水宿，結思渺云林。","牽綴從浮事，遲回謝所欽。","东南行舫远，秋浦念猿吟。"]', '诗', 'shi', '', NULL, '別鄉人南還 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcf7db91-d7f3-486d-9807-167aa32d25bc', '初發江陵有懷', '初發江陵有懷', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["極望涔陽浦，江天渺不分。","扁舟從此去，鷗鳥自爲羣。","他日懷真賞，中年負俗紛。","適來果微尚，倏爾會斯文。","復想金閨籍，何如夢渚雲。","我行多勝寄，浩思獨氛氳。"]', '["極望涔陽浦，江天渺不分。","扁舟從此去，鷗鸟自爲羣。","他日懷真賞，中年負俗紛。","適来果微尚，倏爾會斯文。","复想金閨籍，何如梦渚云。","我行多勝寄，浩思独氛氳。"]', '诗', 'shi', '', NULL, '初發江陵有懷 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9a41ff5-2b5b-4cc7-92d6-b4635c404196', '同綦毋學士月夜聞雁', '同綦毋学士月夜闻雁', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["棲宿豈無意，飛飛更遠尋。","長途未及半，中夜有遺音。","月思關山笛，風號流水琴。","空聲兩相應，幽感一何深。","避繳歸南浦，離羣呌北林。","聯翩俱不定，憐爾越鄉心。"]', '["棲宿豈無意，飞飞更远尋。","长途未及半，中夜有遺音。","月思关山笛，风號流水琴。","空声兩相應，幽感一何深。","避繳归南浦，離羣呌北林。","聯翩俱不定，怜爾越乡心。"]', '诗', 'shi', '', NULL, '同綦毋學士月夜聞雁 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('333dbe31-11a2-47fb-be67-3f5e921453be', '登總持寺閣', '登總持寺閣', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["香閣起崔嵬，高高沙版開。","攀躋千仞上，紛詭萬形來。","草間商君陌，雲重漢后臺。","山從函谷斷，川向斗城回。","林裏春容變，天邊客思催。","登臨信爲美，懷遠獨悠哉。"]', '["香閣起崔嵬，高高沙版开。","攀躋千仞上，紛詭万形来。","草间商君陌，云重漢后台。","山從函谷斷，川向斗城回。","林裏春容变，天邊客思催。","登臨信爲美，懷远独悠哉。"]', '诗', 'shi', '', NULL, '登總持寺閣 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74db8f91-a97e-41ee-8f4e-f44f28ad1c03', '晚憩王少府東閣', '晚憩王少府东閣', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["披軒肆流覽，雲壑見深重。","空水秋彌淨，林煙晚更濃。","坐隅分洞府，簷際列羣峰。","窈窕生幽意，參差多異容。","還慙大隱跡，空想列仙蹤。","賴此昇攀處，蕭條得所從。"]', '["披軒肆流覽，云壑见深重。","空水秋彌淨，林煙晚更濃。","坐隅分洞府，簷際列羣峰。","窈窕生幽意，參差多異容。","還慙大隐跡，空想列仙蹤。","賴此昇攀处，蕭條得所從。"]', '诗', 'shi', '', NULL, '晚憩王少府東閣 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fe5a07c-c814-40ba-86d1-97edf1524e92', '登城樓望西山作', '登城楼望西山作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["城樓枕南浦，日夕顧西山。","宛宛鸞鶴處，高高煙霧間。","仙井今猶在，洪厓久不還。","金編莫我授，羽駕亦難攀。","簷際千峰出，雲中一鳥閑。","縱觀窮水國，游思徧人寰。","勿復塵埃事，歸來且閉關。"]', '["城楼枕南浦，日夕顧西山。","宛宛鸾鹤处，高高煙霧间。","仙井今猶在，洪厓久不還。","金編莫我授，羽駕亦难攀。","簷際千峰出，云中一鸟闲。","縱观窮水国，游思徧人寰。","勿复塵埃事，归来且閉关。"]', '诗', 'shi', '', NULL, '登城樓望西山作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00532c2f-0a00-4d72-9983-54ab4f6aa63f', '祠紫蓋山經玉泉山寺', '祠紫蓋山經玉泉山寺', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["指塗躋楚望，策馬傍荆岑。","稍稍松篁入，泠泠磵谷深。","觀奇逐幽暎，歷險忘嶇嶔。","上界投佛影，中天揚梵音。","焚香懺在昔，禮足誓來今。","靈異若有對，神仙真可尋。","高僧聞逝者，遠俗是初心。","蘚駁經行處，猿啼燕坐林。","歸真已寂滅，留迹豈[湮沈]。","法地自茲廣，何云千萬金。"]', '["指塗躋楚望，策马傍荆岑。","稍稍松篁入，泠泠磵谷深。","观奇逐幽暎，歷險忘嶇嶔。","上界投佛影，中天揚梵音。","焚香懺在昔，禮足誓来今。","靈異若有对，神仙真可尋。","高僧闻逝者，远俗是初心。","蘚駁經行处，猿啼燕坐林。","归真已寂滅，留迹豈[湮沈]。","法地自茲廣，何云千万金。"]', '诗', 'shi', '', NULL, '祠紫蓋山經玉泉山寺 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('846fe4c1-7800-4c19-bd05-9d1e0e72fda9', '洪州西山祈雨是日輒應因賦詩言事', '洪州西山祈雨是日輒應因賦诗言事', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["茲山蘊靈異，走望良有歸。","丘禱雖已久，甿心難重違。","遲明申藻薦，先夕旅巖扉。","獨宿雲峰下，蕭條人吏稀。","我來不外適，幽抱自中微。","靜入風泉奏，涼生松栝圍。","窮年滯遠想，寸晷閱清暉。","虛美悵無屬，素情緘所依。","詭隨嫌弱操，羇束謝貞肥。","義濟亦吾道，誠存爲物祈。","靈心倏已應，甘液幸而飛。","閉閣且無責，隨車安敢希。","多慙德不感，知復是耶非。"]', '["茲山蘊靈異，走望良有归。","丘禱雖已久，甿心难重違。","遲明申藻薦，先夕旅巖扉。","独宿云峰下，蕭條人吏稀。","我来不外適，幽抱自中微。","静入风泉奏，涼生松栝圍。","窮年滯远想，寸晷閱清暉。","虛美悵無屬，素情緘所依。","詭隨嫌弱操，羇束謝貞肥。","義濟亦吾道，誠存爲物祈。","靈心倏已應，甘液幸而飞。","閉閣且無責，隨车安敢希。","多慙德不感，知复是耶非。"]', '诗', 'shi', '', NULL, '洪州西山祈雨是日輒應因賦詩言事 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ddb2f27-5e26-445e-b486-59bad0c9df97', '經江寧覽舊跡至玄武湖', '經江寧覽旧跡至玄武湖', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["南國更數世，北湖方十洲。","天清華林苑，日晏景陽樓。","果下回仙騎，津傍駐綵斿。","鳧鷖喧鳳管，荷芰鬬龍舟。","七子陪詩賦，千人和棹謳。","應言在鎬樂，不讓橫汾秋。","風俗因紓慢，江山成易由。","駒王信不武，孫叔是無謀。","佳氣日將歇，霸功誰與修。","桑田東海變，麋鹿姑蘇遊。","否運爭三國，康時劣九州。","山雖幕府在，館豈豫章留。","水淀還相閱，菱歌亦故遒。","雄圖不足問，唯想事風流。"]', '["南国更數世，北湖方十洲。","天清华林苑，日晏景陽楼。","果下回仙騎，津傍駐綵斿。","鳧鷖喧鳳管，荷芰鬬龙舟。","七子陪诗賦，千人和棹謳。","應言在鎬乐，不讓橫汾秋。","风俗因紓慢，江山成易由。","駒王信不武，孫叔是無謀。","佳氣日將歇，霸功誰與修。","桑田东海变，麋鹿姑蘇游。","否運爭三国，康时劣九州。","山雖幕府在，館豈豫章留。","水淀還相閱，菱歌亦故遒。","雄圖不足问，唯想事风流。"]', '诗', 'shi', '', NULL, '經江寧覽舊跡至玄武湖 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b19be9f9-c4b5-4350-a9ca-3282d42a1876', '登襄陽峴山', '登襄陽峴山', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["昔年亟攀踐，征馬復來過。","信若山川舊，誰如歲月何。","蜀相吟安在，羊公碣已磨。","令圖猶寂寞，嘉會亦蹉跎。","宛宛樊城岸，悠悠漢水波。","逶迤春日遠，感寄客情多。","地本原林秀，朝來煙景和。","同心不同賞，留歎此巖阿。"]', '["昔年亟攀踐，征马复来過。","信若山川旧，誰如歲月何。","蜀相吟安在，羊公碣已磨。","令圖猶寂寞，嘉會亦蹉跎。","宛宛樊城岸，悠悠漢水波。","逶迤春日远，感寄客情多。","地本原林秀，朝来煙景和。","同心不同賞，留歎此巖阿。"]', '诗', 'shi', '', NULL, '登襄陽峴山 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a7496f-f4ae-47b8-9a60-4cce8b3e9514', '登荆州城樓', '登荆州城楼', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["天宇何其曠，江城坐自拘。","層樓百餘尺，迢遞在西隅。","暇日時登眺，荒郊臨故都。","纍纍見陳迹，寂寂想雄圖。","古往山川在，今來郡邑殊。","北疆雖入鄭，東距豈防吳。","幾代傳荆國，當時敵陝郛。","上流空有處，中土復何虞。","枕席夷三峽，關梁豁五湖。","承平無異境，守隘莫論夫。","自罷金門籍，來參竹使符。","端居向林藪，微尚在桑榆。","直似王陵戇，非如甯武愚。","今茲對南浦，乘雁與雙鳧。"]', '["天宇何其曠，江城坐自拘。","層楼百餘尺，迢遞在西隅。","暇日时登眺，荒郊臨故都。","纍纍见陳迹，寂寂想雄圖。","古往山川在，今来郡邑殊。","北疆雖入鄭，东距豈防吳。","幾代傳荆国，當时敵陝郛。","上流空有处，中土复何虞。","枕席夷三峽，关梁豁五湖。","承平無異境，守隘莫論夫。","自罷金门籍，来參竹使符。","端居向林藪，微尚在桑榆。","直似王陵戇，非如甯武愚。","今茲对南浦，乘雁與雙鳧。"]', '诗', 'shi', '', NULL, '登荆州城樓 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad6efc28-bd02-431b-a9f6-ed68b86c32e1', '登樂遊原春望書懷', '登乐游原春望书懷', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["城隅有樂遊，表裏見皇州。","策馬既長遠，雲山亦悠悠。","萬壑清光滿，千門喜氣浮。","花間直城路，草際曲江流。","憑眺茲爲美，離居方獨愁。","已驚玄髮換，空度綠荑柔。","奮翼籠中鳥，歸心海上鷗。","既傷日月逝，且欲桑榆收。","豹變焉能及，鶯鳴非可求。","願言從所好，初服返林丘。"]', '["城隅有乐游，表裏见皇州。","策马既长远，云山亦悠悠。","万壑清光满，千门喜氣浮。","花间直城路，草際曲江流。","憑眺茲爲美，離居方独愁。","已驚玄髮換，空度綠荑柔。","奮翼籠中鸟，归心海上鷗。","既傷日月逝，且欲桑榆收。","豹变焉能及，鶯鳴非可求。","願言從所好，初服返林丘。"]', '诗', 'shi', '', NULL, '登樂遊原春望書懷 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('607a04c7-d6b4-438b-b053-28330e5edee6', '候使登石頭驛樓作', '候使登石头驛楼作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["山檻憑南望，川途眇北流。","遠林天翠合，前浦日華浮。","萬井緣津渚，千艘咽渡頭。","漁商多末事，耕稼少良疇。","自守陳蕃榻，嘗登王粲樓。","徒然騁目處，豈是獲心遊。","向跡雖愚谷，求名異盜丘。","息陰芳木所，空復越鄉憂。"]', '["山檻憑南望，川途眇北流。","远林天翠合，前浦日华浮。","万井緣津渚，千艘咽渡头。","漁商多末事，耕稼少良疇。","自守陳蕃榻，嘗登王粲楼。","徒然騁目处，豈是獲心游。","向跡雖愚谷，求名異盜丘。","息陰芳木所，空复越乡憂。"]', '诗', 'shi', '', NULL, '候使登石頭驛樓作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df9eafc9-2f72-4d49-95e5-e6cfc390b67d', '登臨沮樓', '登臨沮楼', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["高深不可厭，巡屬復來過。","本與衆山絕，況茲韶景和。","危樓入水倒，飛檻向空摩。","雜樹緣青壁，樛枝掛綠蘿。","潭清能徹底，魚樂好跳波。","有象言雖具，無端思轉多。","同懷不在此，孤賞欲如何。"]', '["高深不可厭，巡屬复来過。","本與衆山絕，況茲韶景和。","危楼入水倒，飞檻向空摩。","杂樹緣青壁，樛枝掛綠蘿。","潭清能徹底，鱼乐好跳波。","有象言雖具，無端思轉多。","同懷不在此，孤賞欲如何。"]', '诗', 'shi', '', NULL, '登臨沮樓 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42fbff3e-da06-41ca-a472-7fd4fcca0476', '陪王司馬登薛公逍遙臺', '陪王司马登薛公逍遙台', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["嘗聞薛公淚，非直雍門琴。","竄逐留遺迹，悲涼見此心。","府中因暇豫，江上幸招尋。","人事已成古，風流獨至今。","閑情多感歎，清景暫登臨。","無復甘棠在，空餘蔓草深。","晴光送遠目，勝氣入幽襟。","水去朝滄海，春來換碧林。","賦懷湘浦弔，碑想漢川沈。","曾是陪遊日，徒爲梁父吟。"]', '["嘗闻薛公泪，非直雍门琴。","竄逐留遺迹，悲涼见此心。","府中因暇豫，江上幸招尋。","人事已成古，风流独至今。","闲情多感歎，清景暫登臨。","無复甘棠在，空餘蔓草深。","晴光送远目，勝氣入幽襟。","水去朝滄海，春来換碧林。","賦懷湘浦弔，碑想漢川沈。","曾是陪游日，徒爲梁父吟。"]', '诗', 'shi', '', NULL, '陪王司馬登薛公逍遙臺 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2306ecf4-6204-48b4-bf1b-471f5b0d2f96', '嘗與大理丞袁公太府丞田公偶詣一所林沼尤勝因並坐其次相得甚歡遂賦詩焉以詠其事', '嘗與大理丞袁公太府丞田公偶詣一所林沼尤勝因並坐其次相得甚歡遂賦诗焉以詠其事', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["方駕與吾友，同懷不異尋。","偶逢池竹處，便會江湖心。","夏近林方密，春餘水更深。","清華兩輝暎，閑步亦窺臨。","蘋藻復佳色，鳧鷖亦好音。","韶芳媚洲渚，蕙氣襲衣襟。","蕭散皆爲樂，裴回從所欽。","謂予成夙志，歲晚共抽簪。"]', '["方駕與吾友，同懷不異尋。","偶逢池竹处，便會江湖心。","夏近林方密，春餘水更深。","清华兩輝暎，闲步亦窺臨。","蘋藻复佳色，鳧鷖亦好音。","韶芳媚洲渚，蕙氣襲衣襟。","蕭散皆爲乐，裴回從所欽。","謂予成夙志，歲晚共抽簪。"]', '诗', 'shi', '', NULL, '嘗與大理丞袁公太府丞田公偶詣一所林沼尤勝因並坐其次相得甚歡遂賦詩焉以詠其事 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb02eaa9-b1ff-4334-94b6-d4bae0364548', '與弟遊家園', '與弟游家园', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["定省榮君賜，來歸是晝遊。","林烏飛舊里，園果讓新秋。","枝長南庭樹，池臨北澗流。","星霜屢爾別，蘭麝爲誰幽。","善積家方慶，恩深國未酬。","棲棲將義動，安得久情留。"]', '["定省榮君賜，来归是晝游。","林烏飞旧里，园果讓新秋。","枝长南庭樹，池臨北澗流。","星霜屢爾別，蘭麝爲誰幽。","善積家方慶，恩深国未酬。","棲棲將義动，安得久情留。"]', '诗', 'shi', '', NULL, '與弟遊家園 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d67944c6-1a69-4e14-8a34-d1e81adb5d30', '郡內閑齋', '郡內闲斋', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["郡閣晝常掩，庭蕪日復滋。","簷風落鳥毳，窗葉掛蟲絲。","拙病宦情少，羇閑秋氣悲。","理人無異績，爲郡但經時。","唯有江湖意，沈冥空在茲。"]', '["郡閣晝常掩，庭蕪日复滋。","簷风落鸟毳，窗葉掛蟲絲。","拙病宦情少，羇闲秋氣悲。","理人無異績，爲郡但經时。","唯有江湖意，沈冥空在茲。"]', '诗', 'shi', '', NULL, '郡內閑齋 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e5c4641-1081-43ab-bad5-09758953056f', '城南隅山池春中田袁二公盛稱其美夏首獲賞果會夙言故有此詠', '城南隅山池春中田袁二公盛稱其美夏首獲賞果會夙言故有此詠', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["憶昨聞佳境，駕言尋昔蹊。","非惟初物變，亦與舊遊暌。","幽渚爲君說，清晨即我攜。","途深獨睥睨，歷險共攀躋。","林笋苞青籜，津楊委綠荑。","荷香初出浦，草色復緣堤。","樂處將鷗狎，譚端用馬齊。","且言臨海郡，兼話武陵溪。","異壤風煙絕，空山巖逕迷。","如何際朝野，從此待金閨。"]', '["憶昨闻佳境，駕言尋昔蹊。","非惟初物变，亦與旧游暌。","幽渚爲君说，清晨即我携。","途深独睥睨，歷險共攀躋。","林笋苞青籜，津楊委綠荑。","荷香初出浦，草色复緣堤。","乐处將鷗狎，譚端用马齊。","且言臨海郡，兼話武陵溪。","異壤风煙絕，空山巖逕迷。","如何際朝野，從此待金閨。"]', '诗', 'shi', '', NULL, '城南隅山池春中田袁二公盛稱其美夏首獲賞果會夙言故有此詠 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32ae4c66-5f9c-4c4e-99a5-f3f96a6bc680', '西江夜行', '西江夜行', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["遙夜人何在，澄潭月裏行。","悠悠天宇曠，切切故鄉情。","外物寂無擾，中流澹自清。","念歸林葉換，愁坐露華生。","猶有汀洲鶴，宵分乍一鳴。"]', '["遙夜人何在，澄潭月裏行。","悠悠天宇曠，切切故乡情。","外物寂無擾，中流澹自清。","念归林葉換，愁坐露华生。","猶有汀洲鹤，宵分乍一鳴。"]', '诗', 'shi', '', NULL, '西江夜行 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d247e1-9365-4ae1-a8a6-3cfb3a00c64d', '南還湘水言懷', '南還湘水言懷', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["拙宦今何有？勞歌念不成。","十年乖夙志，一別悔前行。","歸去田園老，倘來軒冕輕。","江間稻正熟，林裏桂初榮。","魚意思在藻，鹿心懷食苹。","時哉苟不達，取樂遂吾情。"]', '["拙宦今何有？勞歌念不成。","十年乖夙志，一別悔前行。","归去田园老，倘来軒冕轻。","江间稻正熟，林裏桂初榮。","鱼意思在藻，鹿心懷食苹。","时哉苟不達，取乐遂吾情。"]', '诗', 'shi', '', NULL, '南還湘水言懷 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('070a223a-8a82-4657-b6b8-c4e1f43dedad', '商洛山行懷古', '商洛山行懷古', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["園綺值秦末，嘉遁此山阿。","陳迹向千古，荒途始一過。","碩人久淪謝，喬木自森羅。","故事昔嘗覽，遺風今豈訛。","泌泉空活活，樵叟獨皤皤。","是處清暉滿，從中幽興多。","長懷赤松意，復憶紫芝歌。","避世辭軒冕，逢時解薜蘿。","盛明今在運，吾道竟如何。"]', '["园綺值秦末，嘉遁此山阿。","陳迹向千古，荒途始一過。","碩人久淪謝，喬木自森羅。","故事昔嘗覽，遺风今豈訛。","泌泉空活活，樵叟独皤皤。","是处清暉满，從中幽兴多。","长懷赤松意，复憶紫芝歌。","避世辞軒冕，逢时解薜蘿。","盛明今在運，吾道竟如何。"]', '诗', 'shi', '', NULL, '商洛山行懷古 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bba0358-1035-49e3-a711-8a527144a9f5', '南還以詩代書贈京師舊僚', '南還以诗代书贈京師旧僚', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["薄宦晨昏闕，尊尊義取斯。","窮愁年貌改，寂歷爾胡爲。","不諂詞多忤，無容禮益卑。","微生尚何有？遠跡固其宜。","思擾梁山曲，情遙越鳥枝。","故園從海上，良友邈天涯。","雲雨歎一別，川原勞載馳。","上慙伯樂顧，中負叔牙知。","去國誠寥落，經途弊險巇。","歲逢霜雪苦，林屬蕙蘭萎。","欲贈幽芳歇，行悲舊賞移。","一從關作限，兩見月成規。","苒苒窮年籥，行行盡路岐。","征鞍稅北渚，歸帆指南垂。","樹晚猶葱蒨，江寒尚渺瀰。","土風從楚別，山水入湘奇。","石瀨相奔觸，煙林更蔽虧。","層崖夾洞浦，輕舸汎澄漪。","松篠行皆傍，禽魚動輙隨。","惜哉邊地隔，不與故人窺。","疇昔陪鵷鷺，朝陽振羽儀。","來音雖寂寞，接景每逶迤。","朝罷冥塵事，賓來話酒巵。","邀歡逐芳草，結興選華池。","及此風成歎，何時霧可披。","自憐無用者，誰念有情離。","望美音容闊，懷賢夢想疲。","因聲達霄漢，持拙守東陂。"]', '["薄宦晨昏闕，尊尊義取斯。","窮愁年貌改，寂歷爾胡爲。","不諂词多忤，無容禮益卑。","微生尚何有？远跡固其宜。","思擾梁山曲，情遙越鸟枝。","故园從海上，良友邈天涯。","云雨歎一別，川原勞載驰。","上慙伯乐顧，中負叔牙知。","去国誠寥落，經途弊險巇。","歲逢霜雪苦，林屬蕙蘭萎。","欲贈幽芳歇，行悲旧賞移。","一從关作限，兩见月成規。","苒苒窮年籥，行行尽路岐。","征鞍稅北渚，归帆指南垂。","樹晚猶葱蒨，江寒尚渺瀰。","土风從楚別，山水入湘奇。","石瀨相奔觸，煙林更蔽虧。","層崖夾洞浦，轻舸汎澄漪。","松篠行皆傍，禽鱼动輙隨。","惜哉邊地隔，不與故人窺。","疇昔陪鵷鷺，朝陽振羽儀。","来音雖寂寞，接景每逶迤。","朝罷冥塵事，賓来話酒巵。","邀歡逐芳草，結兴選华池。","及此风成歎，何时霧可披。","自怜無用者，誰念有情離。","望美音容闊，懷賢梦想疲。","因声達霄漢，持拙守东陂。"]', '诗', 'shi', '', NULL, '南還以詩代書贈京師舊僚 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae688214-c442-4f7e-9a74-d2e9d79579c6', '初發道中贈王司馬兼寄諸公', '初發道中贈王司马兼寄諸公', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["昔歲嘗陳力，中年退屏居。","承顏方弄鳥，放性或觀魚。","曾是安疵拙，誠非議卷舒。","林園事益簡，煙月賞恆餘。","不意棲愚谷，無階奉詔書。","湛恩均大造，弱植媿空虛。","肅命趨仙闕，僑裝撫傳車。","念行開祖帳，憐別降題輿。","誰謂風期許，叨延禮數殊。","義沾投分末，情及解攜初。","追餞扶江介，光輝燭里閭。","子雲應寂寞，公叔爲吹噓。","景物春來異，音容日向疎。","川原行稍穩，鐘鼓聽猶徐。","林隔王公轝，雲迷班氏廬。","戀親唯委咽，思德更躊躇。","徇義當由此，懷安乃闕如。","願酬明主惠，行矣豈徒歟。"]', '["昔歲嘗陳力，中年退屏居。","承顏方弄鸟，放性或观鱼。","曾是安疵拙，誠非議卷舒。","林园事益簡，煙月賞恆餘。","不意棲愚谷，無階奉詔书。","湛恩均大造，弱植媿空虛。","肅命趨仙闕，僑裝撫傳车。","念行开祖帳，怜別降題輿。","誰謂风期許，叨延禮數殊。","義沾投分末，情及解携初。","追餞扶江介，光輝燭里閭。","子云應寂寞，公叔爲吹噓。","景物春来異，音容日向疎。","川原行稍穩，鐘鼓听猶徐。","林隔王公轝，云迷班氏廬。","戀親唯委咽，思德更躊躇。","徇義當由此，懷安乃闕如。","願酬明主惠，行矣豈徒歟。"]', '诗', 'shi', '', NULL, '初發道中贈王司馬兼寄諸公 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04bfef48-2092-46e2-b281-691f11218f6a', '自始興溪夜上赴嶺', '自始兴溪夜上赴嶺', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["嘗蓄名山意，茲爲世網牽。","征途屢及此，初服已非然。","日落青巖際，溪行綠篠邊。","去舟乘月後，歸鳥息人前。","數曲迷幽嶂，連圻觸闇泉。","深林風緒結，遙夜客情懸。","非梗胡爲泛，無膏亦自煎。"]', '["嘗蓄名山意，茲爲世網牽。","征途屢及此，初服已非然。","日落青巖際，溪行綠篠邊。","去舟乘月後，归鸟息人前。","數曲迷幽嶂，連圻觸闇泉。","深林风緒結，遙夜客情懸。","非梗胡爲泛，無膏亦自煎。"]', '诗', 'shi', '', NULL, '自始興溪夜上赴嶺 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c4fd614-e2f8-40f5-ae94-0631da4aae47', '當塗界寄裴宣州', '當塗界寄裴宣州', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["故人宣城守，亦在江南偏。","如何分虎竹，相與間山川。","章綬胡爲者，形骸非自然。","含情津渡闊，倚望脰空延。","遠近聞佳政，平生仰大賢。","推心徒有屬，會面良無緣。","日夕遵前渚，江村投暮煙。","念行秪意默，懷遠豈言宣。","委曲風波事，難爲尺素傳。"]', '["故人宣城守，亦在江南偏。","如何分虎竹，相與间山川。","章綬胡爲者，形骸非自然。","含情津渡闊，倚望脰空延。","远近闻佳政，平生仰大賢。","推心徒有屬，會面良無緣。","日夕遵前渚，江村投暮煙。","念行秪意默，懷远豈言宣。","委曲风波事，难爲尺素傳。"]', '诗', 'shi', '', NULL, '當塗界寄裴宣州 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf065298-f718-445a-b21c-58400a224299', '郡中每晨興輙見羣鶴東飛至暮又行列而返哢唳雲路甚和樂焉予媿獨處江城常目送此意有所羨遂賦以詩', '郡中每晨兴輙见羣鹤东飞至暮又行列而返哢唳云路甚和乐焉予媿独处江城常目送此意有所羨遂賦以诗', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["雲間有數鶴，撫翼意無違。","曉日東田去，煙霄北渚歸。","歡呼良自適，羅列好相依。","遠集長江靜，高翔衆鳥稀。","豈煩仙子馭，何畏野人機。","却念乘軒者，拘留不得飛。"]', '["云间有數鹤，撫翼意無違。","晓日东田去，煙霄北渚归。","歡呼良自適，羅列好相依。","远集长江静，高翔衆鸟稀。","豈煩仙子馭，何畏野人機。","却念乘軒者，拘留不得飞。"]', '诗', 'shi', '', NULL, '郡中每晨興輙見羣鶴東飛至暮又行列而返哢唳雲路甚和樂焉予媿獨處江城常目送此意有所羨遂賦以詩 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ba7616-50c4-4e67-b70c-0bdfe7bf8853', '和裴侍中承恩拜掃旋轡途中有懷寄州縣官僚鄉國親故', '和裴侍中承恩拜掃旋轡途中有懷寄州縣官僚乡国親故', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["嵩嶽神惟降，汾川鼎氣雄。","生才作霖雨，繼代有清通。","天下稱賢相，朝端挹至公。","自家來佐國，移孝入爲忠。","霜露多前感，丘園想舊風。","扈巡過晉北，問俗到河東。","便道恩華降，還鄉禮教崇。","野尊延故老，朝服見兒童。"]', '["嵩嶽神惟降，汾川鼎氣雄。","生才作霖雨，繼代有清通。","天下稱賢相，朝端挹至公。","自家来佐国，移孝入爲忠。","霜露多前感，丘园想旧风。","扈巡過晉北，问俗到河东。","便道恩华降，還乡禮教崇。","野尊延故老，朝服见兒童。"]', '诗', 'shi', '', NULL, '和裴侍中承恩拜掃旋轡途中有懷寄州縣官僚鄉國親故 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94b9c1e7-9b5f-4925-bd3d-9499f3f1e4ec', '和姚令公哭李尚書乂', '和姚令公哭李尚书乂', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["貴賤雖殊等，平生竊下風。","雲泥勢已絕，山海納還通。","忽歎登龍者，翻將弔鶴同。","琴詩猶可託，劍履獨成空。","疇昔嘗論禮，興言每匪躬。","人思崔琰議，朝掩祭遵公。","作善神何酷，依仁命不融。","天文虛北斗，人事罷南宮。","上幸既傷舊，下流彌感衷。","無恩報國士，徒欲問玄穹。"]', '["貴賤雖殊等，平生竊下风。","云泥勢已絕，山海納還通。","忽歎登龙者，翻將弔鹤同。","琴诗猶可託，劍履独成空。","疇昔嘗論禮，兴言每匪躬。","人思崔琰議，朝掩祭遵公。","作善神何酷，依仁命不融。","天文虛北斗，人事罷南宮。","上幸既傷旧，下流彌感衷。","無恩報国士，徒欲问玄穹。"]', '诗', 'shi', '', NULL, '和姚令公哭李尚書乂 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867975bd-fcc1-4ee1-8deb-c622153a120d', '奉和聖製經函谷關作', '奉和聖製經函谷关作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["函谷雖云險，黃河已復清。","聖心無所隔，空此置關城。"]', '["函谷雖云險，黄河已复清。","聖心無所隔，空此置关城。"]', '诗', 'shi', '', NULL, '奉和聖製經函谷關作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfbc2f65-71d4-4e4e-9302-860a216c61ad', '奉和聖製度潼關口號', '奉和聖製度潼关口號', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["嶙嶙故城壘，荒涼空戍樓。","在德不在險，方知王道休。"]', '["嶙嶙故城壘，荒涼空戍楼。","在德不在險，方知王道休。"]', '诗', 'shi', '', NULL, '奉和聖製度潼關口號 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd7e235-ba25-4420-972b-404e43b902d3', '答太常靳博士見贈一絕', '答太常靳博士见贈一絕', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["上苑春先入，中園花盡開。","唯餘幽徑草，尚待日光催。"]', '["上苑春先入，中园花尽开。","唯餘幽徑草，尚待日光催。"]', '诗', 'shi', '', NULL, '答太常靳博士見贈一絕 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ee8b55c-6446-4693-910e-b05e72617faa', '登荆州城望江二首 一', '登荆州城望江二首 一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["滔滔大江水，天地相終始。","經閱幾世人，復歎誰家子。"]', '["滔滔大江水，天地相終始。","經閱幾世人，复歎誰家子。"]', '诗', 'shi', '', NULL, '登荆州城望江二首 一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47703350-cf8c-46e9-82a3-0b8e5a1c3963', '登荆州城望江二首 二', '登荆州城望江二首 二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["東望何悠悠，西來晝夜流。","歲月既如此，爲心那不愁。"]', '["东望何悠悠，西来晝夜流。","歲月既如此，爲心那不愁。"]', '诗', 'shi', '', NULL, '登荆州城望江二首 二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2535853-d394-4b17-ac90-30bfc859324f', '賦得自君之出矣', '賦得自君之出矣', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["自君之出矣，不復理殘機。","思君如滿月，夜夜減清輝。"]', '["自君之出矣，不复理殘機。","思君如满月，夜夜減清輝。"]', '诗', 'shi', '', NULL, '賦得自君之出矣 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe33e07-c234-4caa-bd28-60991e3e5312', '荅陸澧', '荅陸澧', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["松葉堪爲酒，春來釀幾多。","不辭山路遠，踏雪也相過。"]', '["松葉堪爲酒，春来釀幾多。","不辞山路远，踏雪也相過。"]', '诗', 'shi', '', NULL, '荅陸澧 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d56f2525-ba42-4af3-98f8-d95adc8364aa', '奉和上元酺宴應詔', '奉和上元酺宴應詔', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["甲乙遇災年，周隋送上弦。","妖星六丈出，沴氣七重懸。","赤縣空無主，蒼生欲問天。","龜龍開寶命，雲火昭靈慶。","萬物覩真人，千秋逢聖政。","祖宗玄澤遠，文武休光盛。","大號域中平，皇威天下驚。","參辰昭文物，宇宙浹聲名。","漢后三章令，周王五伐兵。","匈奴窮地角，本自遠正朔。","驕子起天街，由來虧禮樂。","一衣掃風雨，再戰夷屯剝。","清明日月旦，蕭索煙雲渙。","寒暑既平分，陰陽復貞觀。","惟神諧妙物，乃聖符幽贊。","下武發禎祥，平階屬會昌。","金泥封日觀，璧水匝明堂。","業盛勳華德，興包天地皇。","孝思義罔極，易禮光前式。","天煥三辰輝，靈書五雲色。","敬時窮發歛，卜代盈千億。","五緯聚華軒，重光入望園。","公卿論至道，天子拜昌言。","雷解初開出，星空即便元。","瑤臺涼景薦，銀闕秋陰遍。","百戲騁魚龍，千門壯宮殿。","深仁洽蠻徼，愷樂周寰縣。","宣室召羣臣，明庭禮百神。","仰德還符日，霑恩更似春。","襄城非牧豎，楚國有巴人。"]', '["甲乙遇災年，周隋送上弦。","妖星六丈出，沴氣七重懸。","赤縣空無主，蒼生欲问天。","龟龙开寶命，云火昭靈慶。","万物覩真人，千秋逢聖政。","祖宗玄澤远，文武休光盛。","大號域中平，皇威天下驚。","參辰昭文物，宇宙浹声名。","漢后三章令，周王五伐兵。","匈奴窮地角，本自远正朔。","驕子起天街，由来虧禮乐。","一衣掃风雨，再戰夷屯剝。","清明日月旦，蕭索煙云渙。","寒暑既平分，陰陽复貞观。","惟神諧妙物，乃聖符幽贊。","下武發禎祥，平階屬會昌。","金泥封日观，璧水匝明堂。","業盛勳华德，兴包天地皇。","孝思義罔極，易禮光前式。","天煥三辰輝，靈书五云色。","敬时窮發歛，卜代盈千億。","五緯聚华軒，重光入望园。","公卿論至道，天子拜昌言。","雷解初开出，星空即便元。","瑤台涼景薦，銀闕秋陰遍。","百戲騁鱼龙，千门壯宮殿。","深仁洽蠻徼，愷乐周寰縣。","宣室召羣臣，明庭禮百神。","仰德還符日，霑恩更似春。","襄城非牧豎，楚国有巴人。"]', '诗', 'shi', '', NULL, '奉和上元酺宴應詔 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079f54bb-8a3f-472d-a683-014ae7949c7d', '廣溪峽', '廣溪峽', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["廣溪三峽首，曠望兼川陸。","山路遶羊腸，江城鎮魚腹。","喬林百丈偃，飛水千尋瀑。","驚浪回高天，盤渦轉深谷。","漢氏昔云季，中原爭逐鹿。","天下有英雄，襄陽有龍伏。","常山集軍旅，永安興版築。","池臺忽已傾，邦家遽淪覆。","庸才若劉禪，忠佐爲心腹。","設險猶可存，當無賈生哭。"]', '["廣溪三峽首，曠望兼川陸。","山路遶羊腸，江城鎮鱼腹。","喬林百丈偃，飞水千尋瀑。","驚浪回高天，盤渦轉深谷。","漢氏昔云季，中原爭逐鹿。","天下有英雄，襄陽有龙伏。","常山集軍旅，永安兴版築。","池台忽已傾，邦家遽淪覆。","庸才若劉禪，忠佐爲心腹。","設險猶可存，當無賈生哭。"]', '诗', 'shi', '', NULL, '廣溪峽 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f35edb07-a3de-4188-812f-6066e9b83d33', '巫峽', '巫峽', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["三峽七百里，唯言巫峽長。","重巖窅不極，疊嶂凌蒼蒼。","絕壁橫天險，莓苔爛錦章。","入夜分明見，無風波浪狂。","忠信吾所蹈，泛舟亦何傷。","可以涉砥柱，可以浮呂梁。","美人今何在？靈芝徒有芳。","山空夜猿嘯，征客淚沾裳。"]', '["三峽七百里，唯言巫峽长。","重巖窅不極，叠嶂凌蒼蒼。","絕壁橫天險，莓苔爛錦章。","入夜分明见，無风波浪狂。","忠信吾所蹈，泛舟亦何傷。","可以涉砥柱，可以浮呂梁。","美人今何在？靈芝徒有芳。","山空夜猿嘯，征客泪沾裳。"]', '诗', 'shi', '', NULL, '巫峽 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4e76a73-6330-478d-8502-83458e18c416', '西陵峽', '西陵峽', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["絕壁聳萬仞，長波射千里。","盤薄荆之門，滔滔南國紀。","楚都昔全盛，高丘烜望祀。","秦兵一旦侵，夷陵火潛起。","四維不復設，關塞良難恃。","洞庭且忽焉，孟門終已矣。","自古天地闢，流爲峽中水。","行旅相贈言，風濤無極已。","及余踐斯地，瓌奇信爲美。","江山若有靈，千載伸知己。"]', '["絕壁聳万仞，长波射千里。","盤薄荆之门，滔滔南国紀。","楚都昔全盛，高丘烜望祀。","秦兵一旦侵，夷陵火潛起。","四維不复設，关塞良难恃。","洞庭且忽焉，孟门終已矣。","自古天地闢，流爲峽中水。","行旅相贈言，风濤無極已。","及余踐斯地，瓌奇信爲美。","江山若有靈，千載伸知己。"]', '诗', 'shi', '', NULL, '西陵峽 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c989738d-cb18-4f0d-a353-56e6bc3a3ab3', '從軍行', '從軍行', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["烽火照西京，心中自不平。","牙璋辭鳳闕，鐵騎繞龍城。","雪暗凋旗畫，風多雜鼓聲。","寧爲百夫長，勝作一書生。"]', '["烽火照西京，心中自不平。","牙璋辞鳳闕，鐵騎繞龙城。","雪暗凋旗畫，风多杂鼓声。","寧爲百夫长，勝作一书生。"]', '诗', 'shi', '', NULL, '從軍行 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a66b667d-75bd-4ee9-87ac-773b125d5b29', '劉生', '劉生', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["卿家本六郡，年長入三秦。","白璧酬知己，黃金謝主人。","劍鋒生赤電，馬足起紅塵。","日暮歌鐘發，喧喧動四鄰。"]', '["卿家本六郡，年长入三秦。","白璧酬知己，黄金謝主人。","劍鋒生赤電，马足起紅塵。","日暮歌鐘發，喧喧动四鄰。"]', '诗', 'shi', '', NULL, '劉生 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb0204e5-3ee1-4b08-b0ea-b5480d7af7c8', '驄馬', '驄马', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["驄馬鐵連錢，長安俠少年。","帝畿平若水，官路直如弦。","夜玉妝車軸，秋金鑄馬鞭。","風霜但自保，窮達任皇天。"]', '["驄马鐵連錢，长安俠少年。","帝畿平若水，官路直如弦。","夜玉妝车軸，秋金鑄马鞭。","风霜但自保，窮達任皇天。"]', '诗', 'shi', '', NULL, '驄馬 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('153ddc69-4ed3-4c91-a13f-01fd8abab905', '出塞', '出塞', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["塞外欲紛紜，雌雄猶未分。","明堂占氣色，華蓋辨星文。","二月河魁將，三千太乙軍。","丈夫皆有志，會見立功勳。"]', '["塞外欲紛紜，雌雄猶未分。","明堂占氣色，华蓋辨星文。","二月河魁將，三千太乙軍。","丈夫皆有志，會见立功勳。"]', '诗', 'shi', '', NULL, '出塞 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3389307a-0db9-437e-a686-58794ccd18dc', '有所思', '有所思', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["賤妾留南楚，征夫向北燕。","三秋方一日，少別比千年。","不掩嚬紅樓，無論數綠錢。","相思明月夜，迢遞白雲天。"]', '["賤妾留南楚，征夫向北燕。","三秋方一日，少別比千年。","不掩嚬紅楼，無論數綠錢。","相思明月夜，迢遞白云天。"]', '诗', 'shi', '', NULL, '有所思 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3b5a394-f179-471b-8855-8b9b6a6ce39d', '梅花落', '梅花落', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["窗外一株梅，寒花五出開。","影隨朝日遠，香逐便風來。","泣對銅鈎障，愁看玉鏡臺。","行人斷消息，春恨幾裴回。"]', '["窗外一株梅，寒花五出开。","影隨朝日远，香逐便风来。","泣对銅鈎障，愁看玉镜台。","行人斷消息，春恨幾裴回。"]', '诗', 'shi', '', NULL, '梅花落 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82514788-2ea1-4930-80e4-f9ee3fad85fd', '折楊柳', '折楊柳', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["邊地遙無極，征人去不還。","秋容凋翠羽，別淚損紅顏。","望斷流星驛，心馳明月關。","藁砧何處在？楊柳自堪攀。"]', '["邊地遙無極，征人去不還。","秋容凋翠羽，別泪損紅顏。","望斷流星驛，心驰明月关。","藁砧何处在？楊柳自堪攀。"]', '诗', 'shi', '', NULL, '折楊柳 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d5bda08-dd9e-43cd-820e-ed52b77f35fd', '紫騮馬', '紫騮马', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["俠客重周遊，金鞭控紫騮。","蛇弓白羽箭，鶴轡赤茸鞦。","發跡來南海，長鳴向北州。","匈奴今未滅，畫地取封侯。"]', '["俠客重周游，金鞭控紫騮。","蛇弓白羽箭，鹤轡赤茸鞦。","發跡来南海，长鳴向北州。","匈奴今未滅，畫地取封侯。"]', '诗', 'shi', '', NULL, '紫騮馬 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a19c95f-68ad-4c38-8c03-a3365f32b547', '戰城南', '戰城南', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["塞北途遼遠，城南戰苦辛。","旛旗如鳥翼，甲胄似魚鱗。","凍水寒傷馬，悲風愁殺人。","寸心明白日，千里暗黃塵。"]', '["塞北途遼远，城南戰苦辛。","旛旗如鸟翼，甲胄似鱼鱗。","凍水寒傷马，悲风愁殺人。","寸心明白日，千里暗黄塵。"]', '诗', 'shi', '', NULL, '戰城南 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b049fac-a802-4c1d-a741-d8b7a3465d83', '送臨津房少府', '送臨津房少府', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["岐路三秋別，江津萬里長。","煙霞駐征蓋，弦奏促飛觴。","階樹含斜日，池風泛早涼。","贈言未終竟，流涕忽沾裳。"]', '["岐路三秋別，江津万里长。","煙霞駐征蓋，弦奏促飞觴。","階樹含斜日，池风泛早涼。","贈言未終竟，流涕忽沾裳。"]', '诗', 'shi', '', NULL, '送臨津房少府 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c48e67c-df64-4b13-9de4-7e0dd79d2aef', '送豐城王少府', '送豐城王少府', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["愁結亂如麻，長天照落霞。","離亭隱喬樹，溝水浸平沙。","左尉才何屈，東關望漸賒。","行看轉牛斗，持此報張華。"]', '["愁結亂如麻，长天照落霞。","離亭隐喬樹，溝水浸平沙。","左尉才何屈，东关望漸賒。","行看轉牛斗，持此報張华。"]', '诗', 'shi', '', NULL, '送豐城王少府 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40eead5d-1119-4d45-b4c5-37152b06a285', '送鄭州周司空', '送鄭州周司空', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["漢國臨清渭，京城枕濁河。","居人下珠淚，賓御促驪歌。","望極關山遠，秋深煙霧多。","唯餘三五夕，明月暫經過。"]', '["漢国臨清渭，京城枕濁河。","居人下珠泪，賓御促驪歌。","望極关山远，秋深煙霧多。","唯餘三五夕，明月暫經過。"]', '诗', 'shi', '', NULL, '送鄭州周司空 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bbc999e-ece5-4074-9f2a-ad75a35be097', '送梓州周司功', '送梓州周司功', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["御溝一相送，征馬屢盤桓。","言笑方無日，離憂獨未寬。","舉杯聊勸酒，破涕暫爲歡。","別後風清夜，思君蜀路難。"]', '["御溝一相送，征马屢盤桓。","言笑方無日，離憂独未寬。","舉杯聊勸酒，破涕暫爲歡。","別後风清夜，思君蜀路难。"]', '诗', 'shi', '', NULL, '送梓州周司功 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5237dd8e-694f-481f-9a00-ef2248894867', '送楊處士反初卜居曲江', '送楊处士反初卜居曲江', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["雁門歸去遠，垂老脫袈裟。","蕭寺休爲客，曹溪便寄家。","綠琪千歲樹，黃槿四時花。","別怨應無限，門前桂水斜。"]', '["雁门归去远，垂老脫袈裟。","蕭寺休爲客，曹溪便寄家。","綠琪千歲樹，黄槿四时花。","別怨應無限，门前桂水斜。"]', '诗', 'shi', '', NULL, '送楊處士反初卜居曲江 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71bcf274-befb-4e57-b20c-f067fe4c6aa1', '途中', '途中', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["悠悠辭鼎邑，去去指金墉。","途路盈千里，山川亙百重。","風行常有地，雲出本多峰。","鬱鬱園中柳，亭亭山上松。","客心殊不樂，鄉淚獨無從。"]', '["悠悠辞鼎邑，去去指金墉。","途路盈千里，山川亙百重。","风行常有地，云出本多峰。","鬱鬱园中柳，亭亭山上松。","客心殊不乐，乡泪独無從。"]', '诗', 'shi', '', NULL, '途中 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a09c065-3355-47dc-8561-2d911a34b8dc', '送劉校書從軍', '送劉校书從軍', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["天將下三宮，星門召五戎。","坐謀資廟略，飛檄佇文雄。","赤土流星劍，烏號明月弓。","秋陰生蜀道，殺氣繞湟中。","風雨何年別，琴尊此日同。","離亭不可望，溝水自西東。"]', '["天將下三宮，星门召五戎。","坐謀資廟略，飞檄佇文雄。","赤土流星劍，烏號明月弓。","秋陰生蜀道，殺氣繞湟中。","风雨何年別，琴尊此日同。","離亭不可望，溝水自西东。"]', '诗', 'shi', '', NULL, '送劉校書從軍 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7599fb2b-43f5-41cd-88cb-20f0fe828e99', '遊廢觀', '游廢观', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["青幛倚丹田，荒涼數百年。","猶知小山桂，尚識大羅天。","藥敗金爐火，苔昏玉女泉。","歲時無壁畫，朝夕有階煙。","花柳三春節，江山四望懸。","悠然出塵網，從此狎神仙。"]', '["青幛倚丹田，荒涼數百年。","猶知小山桂，尚識大羅天。","藥敗金爐火，苔昏玉女泉。","歲时無壁畫，朝夕有階煙。","花柳三春節，江山四望懸。","悠然出塵網，從此狎神仙。"]', '诗', 'shi', '', NULL, '遊廢觀 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('837b2750-0ba8-421e-b124-3d6ab7381c16', '和石侍御山莊', '和石侍御山莊', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["煙霞非俗宇，巖壑只幽居。","水浸何曾畎，荒郊不復鋤。","影濃山樹密，香淺澤花疎。","闊塹防斜徑，平堤夾小渠。","蓮房若箇實，竹節幾重虛。","蕭然隔城市，酌醴焚枯魚。"]', '["煙霞非俗宇，巖壑只幽居。","水浸何曾畎，荒郊不复鋤。","影濃山樹密，香淺澤花疎。","闊塹防斜徑，平堤夾小渠。","蓮房若箇實，竹節幾重虛。","蕭然隔城市，酌醴焚枯鱼。"]', '诗', 'shi', '', NULL, '和石侍御山莊 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7afeddef-90a3-4908-b6fc-875d2a64c3de', '送李庶子致仕還洛', '送李庶子致仕還洛', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["此地傾城日，由來供帳華。","亭逢李廣騎，門接邵平瓜。","原野煙氛匝，關河遊望賒。","白雲斷巖岫，綠草覆江沙。","詔賜扶陽宅，人榮御史車。","灞池一相送，流涕向煙霞。"]', '["此地傾城日，由来供帳华。","亭逢李廣騎，门接邵平瓜。","原野煙氛匝，关河游望賒。","白云斷巖岫，綠草覆江沙。","詔賜扶陽宅，人榮御史车。","灞池一相送，流涕向煙霞。"]', '诗', 'shi', '', NULL, '送李庶子致仕還洛 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7fbbf94-16ae-4cbe-8ebb-05c240c60f5e', '早行', '早行', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["敞朗東方徹，闌干北斗斜。","地氣俄成霧，天雲漸作霞。","河流纔辨馬，巖路不容車。","阡陌經三歲，閭閻對五家。","露文沾細草，風影轉高花。","日月從來惜，關山猶自賒。"]', '["敞朗东方徹，闌干北斗斜。","地氣俄成霧，天云漸作霞。","河流纔辨马，巖路不容车。","阡陌經三歲，閭閻对五家。","露文沾細草，风影轉高花。","日月從来惜，关山猶自賒。"]', '诗', 'shi', '', NULL, '早行 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81ce81a6-2e44-432f-a440-9c548f3517ff', '和崔司空傷姬人', '和崔司空傷姬人', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["昔時南浦別，鶴怨寶琴弦。","今日東方至，鸞銷珠鏡前。","水流銜砌咽，月影向窗懸。","妝匣悽餘粉，熏爐滅舊煙。","晚庭摧玉樹，寒帳委金蓮。","佳人不再得，雲日幾千年。"]', '["昔时南浦別，鹤怨寶琴弦。","今日东方至，鸾銷珠镜前。","水流銜砌咽，月影向窗懸。","妝匣悽餘粉，熏爐滅旧煙。","晚庭摧玉樹，寒帳委金蓮。","佳人不再得，云日幾千年。"]', '诗', 'shi', '', NULL, '和崔司空傷姬人 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db33d521-9935-4748-a166-743e40cf4ab7', '和騫右丞省中暮望', '和騫右丞省中暮望', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["故事閒臺閣，仙門藹已深。","舊章窺複道，雲幌肅重陰。","玄律葭灰變，青陽斗柄臨。","年光搖樹色，春氣繞蘭心。","風響高窗度，流痕曲岸侵。","天門總樞轄，人鏡辨衣簪。","日暮南宮靜，瑤華振雅音。"]', '["故事閒台閣，仙门藹已深。","旧章窺複道，云幌肅重陰。","玄律葭灰变，青陽斗柄臨。","年光搖樹色，春氣繞蘭心。","风响高窗度，流痕曲岸侵。","天门總樞轄，人镜辨衣簪。","日暮南宮静，瑤华振雅音。"]', '诗', 'shi', '', NULL, '和騫右丞省中暮望 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('082bf240-136b-498f-88a4-48b1a1ac3c6c', '和酬虢州李司法', '和酬虢州李司法', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["唇齒標形勝，關河壯邑居。","寒山抵方伯，秋水面鴻臚。","君子從遊宦，忘情任卷舒。","風霜下刀筆，軒蓋擁門閭。","平野芸黃遍，長洲鴻雁初。","菊花宜泛酒，浦葉好裁書。","昔我芝蘭契，悠然雲雨疎。","非君重千里，誰有惠雙魚。"]', '["唇齒標形勝，关河壯邑居。","寒山抵方伯，秋水面鴻臚。","君子從游宦，忘情任卷舒。","风霜下刀笔，軒蓋擁门閭。","平野芸黄遍，长洲鴻雁初。","菊花宜泛酒，浦葉好裁书。","昔我芝蘭契，悠然云雨疎。","非君重千里，誰有惠雙鱼。"]', '诗', 'shi', '', NULL, '和酬虢州李司法 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85f36d32-337d-440a-8317-a61d3d3595cc', '和鄭讎校內省眺矚思鄉懷友', '和鄭讎校內省眺矚思乡懷友', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["銅門初下辟，石館始沈研。","遊霧千金字，飛雲五色牋。","樓臺橫紫極，城闕俯青田。","暄入瑤房裏，春回玉宇前。","霞文埋落照，風物澹歸煙。","翰墨三餘隙，關山四望懸。","頹峰暌酌羽，流水曠鳴絃。","雖欣承白雪，終恨隔青天。"]', '["銅门初下辟，石館始沈研。","游霧千金字，飞云五色牋。","楼台橫紫極，城闕俯青田。","暄入瑤房裏，春回玉宇前。","霞文埋落照，风物澹归煙。","翰墨三餘隙，关山四望懸。","頹峰暌酌羽，流水曠鳴絃。","雖欣承白雪，終恨隔青天。"]', '诗', 'shi', '', NULL, '和鄭讎校內省眺矚思鄉懷友 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed2a08a5-1d28-4144-a920-faee72408b45', '和旻上人傷果禪師', '和旻上人傷果禪師', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["淨業初中日，浮生大小年。","無人本無我，非後亦非前。","簫鼓旁喧地，龍蛇直映天。","法門摧棟宇，覺海破舟船。","書鎮秦王餉，經文宋國傳。","聲華周百億，風烈被三千。","蕪沒青園寺，荒涼紫陌田。","德音殊未遠，拱木已生煙。"]', '["淨業初中日，浮生大小年。","無人本無我，非後亦非前。","簫鼓旁喧地，龙蛇直映天。","法门摧棟宇，覺海破舟船。","书鎮秦王餉，經文宋国傳。","声华周百億，风烈被三千。","蕪沒青园寺，荒涼紫陌田。","德音殊未远，拱木已生煙。"]', '诗', 'shi', '', NULL, '和旻上人傷果禪師 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('952ec2cf-b0ac-4fc9-b83e-90b60ab4c4a9', '和劉侍郎入隆唐觀', '和劉侍郎入隆唐观', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["福地陰陽合，仙都日月開。","山川臨四險，城樹隱三臺。","伏檻排雲出，飛軒遶澗回。","參差凌倒影，瀟灑軼浮埃。","百果珠爲實，羣峰錦作苔。","懸蘿暗疑霧，瀑布響成雷。","方士燒丹液，真人泛玉杯。","還如問桃水，更似得蓬萊。","漢帝求仙日，相如作賦才。","自然金石奏，何必上天台。"]', '["福地陰陽合，仙都日月开。","山川臨四險，城樹隐三台。","伏檻排云出，飞軒遶澗回。","參差凌倒影，瀟灑軼浮埃。","百果珠爲實，羣峰錦作苔。","懸蘿暗疑霧，瀑布响成雷。","方士燒丹液，真人泛玉杯。","還如问桃水，更似得蓬萊。","漢帝求仙日，相如作賦才。","自然金石奏，何必上天台。"]', '诗', 'shi', '', NULL, '和劉侍郎入隆唐觀 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6b3b553-be08-42d5-bc7c-fcce3348cb0d', '和輔先入昊天觀星瞻', '和輔先入昊天观星瞻', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["遁甲爰皇里，星占太乙宮。","天門開奕奕，佳氣鬱蔥蔥。","碧落三乾外，黃圖四海中。","邑居環若水，城闕抵新豐。","玉檻崑崙側，金樞地軸東。","上真朝北斗，元始詠南風。","漢君祠五帝，淮王禮八公。","道書編竹簡，靈液灌梧桐。","草茂瓊階綠，花繁寶樹紅。","石樓紛似畫，地鏡淼如空。","桑海年應積，桃源路不窮。","黃軒若有問，三月住崆峒。"]', '["遁甲爰皇里，星占太乙宮。","天门开奕奕，佳氣鬱蔥蔥。","碧落三乾外，黄圖四海中。","邑居环若水，城闕抵新豐。","玉檻崑崙側，金樞地軸东。","上真朝北斗，元始詠南风。","漢君祠五帝，淮王禮八公。","道书編竹簡，靈液灌梧桐。","草茂瓊階綠，花繁寶樹紅。","石楼紛似畫，地镜淼如空。","桑海年應積，桃源路不窮。","黄軒若有问，三月住崆峒。"]', '诗', 'shi', '', NULL, '和輔先入昊天觀星瞻 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c262982e-59e4-4fd5-b435-31997a5aa6c6', '和劉長史荅十九兄', '和劉长史荅十九兄', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["帝堯平百姓，高祖宅三秦。","子弟分河岳，衣冠動縉紳。","盛名恆不隕，歷代幾相因。","街巷塗山曲，門閭洛水濱。","五龍金作友，一子玉爲人。","寶劍豐城氣，明珠魏國珍。","風標自落落，文質且彬彬。","共許刁元亮，同推周伯仁。","石城俯天闕，鍾阜對江津。","驥足方遐騁，狼心獨未馴。","鼓鼙鳴九域，風火集重闉。","城勢餘三板，兵威乏四鄰。","居然混玉石，直置保松筠。","耿介酬天子，危言數賊臣。","鍾儀琴未奏，蘇武節猶新。","受祿寧辭死，揚名不顧身。","精誠動天地，忠義感明神。","怪鳥俄垂翼，修蛇竟暴鱗。","來朝拜休命，述職下梁岷。","善政馳金馬，嘉聲繞玉輪。","三荆忽有贈，四海更相親。","宮徵諧鳴石，光輝掩燭銀。","山川遙滿目，零露坐沾巾。","友愛光天下，恩波浹後塵。","懦夫仰高節，下里繼陽春。"]', '["帝堯平百姓，高祖宅三秦。","子弟分河岳，衣冠动縉紳。","盛名恆不隕，歷代幾相因。","街巷塗山曲，门閭洛水濱。","五龙金作友，一子玉爲人。","寶劍豐城氣，明珠魏国珍。","风標自落落，文質且彬彬。","共許刁元亮，同推周伯仁。","石城俯天闕，鍾阜对江津。","驥足方遐騁，狼心独未馴。","鼓鼙鳴九域，风火集重闉。","城勢餘三板，兵威乏四鄰。","居然混玉石，直置保松筠。","耿介酬天子，危言數賊臣。","鍾儀琴未奏，蘇武節猶新。","受祿寧辞死，揚名不顧身。","精誠动天地，忠義感明神。","怪鸟俄垂翼，修蛇竟暴鱗。","来朝拜休命，述職下梁岷。","善政驰金马，嘉声繞玉輪。","三荆忽有贈，四海更相親。","宮徵諧鳴石，光輝掩燭銀。","山川遙满目，零露坐沾巾。","友愛光天下，恩波浹後塵。","懦夫仰高節，下里繼陽春。"]', '诗', 'shi', '', NULL, '和劉長史荅十九兄 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('957f6814-e4c7-4d03-b8bc-9370952dbb05', '夜送趙縱', '夜送趙縱', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["趙氏連城璧，由來天下傳。","送君還舊府，明月滿前川。"]', '["趙氏連城璧，由来天下傳。","送君還旧府，明月满前川。"]', '诗', 'shi', '', NULL, '夜送趙縱 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdab1a54-9805-4c24-a89a-4b9c58594cf4', '息夫人', '息夫人', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["可憐楚破息，腸斷息夫人。","仍爲泉下骨，不作楚王嬪。","楚王寵莫盛，息君情更親。","情親怨生別，一朝俱殺身。"]', '["可怜楚破息，腸斷息夫人。","仍爲泉下骨，不作楚王嬪。","楚王寵莫盛，息君情更親。","情親怨生別，一朝俱殺身。"]', '诗', 'shi', '', NULL, '息夫人 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa42d2ac-f630-4aa6-b93b-65ebba9e3d9a', '初到陸渾山莊', '初到陸渾山莊', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["授衣感窮節，策馬凌伊關。","歸齊逸人趣，日覺秋琴閑。","寒露衰北阜，夕陽破東山。","浩歌步榛樾，棲鳥隨我還。"]', '["授衣感窮節，策马凌伊关。","归齊逸人趣，日覺秋琴闲。","寒露衰北阜，夕陽破东山。","浩歌步榛樾，棲鸟隨我還。"]', '诗', 'shi', '', NULL, '初到陸渾山莊 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2846a406-001c-45f8-824e-a5cf45523500', '夜飲東亭', '夜饮东亭', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["春泉鳴大壑，皓月吐層岑。","岑壑景色佳，慰我遠遊心。","暗芳足幽氣，驚棲多衆音。","高興南山曲，長謠橫素琴。"]', '["春泉鳴大壑，皓月吐層岑。","岑壑景色佳，慰我远游心。","暗芳足幽氣，驚棲多衆音。","高兴南山曲，长謠橫素琴。"]', '诗', 'shi', '', NULL, '夜飲東亭 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7637858b-ae90-4d68-9696-83eebfd4770f', '芳樹', '芳樹', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["何地早芳菲，宛在長門殿。","夭桃色若綬，穠李光如練。","啼鳥弄花疎，遊蜂飲香遍。","歎息春風起，飄零君不見。"]', '["何地早芳菲，宛在长门殿。","夭桃色若綬，穠李光如練。","啼鸟弄花疎，游蜂饮香遍。","歎息春风起，飄零君不见。"]', '诗', 'shi', '', NULL, '芳樹 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90440b5c-fb49-4153-8cb1-87680ecbe3b4', '送趙六貞固', '送趙六貞固', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["目斷南浦雲，心醉東郊柳。","怨別此何時，春芳來已久。","與君共時物，盡此盈樽酒。","始願今不從，春風戀攜手。"]', '["目斷南浦云，心醉东郊柳。","怨別此何时，春芳来已久。","與君共时物，尽此盈樽酒。","始願今不從，春风戀携手。"]', '诗', 'shi', '', NULL, '送趙六貞固 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('624fb484-7d7a-4a63-b972-c2f35c3ca313', '題張老松樹', '題張老松樹', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["歲晚東巖下，周顧何悽惻。","日落西山陰，衆草起寒色。","中有喬松樹，使我長歎息。","百尺無寸枝，一生自孤直。"]', '["歲晚东巖下，周顧何悽惻。","日落西山陰，衆草起寒色。","中有喬松樹，使我长歎息。","百尺無寸枝，一生自孤直。"]', '诗', 'shi', '', NULL, '題張老松樹 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62527274-ee49-4fd2-a641-2d6822c9f033', '別之望後獨宿藍田山莊', '別之望後独宿藍田山莊', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["鶺鴒有舊曲，調苦不成歌。","自歎兄弟少，常嗟離別多。","爾尋北京路，予臥南山阿。","泉晚更幽咽，雲秋尚嵯峨。","藥欄聽蟬噪，書幌見禽過。","愁至願甘寢，其如鄉夢何。"]', '["鶺鴒有旧曲，調苦不成歌。","自歎兄弟少，常嗟離別多。","爾尋北京路，予臥南山阿。","泉晚更幽咽，云秋尚嵯峨。","藥欄听蟬噪，书幌见禽過。","愁至願甘寢，其如乡梦何。"]', '诗', 'shi', '', NULL, '別之望後獨宿藍田山莊 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1987a53d-8e9c-40de-8f6a-dea28f1c64c2', '浣紗篇贈陸上人', '浣紗篇贈陸上人', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["越女顏如花，越王聞浣紗。","國微不自寵，獻作吳宮娃。","山藪半潛匿，苧蘿更蒙遮。","一行霸句踐，再笑傾夫差。","豔色奪人目，斆嚬亦相誇。","一朝還舊都，靚粧尋若耶。","鳥驚入松網，魚畏沈荷花。","始覺冶容妄，方悟羣心邪。","欽子秉幽意，世人共稱嗟。","願言托君懷，倘類蓬生麻。","家住雷門曲，高閣凌飛霞。","淋漓翠羽帳，旖旎采雲軍。","春風豔楚舞，秋月纏胡笳。","自昔專嬌愛，襲玩唯矜奢。","達本知空寂，棄彼猶泥沙。","永割偏執性，自長薰修芽。","攜妾不障道，來止妾西家。"]', '["越女顏如花，越王闻浣紗。","国微不自寵，獻作吳宮娃。","山藪半潛匿，苧蘿更蒙遮。","一行霸句踐，再笑傾夫差。","豔色奪人目，斆嚬亦相誇。","一朝還旧都，靚粧尋若耶。","鸟驚入松網，鱼畏沈荷花。","始覺冶容妄，方悟羣心邪。","欽子秉幽意，世人共稱嗟。","願言托君懷，倘類蓬生麻。","家住雷门曲，高閣凌飞霞。","淋漓翠羽帳，旖旎采云軍。","春风豔楚舞，秋月纏胡笳。","自昔專嬌愛，襲玩唯矜奢。","達本知空寂，棄彼猶泥沙。","永割偏執性，自长薰修芽。","携妾不障道，来止妾西家。"]', '诗', 'shi', '', NULL, '浣紗篇贈陸上人 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('097e4aee-c82b-4d38-9ea4-b5ac775290dc', '雨從箕山來', '雨從箕山来', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["雨從箕山來，倏與飄風度。","晴明西峰日，綠縟南溪樹。","此時客精廬，幸蒙真僧顧。","深入清淨理，妙斷往來趣。","意得兩契如，言盡共忘喻。","觀花寂不動，聞鳥懸可悟。","向夕聞天香，淹留不能去。"]', '["雨從箕山来，倏與飄风度。","晴明西峰日，綠縟南溪樹。","此时客精廬，幸蒙真僧顧。","深入清淨理，妙斷往来趣。","意得兩契如，言尽共忘喻。","观花寂不动，闻鸟懸可悟。","向夕闻天香，淹留不能去。"]', '诗', 'shi', '', NULL, '雨從箕山來 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2d614c6-6fa6-4f1f-b191-e5e0e49c3154', '初至崖口', '初至崖口', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["崖口衆山斷，嶔崟聳天壁。","氣衝落日紅，影入春潭碧。","錦繢織苔蘚，丹青畫松石。","水禽泛容與，巖花飛的皪。","微路從此深，我來限于役。","惆悵情未已，羣峰暗將夕。"]', '["崖口衆山斷，嶔崟聳天壁。","氣衝落日紅，影入春潭碧。","錦繢织苔蘚，丹青畫松石。","水禽泛容與，巖花飞的皪。","微路從此深，我来限于役。","惆悵情未已，羣峰暗將夕。"]', '诗', 'shi', '', NULL, '初至崖口 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bddb506-d53e-414b-bb71-3165b72ee162', '自湘源至潭州衡山縣', '自湘源至潭州衡山縣', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["浮湘沿迅湍，逗浦凝遠盼。","漸見江勢闊，行嗟水流漫。","赤岸雜雲霞，綠竹緣溪澗。","向背羣山轉，應接良景晏。","沓障連夜猿，平沙覆陽雁。","紛吾望闕客，歸橈速已慣。","中道方泝洄，遲念自茲撰。","賴欣衡陽美，持以蠲憂患。"]', '["浮湘沿迅湍，逗浦凝远盼。","漸见江勢闊，行嗟水流漫。","赤岸杂云霞，綠竹緣溪澗。","向背羣山轉，應接良景晏。","沓障連夜猿，平沙覆陽雁。","紛吾望闕客，归橈速已慣。","中道方泝洄，遲念自茲撰。","賴欣衡陽美，持以蠲憂患。"]', '诗', 'shi', '', NULL, '自湘源至潭州衡山縣 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87eb79bf-7f11-4152-abb9-a20e0eb24259', '入崖口五渡寄李適', '入崖口五渡寄李適', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["抱琴登絕壑，伐木泝清川。","路極意謂盡，勢回趣轉綿。","人遠草木秀，山深雲景鮮。","余負海嶠情，自昔微尚然。","彌曠十餘載，今來宛仍前。","未窺仙源極，獨進野人船。","時攀乳竇憩，屢薄天窗眠。","夜弦響松月，朝楫弄苔泉。","因冥象外理，永謝區中緣。","碧潭可遺老，丹砂堪學仙。","莫使馳光暮，空令歸鶴憐。"]', '["抱琴登絕壑，伐木泝清川。","路極意謂尽，勢回趣轉綿。","人远草木秀，山深云景鲜。","余負海嶠情，自昔微尚然。","彌曠十餘載，今来宛仍前。","未窺仙源極，独進野人船。","时攀乳竇憩，屢薄天窗眠。","夜弦响松月，朝楫弄苔泉。","因冥象外理，永謝區中緣。","碧潭可遺老，丹砂堪学仙。","莫使驰光暮，空令归鹤怜。"]', '诗', 'shi', '', NULL, '入崖口五渡寄李適 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba43da13-4f89-4d65-a1bf-62efa5f5d6c0', '洞庭湖', '洞庭湖', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["地盡天水合，朝及洞庭湖。","初日當中涌，莫辨東西隅。","晶耀目何在，瀅熒心欲無。","靈光晏海若，游氣耿天吳。","張樂軒皇至，征苗夏禹徂。","楚臣悲落葉，堯女泣蒼梧。","野積九江潤，山通五嶽圖。","風恬魚自躍，雲夕雁相呼。","獨此臨泛漾，浩將人代殊。","永言洗氛濁，卒歲爲清娛。","要使功成退，徒勞越大夫。"]', '["地尽天水合，朝及洞庭湖。","初日當中涌，莫辨东西隅。","晶耀目何在，瀅熒心欲無。","靈光晏海若，游氣耿天吳。","張乐軒皇至，征苗夏禹徂。","楚臣悲落葉，堯女泣蒼梧。","野積九江潤，山通五嶽圖。","风恬鱼自躍，云夕雁相呼。","独此臨泛漾，浩將人代殊。","永言洗氛濁，卒歲爲清娛。","要使功成退，徒勞越大夫。"]', '诗', 'shi', '', NULL, '洞庭湖 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0a304ef-b9f1-4f9c-b9e3-9890a1ca86d0', '景龍四年春祠海', '景龙四年春祠海', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["肅事祠春溟，宵齋洗蒙慮。","雞鳴見日出，鷺下驚濤鶩。","地闊八荒近，天回百川澍。","筵端接空曲，目外唯雰霧。","暖氣物象來，周遊晦明互。","致牲匪玄享，禋滌期靈煦。","的的波際禽，沄沄島間樹。","安期今何在，方丈蔑尋路。","仙事與世隔，冥搜徒已屢。","四明背羣山，遺老莫辨處。","撫中良自慨，弱齡忝恩遇。","三入文史林，兩拜神仙署。","雖歎出關遠，始知臨海趣。","賞來空自多，理勝孰能喻。","留楫竟何待，徙倚忽云暮。"]', '["肅事祠春溟，宵斋洗蒙慮。","雞鳴见日出，鷺下驚濤鶩。","地闊八荒近，天回百川澍。","筵端接空曲，目外唯雰霧。","暖氣物象来，周游晦明互。","致牲匪玄享，禋滌期靈煦。","的的波際禽，沄沄島间樹。","安期今何在，方丈蔑尋路。","仙事與世隔，冥搜徒已屢。","四明背羣山，遺老莫辨处。","撫中良自慨，弱齡忝恩遇。","三入文史林，兩拜神仙署。","雖歎出关远，始知臨海趣。","賞来空自多，理勝孰能喻。","留楫竟何待，徙倚忽云暮。"]', '诗', 'shi', '', NULL, '景龍四年春祠海 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9957052-6982-4ff5-9e8c-5472eaddfc6b', '溫泉莊臥病寄楊七炯', '溫泉莊臥病寄楊七炯', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["移疾臥茲嶺，寥寥倦幽獨。","賴有嵩丘山，高枕長在目。","茲山棲靈異，朝夜翳雲族。","是日濛雨晴，返景入巖谷。","冪冪澗畔草，青青山下木。","此意方無窮，環顧悵林麓。","伊洛何悠漫，川原信重複。","夏餘鳥獸蕃，秋末禾黍熟。","秉願守樊圃，歸閑欣藝牧。","惜無載酒人，徒把涼泉掬。"]', '["移疾臥茲嶺，寥寥倦幽独。","賴有嵩丘山，高枕长在目。","茲山棲靈異，朝夜翳云族。","是日濛雨晴，返景入巖谷。","冪冪澗畔草，青青山下木。","此意方無窮，环顧悵林麓。","伊洛何悠漫，川原信重複。","夏餘鸟獸蕃，秋末禾黍熟。","秉願守樊圃，归闲欣藝牧。","惜無載酒人，徒把涼泉掬。"]', '诗', 'shi', '', NULL, '溫泉莊臥病寄楊七炯 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08aa0cab-ac13-486b-b6fa-42ef81a09899', '荅田徵君', '荅田徵君', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["家臨清溪水，溪水繞盤石。","綠蘿四面垂，褭褭百餘尺。","風泉度絲管，苔蘚鋪茵席。","傳聞潁陽人，霞外漱靈液。","忽枉巖中翰，吟望朝復夕。","何當遂遠遊，物色候逋客。"]', '["家臨清溪水，溪水繞盤石。","綠蘿四面垂，褭褭百餘尺。","风泉度絲管，苔蘚鋪茵席。","傳闻潁陽人，霞外漱靈液。","忽枉巖中翰，吟望朝复夕。","何當遂远游，物色候逋客。"]', '诗', 'shi', '', NULL, '荅田徵君 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d96d2ca0-c18e-4a72-abc3-b3d015bac44c', '自衡陽至韶州謁能禪師', '自衡陽至韶州謁能禪師', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["謫居竄炎壑，孤帆淼不繫。","別家萬里餘，流目三春際。","猿啼山館曉，虹飲江皐霽。","湘岸竹泉幽，衡峯石囷閉。","嶺嶂窮攀越，風濤極沿濟。","吾師在韶陽，欣此得躬詣。","洗慮賓空寂，焚香結精誓。","願以有漏軀，聿薰無生慧。","物用益沖曠，心源日閑細。","伊我獲此途，遊道回晚計。","宗師信捨法，擯落文史藝。","坐禪羅浮中，尋異窮海裔。","何辭禦魑魅，自可乘炎癘。","回首望舊鄉，雲林浩虧蔽。","不作離別苦，歸期多年歲。"]', '["謫居竄炎壑，孤帆淼不繫。","別家万里餘，流目三春際。","猿啼山館晓，虹饮江皐霽。","湘岸竹泉幽，衡峯石囷閉。","嶺嶂窮攀越，风濤極沿濟。","吾師在韶陽，欣此得躬詣。","洗慮賓空寂，焚香結精誓。","願以有漏軀，聿薰無生慧。","物用益沖曠，心源日闲細。","伊我獲此途，游道回晚計。","宗師信捨法，擯落文史藝。","坐禪羅浮中，尋異窮海裔。","何辞禦魑魅，自可乘炎癘。","回首望旧乡，云林浩虧蔽。","不作離別苦，归期多年歲。"]', '诗', 'shi', '', NULL, '自衡陽至韶州謁能禪師 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b02d795c-799a-4d28-b5aa-26d833736bde', '見南山夕陽召監師不至', '见南山夕陽召監師不至', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["夕陽黯晴碧，山翠互明滅。","此中意無限，要與開士說。","徒鬱仲舉思，詎迴道林轍。","孤興欲待誰，待此湖上月。"]', '["夕陽黯晴碧，山翠互明滅。","此中意無限，要與开士说。","徒鬱仲舉思，詎迴道林轍。","孤兴欲待誰，待此湖上月。"]', '诗', 'shi', '', NULL, '見南山夕陽召監師不至 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('563eb155-69f0-40ec-9bbb-105167dbc4ac', '遊法華寺', '游法华寺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["薄游京都日，遙羨稽山名。","分刺江海郡，朅來徵素情。","松露洗心眷，象筵敷念誠。","薄雲界青嶂，皎日鶱朱甍。","苔澗深不測，竹房閑且清。","感真六象見，垂兆二𪅝鳴。","古今信靈跡，中州莫與京。","林巘永棲業，豈伊佐一生。","浮悟雖已久，事試去來成。","觀念幸相續，庶幾最後明。"]', '["薄游京都日，遙羨稽山名。","分刺江海郡，朅来徵素情。","松露洗心眷，象筵敷念誠。","薄云界青嶂，皎日鶱朱甍。","苔澗深不測，竹房闲且清。","感真六象见，垂兆二𪅝鳴。","古今信靈跡，中州莫與京。","林巘永棲業，豈伊佐一生。","浮悟雖已久，事試去来成。","观念幸相續，庶幾最後明。"]', '诗', 'shi', '', NULL, '遊法華寺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a9362bf-5d80-4528-af3a-96c7cb7d0848', '宿雲門寺', '宿云门寺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["雲門若邪裏，泛鷁路纔通。","夤緣綠篠岸，遂得青蓮宮。","天香衆壑滿，夜梵前山空。","漾漾潭際月，颸飀杉上風。","茲焉多嘉遯，數子今莫同。","鳳歸慨處士，鹿化聞仙公。","樵路鄭州北，舉井阿巖東。","永夜豈云寐，曙華忽葱蘢。","谷鳥囀尚澀，源桃驚未紅。","再來期春暮，當造林端窮。","庶幾蹤謝客，開山投剡中。"]', '["云门若邪裏，泛鷁路纔通。","夤緣綠篠岸，遂得青蓮宮。","天香衆壑满，夜梵前山空。","漾漾潭際月，颸飀杉上风。","茲焉多嘉遯，數子今莫同。","鳳归慨处士，鹿化闻仙公。","樵路鄭州北，舉井阿巖东。","永夜豈云寐，曙华忽葱蘢。","谷鸟囀尚澀，源桃驚未紅。","再来期春暮，當造林端窮。","庶幾蹤謝客，开山投剡中。"]', '诗', 'shi', '', NULL, '宿雲門寺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e923cd3-3ab2-4e21-9cd8-09b732e339eb', '春湖古意', '春湖古意', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["院梅發向尺，園鳥復成曲。","落日遊南湖，果擲顏如玉。","含情不得語，轉盼知所屬。","惆悵未可歸，寧關須采菉。"]', '["院梅發向尺，园鸟复成曲。","落日游南湖，果擲顏如玉。","含情不得語，轉盼知所屬。","惆悵未可归，寧关須采菉。"]', '诗', 'shi', '', NULL, '春湖古意 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cefe7e6a-f5fc-4cee-bf22-17c832e3bf4a', '游陸渾南山自歇馬嶺到楓香林以詩代書荅李舍人適', '游陸渾南山自歇马嶺到楓香林以诗代书荅李舍人適', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["晨登歇馬嶺，遙望伏牛山。","孤出羣峰首，熊熊元氣間。","太和亦崔嵬，石扇橫閃倏。","細岑互攢倚，浮巘競奔蹙。","白雲遙入懷，青靄近可掬。","徒尋靈異跡，周顧愜心目。","晨拂鳥路行，暮投人煙宿。","稉稻遠彌秀，栗芋秋新熟。","石髓非一巖，藥苗乃萬族。","間關踏雲雨，繚繞緣水木。","西見商山芝，南到楚鄉竹。","楚竹幽且深，半雜楓香林。","浩歌清潭曲，寄爾桃源心。"]', '["晨登歇马嶺，遙望伏牛山。","孤出羣峰首，熊熊元氣间。","太和亦崔嵬，石扇橫閃倏。","細岑互攢倚，浮巘競奔蹙。","白云遙入懷，青靄近可掬。","徒尋靈異跡，周顧愜心目。","晨拂鸟路行，暮投人煙宿。","稉稻远彌秀，栗芋秋新熟。","石髓非一巖，藥苗乃万族。","间关踏云雨，繚繞緣水木。","西见商山芝，南到楚乡竹。","楚竹幽且深，半杂楓香林。","浩歌清潭曲，寄爾桃源心。"]', '诗', 'shi', '', NULL, '游陸渾南山自歇馬嶺到楓香林以詩代書荅李舍人適 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab2b3f7a-4caf-4d5f-9615-79c2eeb1f0a1', '早發大庾嶺', '早發大庾嶺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["晨躋大庾險，驛鞍馳復息。","霧露晝未開，浩途不可測。","嵥起華夷界，信爲造化力。","歇鞍問徒旅，鄉關在西北。","出門怨別家，登嶺恨辭國。","自惟勗忠孝，斯罪懵所得。","皇明頗照洗，延議日紛惑。","兄弟遠淪居，妻子成異域。","羽翮傷已毀，童幼憐未識。","躊躕戀北顧，亭午晞霽色。","春煖陰梅花，瘴回陽鳥翼。","含沙緣澗聚，吻草依林植。","適蠻悲疾首，懷鞏淚沾臆。","感謝鵷鷺朝，勤修魑魅職。","生還倘非遠，誓擬酬恩德。"]', '["晨躋大庾險，驛鞍驰复息。","霧露晝未开，浩途不可測。","嵥起华夷界，信爲造化力。","歇鞍问徒旅，乡关在西北。","出门怨別家，登嶺恨辞国。","自惟勗忠孝，斯罪懵所得。","皇明頗照洗，延議日紛惑。","兄弟远淪居，妻子成異域。","羽翮傷已毀，童幼怜未識。","躊躕戀北顧，亭午晞霽色。","春煖陰梅花，瘴回陽鸟翼。","含沙緣澗聚，吻草依林植。","適蠻悲疾首，懷鞏泪沾臆。","感謝鵷鷺朝，勤修魑魅職。","生還倘非远，誓擬酬恩德。"]', '诗', 'shi', '', NULL, '早發大庾嶺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c736146d-7acb-4eb1-84ab-ce420bbbf057', '自洪府舟行直書其事', '自洪府舟行直书其事', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["仲春辭國門，畏途橫萬里。","越淮乘楚嶂，造江泛吳汜。","嚴程無休隙，日夜涉風水。","昔聞垂堂言，將誡千金子。","問余何奇剝，遷竄極炎鄙。","揆己道德餘，幼聞虛白旨。","貴身賤外物，抗跡遠塵軌。","朝遊伊水湄，夕臥箕山趾。","妙年拙自晦，皎潔弄文史。","謬辱紫泥書，揮翰青雲裏。","事往每增傷，寵來常誓止。","銘骨懷報稱，逆鱗讓金紫。","安位釁潛搆，退耕禍猶起。","棲巖實吾策，觸藩誠內恥。","濟濟同時人，台庭鳴劒履。","愚以卑自衞，兀坐去沈滓。","迨茲理已極，竊位申知己。","羣議負宿心，獲戾光華始。","黃金忽銷鑠，素業坐淪毀。","浩歎誣平生，何獨戀枌梓。","浦樹浮鬱鬱，皐蘭覆靡靡。","百越去魂斷，九疑望心死。","未盡匡阜遊，遠欣羅浮美。","周旋本師訓，佩服無生理。","異國多靈仙，幽探忘年紀。","敝廬嵩山下，空谷茂蘭芷。","悠悠南溟遠，採掇長已矣。"]', '["仲春辞国门，畏途橫万里。","越淮乘楚嶂，造江泛吳汜。","嚴程無休隙，日夜涉风水。","昔闻垂堂言，將誡千金子。","问余何奇剝，遷竄極炎鄙。","揆己道德餘，幼闻虛白旨。","貴身賤外物，抗跡远塵軌。","朝游伊水湄，夕臥箕山趾。","妙年拙自晦，皎潔弄文史。","謬辱紫泥书，揮翰青云裏。","事往每增傷，寵来常誓止。","銘骨懷報稱，逆鱗讓金紫。","安位釁潛搆，退耕禍猶起。","棲巖實吾策，觸藩誠內恥。","濟濟同时人，台庭鳴劒履。","愚以卑自衞，兀坐去沈滓。","迨茲理已極，竊位申知己。","羣議負宿心，獲戾光华始。","黄金忽銷鑠，素業坐淪毀。","浩歎誣平生，何独戀枌梓。","浦樹浮鬱鬱，皐蘭覆靡靡。","百越去魂斷，九疑望心死。","未尽匡阜游，远欣羅浮美。","周旋本師訓，佩服無生理。","異国多靈仙，幽探忘年紀。","敝廬嵩山下，空谷茂蘭芷。","悠悠南溟远，採掇长已矣。"]', '诗', 'shi', '', NULL, '自洪府舟行直書其事 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bff19a0-00a9-441d-902e-06058fa045e8', '下桂江縣黎壁', '下桂江縣黎壁', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["放溜覿前漵，連山分上干。","江回雲壁轉，天小霧峯攢。","吼沫跳急浪，合流環峻灘。","欹離出漩劃，繚繞避渦盤。","舟子怯桂水，最言斯路難。","吾生抱忠信，吟嘯自安閑。","旦別已千歲，夜愁勞萬端。","企予見夜月，委曲破林巒。","潭曠竹煙盡，洲香橘露團。","豈傲夙所好，對之與俱歡。","思君罷琴酌，泣此夜漫漫。"]', '["放溜覿前漵，連山分上干。","江回云壁轉，天小霧峯攢。","吼沫跳急浪，合流环峻灘。","欹離出漩劃，繚繞避渦盤。","舟子怯桂水，最言斯路难。","吾生抱忠信，吟嘯自安闲。","旦別已千歲，夜愁勞万端。","企予见夜月，委曲破林巒。","潭曠竹煙尽，洲香橘露團。","豈傲夙所好，对之與俱歡。","思君罷琴酌，泣此夜漫漫。"]', '诗', 'shi', '', NULL, '下桂江縣黎壁 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3744261-baec-4685-967c-0fa09ff5b9c4', '奉使嵩山途經緱嶺', '奉使嵩山途經緱嶺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["侵星發洛城，城中歌吹聲。","畢景至緱嶺，嶺上煙霞生。","草樹饒野意，山川多古情。","大隱德所薄，歸來可退耕。"]', '["侵星發洛城，城中歌吹声。","畢景至緱嶺，嶺上煙霞生。","草樹饒野意，山川多古情。","大隐德所薄，归来可退耕。"]', '诗', 'shi', '', NULL, '奉使嵩山途經緱嶺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d34ce5-4731-4099-98e1-7debaf6078ae', '傷王七秘書監寄呈揚州陸長史通簡府僚廣陵以廣好事', '傷王七秘书監寄呈揚州陸长史通簡府僚廣陵以廣好事', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["王氏貴先宗，衡門棲道風。","傳心晤有物，秉化遊無窮。","學奧九流異，機玄三語同。","書乃墨場絕，文稱詞伯雄。","白屋藩魏主，蒼生期謝公。","一祗賢良詔，遂謁承明宮。","補衮望奚塞，尊儒位未充。","罷官七門裏，歸老一丘中。","嘗忝長者轍，微言私謂通。","我行會稽郡，路出廣陵東。","物在人已矣，都疑淮海空。"]', '["王氏貴先宗，衡门棲道风。","傳心晤有物，秉化游無窮。","学奧九流異，機玄三語同。","书乃墨場絕，文稱词伯雄。","白屋藩魏主，蒼生期謝公。","一祗賢良詔，遂謁承明宮。","補衮望奚塞，尊儒位未充。","罷官七门裏，归老一丘中。","嘗忝长者轍，微言私謂通。","我行會稽郡，路出廣陵东。","物在人已矣，都疑淮海空。"]', '诗', 'shi', '', NULL, '傷王七秘書監寄呈揚州陸長史通簡府僚廣陵以廣好事 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb4e6da2-b504-4eb3-9f74-60da168ca9a7', '使至嵩山尋杜四不遇慨然復傷田洗馬韓觀主因以題壁贈杜侯杜四', '使至嵩山尋杜四不遇慨然复傷田洗马韓观主因以題壁贈杜侯杜四', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["洛橋瞻太室，期子在雲煙。","歸來不相見，孤賞弄寒泉。","與君闊松石，于茲二十年。","田公謝昭世，韓子秘幽埏。","憶昔同攜手，山棲接二賢。","笙歌入玄地，詩酒坐寥天。","舊友悉零落，罷琴私自憐。","逝者非藥誤，餐霞意可全。","爲余理還策，相與事靈仙。"]', '["洛橋瞻太室，期子在云煙。","归来不相见，孤賞弄寒泉。","與君闊松石，于茲二十年。","田公謝昭世，韓子秘幽埏。","憶昔同携手，山棲接二賢。","笙歌入玄地，诗酒坐寥天。","旧友悉零落，罷琴私自怜。","逝者非藥誤，餐霞意可全。","爲余理還策，相與事靈仙。"]', '诗', 'shi', '', NULL, '使至嵩山尋杜四不遇慨然復傷田洗馬韓觀主因以題壁贈杜侯杜四 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48bfe21e-41a1-4e70-865a-322188c27a3e', '翫郡齋海榴', '翫郡斋海榴', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["澤國韶氣早，開簾延霽天。","野禽宵未囀，山蜚晝仍眠。","目茲海榴發，列暎巖楹前。","熠爚禦風靜，葳蕤含景鮮。","清晨綠堪佩，亭午丹欲然。","昔忝金閨籍，嘗見玉池蓮。","未若宗族地，更逢榮耀全。","南金雖自貴，賀賞詎能遷。","撫躬萬里絕，豈染一朝妍。","徒緣滯遐郡，常是惜流年。","越俗鄙章甫，捫心空自憐。"]', '["澤国韶氣早，开簾延霽天。","野禽宵未囀，山蜚晝仍眠。","目茲海榴發，列暎巖楹前。","熠爚禦风静，葳蕤含景鲜。","清晨綠堪佩，亭午丹欲然。","昔忝金閨籍，嘗见玉池蓮。","未若宗族地，更逢榮耀全。","南金雖自貴，賀賞詎能遷。","撫躬万里絕，豈染一朝妍。","徒緣滯遐郡，常是惜流年。","越俗鄙章甫，捫心空自怜。"]', '诗', 'shi', '', NULL, '翫郡齋海榴 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a130b9ea-0f41-4f06-8394-d9e6a053a27b', '長安路', '长安路', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["秦地平如掌，層城出雲漢。","樓閣九衢春，車馬千門旦。","綠柳開復合，紅塵聚還散。","日晚鬬雞場，經過狹斜看。"]', '["秦地平如掌，層城出云漢。","楼閣九衢春，车马千门旦。","綠柳开复合，紅塵聚還散。","日晚鬬雞場，經過狹斜看。"]', '诗', 'shi', '', NULL, '長安路 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c745c97-2a26-40cb-bc79-de9ca78abb77', '折楊柳', '折楊柳', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["玉樹朝日映，羅帳春風吹。","拭淚攀楊柳，長條宛地垂。","白花飛歷亂，黃鳥思參差。","妾自肝腸斷，傍人那得知。"]', '["玉樹朝日映，羅帳春风吹。","拭泪攀楊柳，长條宛地垂。","白花飞歷亂，黄鸟思參差。","妾自肝腸斷，傍人那得知。"]', '诗', 'shi', '', NULL, '折楊柳 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e450b85e-af1e-4bfc-ad52-deecdea08a4f', '有所思', '有所思', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["君子事行役，再空芳歲期。","美人曠遙佇，萬里浮雲思。","園桃綻紅豔，郊葉柔綠滋。","坐看長夏晚，秋月生羅帷。"]', '["君子事行役，再空芳歲期。","美人曠遙佇，万里浮云思。","园桃綻紅豔，郊葉柔綠滋。","坐看长夏晚，秋月生羅帷。"]', '诗', 'shi', '', NULL, '有所思 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('722a5190-983c-4b15-beae-49851178c7a4', '軍中人日登高贈房明府', '軍中人日登高贈房明府', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["幽郊昨夜陰風斷，頓覺朝來陽吹暖。","涇水橋南柳欲黃，杜陵城北花應滿。","長安昨夜寄春衣，短翮登茲一望歸。","聞道凱旋乘騎入，看君走馬見芳菲。"]', '["幽郊昨夜陰风斷，頓覺朝来陽吹暖。","涇水橋南柳欲黄，杜陵城北花應满。","长安昨夜寄春衣，短翮登茲一望归。","闻道凱旋乘騎入，看君走马见芳菲。"]', '诗', 'shi', '', NULL, '軍中人日登高贈房明府 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b129aaf4-a51b-4651-8c11-19391eb12d6f', '寒食還陸渾別業', '寒食還陸渾別業', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["洛陽城裏花如雪，陸渾山中今始發。","旦別河橋楊柳風，夕臥伊川桃李月。","伊川桃李正芳新，寒食山中酒復春。","野老不知堯舜力，酣歌一曲太平人。"]', '["洛陽城裏花如雪，陸渾山中今始發。","旦別河橋楊柳风，夕臥伊川桃李月。","伊川桃李正芳新，寒食山中酒复春。","野老不知堯舜力，酣歌一曲太平人。"]', '诗', 'shi', '', NULL, '寒食還陸渾別業 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11f43cfd-a277-41f9-b9b9-b3347f6a6be9', '寒食江州滿塘驛', '寒食江州满塘驛', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["去年上巳洛橋邊，今年寒食廬山曲。","遙憐鞏樹花應滿，復見吳洲草新綠。","吳洲春草蘭杜芳，感物思歸懷故鄉。","驛騎明朝宿何處？猿聲今夜斷君腸。"]', '["去年上巳洛橋邊，今年寒食廬山曲。","遙怜鞏樹花應满，复见吳洲草新綠。","吳洲春草蘭杜芳，感物思归懷故乡。","驛騎明朝宿何处？猿声今夜斷君腸。"]', '诗', 'shi', '', NULL, '寒食江州滿塘驛 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a79a0a-16e5-486d-8519-53f99a76a414', '至端州驛見杜五審言沈三佺期閻五朝隱王二無競題壁慨然成詠', '至端州驛见杜五審言沈三佺期閻五朝隐王二無競題壁慨然成詠', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["逐臣北地承嚴譴，謂到南中每相見。","豈意南中岐路多，千山萬水分鄉縣。","雲搖雨散各翻飛，海闊天長音信稀。","處處山川同瘴癘，自憐能得幾人歸。"]', '["逐臣北地承嚴譴，謂到南中每相见。","豈意南中岐路多，千山万水分乡縣。","云搖雨散各翻飞，海闊天长音信稀。","处处山川同瘴癘，自怜能得幾人归。"]', '诗', 'shi', '', NULL, '至端州驛見杜五審言沈三佺期閻五朝隱王二無競題壁慨然成詠 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60057685-5b50-4eb2-8b0f-c47fe8dbe4e2', '綠竹引', '綠竹引', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["青溪綠潭潭水側，修竹嬋娟同一色。","徒生僊實鳳不遊，老死空山人詎識。","妙年秉願逃俗紛，歸臥嵩丘弄白雲。","含情傲睨慰心目，何可一日無此君。"]', '["青溪綠潭潭水側，修竹嬋娟同一色。","徒生僊實鳳不游，老死空山人詎識。","妙年秉願逃俗紛，归臥嵩丘弄白云。","含情傲睨慰心目，何可一日無此君。"]', '诗', 'shi', '', NULL, '綠竹引 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d52444-8892-40d3-af0a-3ff50214e201', '明河篇', '明河篇', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["八月涼風天氣晶，萬里無雲河漢明。","昏見南樓清且淺，曉落西山縱復橫。","洛陽城闕天中起，長河夜夜千門裏。","複道連甍共蔽虧，畫堂瓊戶特相宜。","雲母帳前初泛濫，水精簾外轉逶迤。","倬彼昭回如練白，復出東城接南陌。","南陌征人去不歸，誰家今夜擣寒衣。","鴛鴦機上疎螢度，烏鵲橋邊一雁飛。","雁飛螢度愁難歇，坐見明河漸微沒。","已能舒卷任浮雲，不惜光輝讓流月。","明河可望不可親，願得乘槎一問津。","更將織女支機石，還訪成都賣卜人。"]', '["八月涼风天氣晶，万里無云河漢明。","昏见南楼清且淺，晓落西山縱复橫。","洛陽城闕天中起，长河夜夜千门裏。","複道連甍共蔽虧，畫堂瓊戶特相宜。","云母帳前初泛濫，水精簾外轉逶迤。","倬彼昭回如練白，复出东城接南陌。","南陌征人去不归，誰家今夜擣寒衣。","鴛鴦機上疎螢度，烏鵲橋邊一雁飞。","雁飞螢度愁难歇，坐见明河漸微沒。","已能舒卷任浮云，不惜光輝讓流月。","明河可望不可親，願得乘槎一问津。","更將织女支機石，還訪成都賣卜人。"]', '诗', 'shi', '', NULL, '明河篇 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49d170cf-fc74-4f8f-b207-b82d364091b7', '龍門應制', '龙门應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["宿雨霽氛埃，流雲度城闕。","河堤柳新翠，苑樹花先發。","洛陽花柳此時濃，山水樓臺暎幾重。","羣公拂霧朝翔鳳，天子乘春幸鑿龍。","鑿龍近出王城外，羽從琳琅擁軒蓋。","雲罕纔臨御水橋，天衣已入香山會。","山壁嶄巖斷復連，清流澄澈俯伊川。","雁塔遙遙綠波上，星龕奕奕翠微邊。","層巒舊長千尋木，遠壑初飛百丈泉。","綵仗蜺旌遶香閣，下輦登高望河洛。","東城宮闕擬昭回，南陌溝塍殊綺錯。","林下天香七寶臺，山中春酒萬年杯。","微風一起祥花落，仙樂初鳴瑞鳥來。","鳥來花落紛無已，稱觴獻壽煙霞裏。","歌舞淹留景欲斜，石關猶駐五雲車。","鳥旗翼翼留芳草，龍騎駸駸暎晚花。","千乘萬騎鑾輿出，水靜山空嚴警蹕。","郊外喧喧引看人，傾都南望屬車塵。","囂聲引颺聞黃道，佳氣周迴入紫宸。","先王定鼎山河固，寶命乘周萬物新。","吾皇不事瑤池樂，時雨來觀農扈春。"]', '["宿雨霽氛埃，流云度城闕。","河堤柳新翠，苑樹花先發。","洛陽花柳此时濃，山水楼台暎幾重。","羣公拂霧朝翔鳳，天子乘春幸鑿龙。","鑿龙近出王城外，羽從琳琅擁軒蓋。","云罕纔臨御水橋，天衣已入香山會。","山壁嶄巖斷复連，清流澄澈俯伊川。","雁塔遙遙綠波上，星龕奕奕翠微邊。","層巒旧长千尋木，远壑初飞百丈泉。","綵仗蜺旌遶香閣，下輦登高望河洛。","东城宮闕擬昭回，南陌溝塍殊綺錯。","林下天香七寶台，山中春酒万年杯。","微风一起祥花落，仙乐初鳴瑞鸟来。","鸟来花落紛無已，稱觴獻壽煙霞裏。","歌舞淹留景欲斜，石关猶駐五云车。","鸟旗翼翼留芳草，龙騎駸駸暎晚花。","千乘万騎鑾輿出，水静山空嚴警蹕。","郊外喧喧引看人，傾都南望屬车塵。","囂声引颺闻黄道，佳氣周迴入紫宸。","先王定鼎山河固，寶命乘周万物新。","吾皇不事瑤池乐，时雨来观農扈春。"]', '诗', 'shi', '', NULL, '龍門應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e438ac7e-6725-47eb-b683-a6b9a25f3466', '初宿淮口', '初宿淮口', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["孤舟汴河水，去國情無已。","晚泊投楚鄉，明月清淮裏。","汴河東瀉路窮茲，洛陽西顧日增悲。","夜聞楚歌思欲斷，況值淮南木落時。"]', '["孤舟汴河水，去国情無已。","晚泊投楚乡，明月清淮裏。","汴河东瀉路窮茲，洛陽西顧日增悲。","夜闻楚歌思欲斷，況值淮南木落时。"]', '诗', 'shi', '', NULL, '初宿淮口 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b4100e1-f53e-43bb-8af8-8a5e04946306', '王子喬', '王子喬', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["王子喬，愛神仙，七月七日上賓天。","白虎搖瑟鳳吹笙，乘騎雲氣吸日精。","吸日精，長不歸，遺廟今在而人非。","空望山頭草，草露溼人衣。"]', '["王子喬，愛神仙，七月七日上賓天。","白虎搖瑟鳳吹笙，乘騎云氣吸日精。","吸日精，长不归，遺廟今在而人非。","空望山头草，草露溼人衣。"]', '诗', 'shi', '', NULL, '王子喬 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('add550b8-b152-4880-8f58-ffa183eadcab', '放白鷴篇', '放白鷴篇', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["故人贈我綠綺琴，兼致白鷴鳥。","琴是嶧山桐，鳥出吳溪中。","我心松石清霞裏，弄此幽弦不能已。","我心河海白雲垂，憐此珍禽空自知。","著書晚下麒麟閣，幼稚驕癡候門樂。","乃言物性不可違，白鷴愁慕刷毛衣。","玉徽閉匣留爲念，六翮開籠任爾飛。"]', '["故人贈我綠綺琴，兼致白鷴鸟。","琴是嶧山桐，鸟出吳溪中。","我心松石清霞裏，弄此幽弦不能已。","我心河海白云垂，怜此珍禽空自知。","著书晚下麒麟閣，幼稚驕癡候门乐。","乃言物性不可違，白鷴愁慕刷毛衣。","玉徽閉匣留爲念，六翮开籠任爾飞。"]', '诗', 'shi', '', NULL, '放白鷴篇 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae42510-1f4b-4dfd-9e4e-9bcdfaeada69', '桂州三月三日', '桂州三月三日', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["代業京華裏，遠投魑魅鄉。","登高望不極，雲海四茫茫。","伊昔承休盼，曾爲人所羨。","兩朝賜顏色，二紀陪歡宴。","昆明御宿侍龍媒，伊闕天泉復幾回。","西夏黃河水心劒，東周清洛羽觴杯。","苑中落花掃還合，河畔垂楊撥不開。","千春萬壽多行樂，柏梁和歌攀睿作。","賜金分帛奉恩輝，風舉雲搖入紫微。","晨趨北闕鳴珂至，夜出南宮把燭歸。","載筆儒林多歲月，襆被文昌佐吳越。","越中山海高且深，興來無處不登臨。","永和九年刺海郡，暮春三月醉山陰。","愚謂嬉遊長似昔，不言流寓歘成今。","始安繁華舊風俗，帳飲傾城沸江曲。","主人絲管清且悲，客子肝腸斷還續。","荔浦蘅皐萬里餘，洛陽音信絕能疎。","故園今日應愁思，曲水何能更祓除。","逐伴誰憐合浦葉，思歸豈食桂江魚。","不求漢使金囊贈，願得佳人錦字書。"]', '["代業京华裏，远投魑魅乡。","登高望不極，云海四茫茫。","伊昔承休盼，曾爲人所羨。","兩朝賜顏色，二紀陪歡宴。","昆明御宿侍龙媒，伊闕天泉复幾回。","西夏黄河水心劒，东周清洛羽觴杯。","苑中落花掃還合，河畔垂楊撥不开。","千春万壽多行乐，柏梁和歌攀睿作。","賜金分帛奉恩輝，风舉云搖入紫微。","晨趨北闕鳴珂至，夜出南宮把燭归。","載笔儒林多歲月，襆被文昌佐吳越。","越中山海高且深，兴来無处不登臨。","永和九年刺海郡，暮春三月醉山陰。","愚謂嬉游长似昔，不言流寓歘成今。","始安繁华旧风俗，帳饮傾城沸江曲。","主人絲管清且悲，客子肝腸斷還續。","荔浦蘅皐万里餘，洛陽音信絕能疎。","故园今日應愁思，曲水何能更祓除。","逐伴誰怜合浦葉，思归豈食桂江鱼。","不求漢使金囊贈，願得佳人錦字书。"]', '诗', 'shi', '', NULL, '桂州三月三日 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa1a1768-8324-4aed-b777-5ef11e4e64f6', '下山歌', '下山歌', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["下嵩山兮多所思，攜佳人兮步遲遲。","松間明月長如此，君再遊兮復何時。"]', '["下嵩山兮多所思，携佳人兮步遲遲。","松间明月长如此，君再游兮复何时。"]', '诗', 'shi', '', NULL, '下山歌 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d5147b-c37b-4783-bde5-3f789d8f9bfd', '冬宵引贈司馬承禎', '冬宵引贈司马承禎', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["河有冰兮山有雪，北戶墐兮行人絕。","獨坐山中兮對松月，懷美人兮屢盈缺。","明月的的寒潭中，青松幽幽吟勁風。","此情不向俗人說，愛而不見恨無窮。"]', '["河有冰兮山有雪，北戶墐兮行人絕。","独坐山中兮对松月，懷美人兮屢盈缺。","明月的的寒潭中，青松幽幽吟勁风。","此情不向俗人说，愛而不见恨無窮。"]', '诗', 'shi', '', NULL, '冬宵引贈司馬承禎 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('194fb28b-2216-41fc-8037-9fface1d9dad', '高山引', '高山引', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["攀雲窈窕兮上躋懸峰，長路浩浩兮此去何從。","水一曲兮腸一曲，山一重兮悲一重。","松檟邈已遠，友于何日逢？","況滿室兮童稚，攢衆慮於心胷。","天高難訴兮遠負明德，却望咸京兮揮涕龍鍾。"]', '["攀云窈窕兮上躋懸峰，长路浩浩兮此去何從。","水一曲兮腸一曲，山一重兮悲一重。","松檟邈已远，友于何日逢？","況满室兮童稚，攢衆慮於心胷。","天高难訴兮远負明德，却望咸京兮揮涕龙鍾。"]', '诗', 'shi', '', NULL, '高山引 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6fc5b12-6130-47da-8aea-c3778a946943', '嵩山天門歌', '嵩山天门歌', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["登天門兮坐盤石之磷𥒘，前漎漎兮未半，下漠漠兮無垠。","紛窈窕兮巖倚披以鵬翅，洞膠葛兮峰稜層以龍鱗。","松移岫轉，左變而右易。","風生雲起，出鬼而入神。","吾亦不知其靈怪如此，願遊杳冥兮見羽人。","重曰：天門兮穹崇，回合兮攢藂。","松萬接兮柱日，石千尋兮倚空。","晚陰兮足風，夕陽兮赩紅。","試一望兮奪魄，況衆妙之無窮。"]', '["登天门兮坐盤石之磷𥒘，前漎漎兮未半，下漠漠兮無垠。","紛窈窕兮巖倚披以鵬翅，洞膠葛兮峰稜層以龙鱗。","松移岫轉，左变而右易。","风生云起，出鬼而入神。","吾亦不知其靈怪如此，願游杳冥兮见羽人。","重曰：天门兮穹崇，回合兮攢藂。","松万接兮柱日，石千尋兮倚空。","晚陰兮足风，夕陽兮赩紅。","試一望兮奪魄，況衆妙之無窮。"]', '诗', 'shi', '', NULL, '嵩山天門歌 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f8a36f2-88f3-48f8-97aa-8b65bbfc105e', '有所思', '有所思', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["洛陽城東桃李花，飛來飛去落誰家。","幽閨女兒惜顏色，坐見落花長歎息。","今年花落顏色改，明年花開復誰在。","已見松柏摧爲薪，更聞桑田變成海。","古人無復洛城東，今人還對落花風。","年年歲歲花相似，歲歲年年人不同。","寄言全盛紅顏子，須憐半死白頭翁。","此翁白頭真可憐，伊昔紅顏美少年。","公子王孫芳樹下，清歌妙舞落花前。","光祿池臺交錦繡，將軍樓閣畫神仙。","一朝臥病無相識，三春行樂在誰邊。","婉轉蛾眉能幾時，須臾鶴髮亂如絲。","但看古來歌舞地，唯有黃昏鳥雀飛。"]', '["洛陽城东桃李花，飞来飞去落誰家。","幽閨女兒惜顏色，坐见落花长歎息。","今年花落顏色改，明年花开复誰在。","已见松柏摧爲薪，更闻桑田变成海。","古人無复洛城东，今人還对落花风。","年年歲歲花相似，歲歲年年人不同。","寄言全盛紅顏子，須怜半死白头翁。","此翁白头真可怜，伊昔紅顏美少年。","公子王孫芳樹下，清歌妙舞落花前。","光祿池台交錦繡，將軍楼閣畫神仙。","一朝臥病無相識，三春行乐在誰邊。","婉轉蛾眉能幾时，須臾鹤髮亂如絲。","但看古来歌舞地，唯有黄昏鸟雀飞。"]', '诗', 'shi', '', NULL, '有所思 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2e43fa5-5665-42f4-95ca-2d4f1c795a60', '奉和立春日侍宴內出剪綵花應制', '奉和立春日侍宴內出剪綵花應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["金閣粧新杏，瓊筵弄綺梅。","人間都未識，天上忽先開。","蜨繞香絲住，蜂憐豔粉迴。","今年春色早，應爲剪刀催。"]', '["金閣粧新杏，瓊筵弄綺梅。","人间都未識，天上忽先开。","蜨繞香絲住，蜂怜豔粉迴。","今年春色早，應爲剪刀催。"]', '诗', 'shi', '', NULL, '奉和立春日侍宴內出剪綵花應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1622e79d-fde5-47d9-9916-82248fd23aee', '春日芙蓉園侍宴應制', '春日芙蓉园侍宴應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["芙蓉秦地沼，盧橘漢家園。","谷轉斜盤徑，川迴曲抱原。","風來花自舞，春入鳥能言。","侍宴瑤池夕，歸途笳吹繁。"]', '["芙蓉秦地沼，盧橘漢家园。","谷轉斜盤徑，川迴曲抱原。","风来花自舞，春入鸟能言。","侍宴瑤池夕，归途笳吹繁。"]', '诗', 'shi', '', NULL, '春日芙蓉園侍宴應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5de475d-f8b1-4e54-9512-b5b9ad65e847', '夏日仙蕚亭應制', '夏日仙蕚亭應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["高嶺逼星河，乘輿此日過。","野含時雨潤，山雜夏雲多。","睿藻光巖穴，宸襟洽薜蘿。","悠然小天下，歸路滿笙歌。"]', '["高嶺逼星河，乘輿此日過。","野含时雨潤，山杂夏云多。","睿藻光巖穴，宸襟洽薜蘿。","悠然小天下，归路满笙歌。"]', '诗', 'shi', '', NULL, '夏日仙蕚亭應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b4c979-d04e-4ab6-9864-803912a47060', '奉和九月九日登慈恩寺浮屠應制', '奉和九月九日登慈恩寺浮屠應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["鳳剎侵雲半，虹旌倚日邊。","散花多寶塔，張樂布金田。","時菊芳仙醞，秋蘭動睿篇。","香街稍欲晚，清蹕扈歸天。"]', '["鳳剎侵云半，虹旌倚日邊。","散花多寶塔，張乐布金田。","时菊芳仙醞，秋蘭动睿篇。","香街稍欲晚，清蹕扈归天。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮屠應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('436fd69c-b5f2-4379-88f8-27f2760cc23f', '奉和九日幸臨渭亭登高應制得歡字', '奉和九日幸臨渭亭登高應制得歡字', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["令節三秋晚，重陽九日歡。","仙杯還泛菊，寶饌且調蘭。","御氣雲霄近，乘高宇宙寬。","今朝萬壽引，宜向曲中彈。"]', '["令節三秋晚，重陽九日歡。","仙杯還泛菊，寶饌且調蘭。","御氣云霄近，乘高宇宙寬。","今朝万壽引，宜向曲中彈。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得歡字 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4dbc821-c5cf-48b3-ae56-48e9802c8790', '奉和聖製閏九月九日登莊嚴總持二寺閣', '奉和聖製閏九月九日登莊嚴總持二寺閣', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["閏月再重陽，仙輿歷寶坊。","帝歌雲稍白，御酒菊猶黃。","風鐸喧行漏，天花拂舞行。","豫游多景福，梵宇日生光。"]', '["閏月再重陽，仙輿歷寶坊。","帝歌云稍白，御酒菊猶黄。","风鐸喧行漏，天花拂舞行。","豫游多景福，梵宇日生光。"]', '诗', 'shi', '', NULL, '奉和聖製閏九月九日登莊嚴總持二寺閣 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed648402-a60f-4fcd-ba82-1c24e5540526', '麟趾殿侍宴應制', '麟趾殿侍宴應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["北闕層城峻，西宮複道懸。","乘輿歷萬戶，置酒望三川。","花柳含丹日，山河入綺筵。","欲知陪賞處，空外有飛煙。"]', '["北闕層城峻，西宮複道懸。","乘輿歷万戶，置酒望三川。","花柳含丹日，山河入綺筵。","欲知陪賞处，空外有飞煙。"]', '诗', 'shi', '', NULL, '麟趾殿侍宴應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fce09c9-08e4-4085-a0ac-8630f9802840', '上陽宮侍宴應制得林字', '上陽宮侍宴應制得林字', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["廣樂張前殿，重裘感聖心。","砌蓂霜月盡，庭樹雪雲深。","舊渥驂宸御，慈恩忝翰林。","微臣一何幸，再得聽瑤琴。"]', '["廣乐張前殿，重裘感聖心。","砌蓂霜月尽，庭樹雪云深。","旧渥驂宸御，慈恩忝翰林。","微臣一何幸，再得听瑤琴。"]', '诗', 'shi', '', NULL, '上陽宮侍宴應制得林字 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8287884-50b0-43a2-a1b5-2543b190be9b', '幸少林寺應制', '幸少林寺應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["紺宇橫天室，回鑾指帝休。","曙陰迎日盡，春氣抱巖流。","空樂繁行漏，香煙薄綵斿。","玉膏從此泛，仙馭接浮丘。"]', '["紺宇橫天室，回鑾指帝休。","曙陰迎日尽，春氣抱巖流。","空乐繁行漏，香煙薄綵斿。","玉膏從此泛，仙馭接浮丘。"]', '诗', 'shi', '', NULL, '幸少林寺應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('967a5bb8-16ac-4f3b-9231-23dcf2b191ac', '幸嶽寺應制', '幸嶽寺應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["蹔幸珠筵地，俱憐石瀨清。","泛流張翠幕，拂迥挂紅旌。","雅曲龍調管，芳樽蟻汎觥。","陪歡玉座晚，復得聽金聲。"]', '["蹔幸珠筵地，俱怜石瀨清。","泛流張翠幕，拂迥挂紅旌。","雅曲龙調管，芳樽蟻汎觥。","陪歡玉座晚，复得听金声。"]', '诗', 'shi', '', NULL, '幸嶽寺應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be7c4b8a-03e9-497c-9aab-7f53c3d9a404', '扈從登封途中作', '扈從登封途中作', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["帳殿鬱崔嵬，仙遊實壯哉。","曉雲連幕捲，夜火雜星回。","谷暗千旗出，山鳴萬乘來。","扈從良可賦，終乏掞天才。"]', '["帳殿鬱崔嵬，仙游實壯哉。","晓云連幕捲，夜火杂星回。","谷暗千旗出，山鳴万乘来。","扈從良可賦，終乏掞天才。"]', '诗', 'shi', '', NULL, '扈從登封途中作 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67e07351-19eb-497e-ba4f-e0aa6968643c', '扈從登封告成頌', '扈從登封告成頌', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["複道開行殿，鉤陳列禁兵。","和風吹鼓角，佳氣動旗旌。","後騎迴天苑，前山入御營。","萬方俱下拜，相與樂昇平。"]', '["複道开行殿，鉤陳列禁兵。","和风吹鼓角，佳氣动旗旌。","後騎迴天苑，前山入御營。","万方俱下拜，相與乐昇平。"]', '诗', 'shi', '', NULL, '扈從登封告成頌 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea4a6624-3ca5-4f9d-8fbc-e4c5403ae805', '松山嶺應制', '松山嶺應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["翼翼高旌轉，鏘鏘鳳輦飛。","塵銷清蹕路，雲濕從臣衣。","白羽搖丹壑，天營逼翠微。","芳聲耀今古，四海警宸威。"]', '["翼翼高旌轉，鏘鏘鳳輦飞。","塵銷清蹕路，云濕從臣衣。","白羽搖丹壑，天營逼翠微。","芳声耀今古，四海警宸威。"]', '诗', 'shi', '', NULL, '松山嶺應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e4779b1-ff20-449b-bcb1-57d694326eea', '緱山廟', '緱山廟', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["王子賓仙去，飄颻笙鶴飛。","徒聞滄海變，不見白雲歸。","天路何其遠，人間此會稀。","空歌日云暮，霜月漸微微。"]', '["王子賓仙去，飄颻笙鹤飞。","徒闻滄海变，不见白云归。","天路何其远，人间此會稀。","空歌日云暮，霜月漸微微。"]', '诗', 'shi', '', NULL, '緱山廟 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c7a9c71-12a1-456a-aa49-aa8f149a3fec', '奉和梁王宴龍泓應教得微字', '奉和梁王宴龙泓應教得微字', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["水府淪幽壑，星軺下紫微。","鳥驚司僕馭，花落侍臣衣。","芳樹搖春晚，晴雲繞座飛。","淮王正留客，不醉莫言歸。"]', '["水府淪幽壑，星軺下紫微。","鸟驚司僕馭，花落侍臣衣。","芳樹搖春晚，晴云繞座飞。","淮王正留客，不醉莫言归。"]', '诗', 'shi', '', NULL, '奉和梁王宴龍泓應教得微字 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7facafd1-7f08-4266-804f-7c80bbc47c46', '壽陽王花燭圖', '壽陽王花燭圖', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["仙媛乘龍日，天孫捧雁來。","可憐桃李樹，更繞鳳皇臺。","燭照香車入，花臨寶扇開。","莫令銀箭曉，爲盡合歡杯。"]', '["仙媛乘龙日，天孫捧雁来。","可怜桃李樹，更繞鳳皇台。","燭照香车入，花臨寶扇开。","莫令銀箭晓，爲尽合歡杯。"]', '诗', 'shi', '', NULL, '壽陽王花燭圖 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3d6c397-167e-4480-866e-9b9de38718b8', '江南曲', '江南曲', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["妾住越城南，離居不自堪。","採花驚曙鳥，摘葉餧春蠶。","懶結茱萸帶，愁安玳瑁簪。","待君消瘦盡，日暮碧江潭。"]', '["妾住越城南，離居不自堪。","採花驚曙鸟，摘葉餧春蠶。","懶結茱萸带，愁安玳瑁簪。","待君消瘦尽，日暮碧江潭。"]', '诗', 'shi', '', NULL, '江南曲 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4689980b-6899-45b8-acfe-a7b2d0d4b083', '牛女', '牛女', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["粉席秋期緩，針樓別怨多。","奔龍爭渡月，飛鵲亂填河。","失喜先臨鏡，含羞未解羅。","誰能留夜色，來夕倍還梭。"]', '["粉席秋期緩，針楼別怨多。","奔龙爭渡月，飞鵲亂填河。","失喜先臨镜，含羞未解羅。","誰能留夜色，来夕倍還梭。"]', '诗', 'shi', '', NULL, '牛女 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b58f52a-47e4-42b2-b905-ebdc6de1cfad', '冬夜寓直麟閣', '冬夜寓直麟閣', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["直事披三省，重關閉七門。","廣庭憐雪淨，深屋喜爐溫。","月幌花虛馥，風窗竹暗喧。","東山白雲意，茲夕寄琴尊。"]', '["直事披三省，重关閉七门。","廣庭怜雪淨，深屋喜爐溫。","月幌花虛馥，风窗竹暗喧。","东山白云意，茲夕寄琴尊。"]', '诗', 'shi', '', NULL, '冬夜寓直麟閣 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3891415-5171-4bd2-bd89-98a91e0d5e1e', '登禪定寺閣', '登禪定寺閣', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["梵宇出三天，登臨望八川。","開襟坐霄漢，揮手拂雲煙。","函谷青山外，昆池落日邊。","東京楊柳陌，少別已經年。"]', '["梵宇出三天，登臨望八川。","开襟坐霄漢，揮手拂云煙。","函谷青山外，昆池落日邊。","东京楊柳陌，少別已經年。"]', '诗', 'shi', '', NULL, '登禪定寺閣 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ccbc19a-f663-44cd-869d-26da42ed7e5d', '陸渾山莊', '陸渾山莊', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["歸來物外情，負杖閱巖耕。","源水看花入，幽林採藥行。","野人相問姓，山鳥自呼名。","去去獨吾樂，無然愧此生。"]', '["归来物外情，負杖閱巖耕。","源水看花入，幽林採藥行。","野人相问姓，山鸟自呼名。","去去独吾乐，無然愧此生。"]', '诗', 'shi', '', NULL, '陸渾山莊 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09f6b283-4c4b-4475-a60e-e6ffc774b9f0', '藍田山莊', '藍田山莊', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["宦遊非吏隱，心事好幽偏。","考室先依地，爲農且用天。","輞川朝伐木，藍水暮澆田。","獨與秦山老，相歡春酒前。"]', '["宦游非吏隐，心事好幽偏。","考室先依地，爲農且用天。","輞川朝伐木，藍水暮澆田。","独與秦山老，相歡春酒前。"]', '诗', 'shi', '', NULL, '藍田山莊 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6d18c25-f490-438b-9860-e4f4b51d7509', '春日山家', '春日山家', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["今日遊何處？春泉洗藥歸。","悠然紫芝曲，晝掩白雲扉。","魚樂偏尋藻，人閑屢采薇。","丘中無俗事，身世兩相違。"]', '["今日游何处？春泉洗藥归。","悠然紫芝曲，晝掩白云扉。","鱼乐偏尋藻，人闲屢采薇。","丘中無俗事，身世兩相違。"]', '诗', 'shi', '', NULL, '春日山家 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b820d946-e56f-4f18-b95f-184e5cf4e616', '春日宴宋主簿山亭得寒字', '春日宴宋主簿山亭得寒字', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["公子正邀歡，林亭春未蘭。","攀巖踐苔易，迷路出花難。","窗覆垂楊煖，階侵瀑水寒。","帝城歸路直，留興接鵷鸞。"]', '["公子正邀歡，林亭春未蘭。","攀巖踐苔易，迷路出花难。","窗覆垂楊煖，階侵瀑水寒。","帝城归路直，留兴接鵷鸾。"]', '诗', 'shi', '', NULL, '春日宴宋主簿山亭得寒字 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42940601-e7b6-44ef-8688-0cf49f1c0565', '江亭晚望', '江亭晚望', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["浩渺浸雲根，煙嵐出遠村。","鳥歸沙有跡，帆過浪無痕。","望水知柔性，看山欲斷魂。","縱情猶未已，回馬欲黃昏。"]', '["浩渺浸云根，煙嵐出远村。","鸟归沙有跡，帆過浪無痕。","望水知柔性，看山欲斷魂。","縱情猶未已，回马欲黄昏。"]', '诗', 'shi', '', NULL, '江亭晚望 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20d53bba-a655-41a1-a9d8-c52e2e417d95', '秋晚遊普耀寺', '秋晚游普耀寺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["薄暮曲江頭，仁祠暫可留。","山形無隱霽，野色徧呈秋。","荷覆香泉密，藤緣寶樹幽。","平生厭塵事，過此忽悠悠。"]', '["薄暮曲江头，仁祠暫可留。","山形無隐霽，野色徧呈秋。","荷覆香泉密，藤緣寶樹幽。","平生厭塵事，過此忽悠悠。"]', '诗', 'shi', '', NULL, '秋晚遊普耀寺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb166eef-8ef1-4fc4-9851-c75db2c971b7', '答李司戶夔', '答李司戶夔', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["遠方來下客，輶軒攝使臣。","弄琴宜在夜，傾酒貴逢春。","駟馬留孤館，雙魚贈故人。","明朝散雲雨，遙仰德爲鄰。"]', '["远方来下客，輶軒攝使臣。","弄琴宜在夜，傾酒貴逢春。","駟马留孤館，雙鱼贈故人。","明朝散云雨，遙仰德爲鄰。"]', '诗', 'shi', '', NULL, '答李司戶夔 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5b3ef0-e039-497f-92c1-4e879dc811e8', '寄天台司馬道士', '寄天台司马道士', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["臥來生白髮，覽鏡忽成絲。","遠愧餐霞子，童顏且自持。","舊遊惜疎曠，微尚日磷緇。","不寄西山藥，何由東海期。"]', '["臥来生白髮，覽镜忽成絲。","远愧餐霞子，童顏且自持。","旧游惜疎曠，微尚日磷緇。","不寄西山藥，何由东海期。"]', '诗', 'shi', '', NULL, '寄天台司馬道士 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4e68a12-9696-4581-8dd6-9403335b7311', '使往天平軍馬約與陳子昂新鄉爲期及還而不相遇', '使往天平軍马約與陳子昂新乡爲期及還而不相遇', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["入衞期之子，吁嗟不少留。","情人去何處？淇水日悠悠。","恆碣青雲斷，衡漳白露秋。","知君心許國，不是愛封侯。"]', '["入衞期之子，吁嗟不少留。","情人去何处？淇水日悠悠。","恆碣青云斷，衡漳白露秋。","知君心許国，不是愛封侯。"]', '诗', 'shi', '', NULL, '使往天平軍馬約與陳子昂新鄉爲期及還而不相遇 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f7b1259-d384-4bc1-a9e8-d07f52fc20e1', '過函谷關', '過函谷关', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["二百四十載，海內何紛紛。","六國兵同合，七雄勢未分。","從成拒秦帝，策決問蘇君。","雞鳴將狗盜，論德不論勳。"]', '["二百四十載，海內何紛紛。","六国兵同合，七雄勢未分。","從成拒秦帝，策決问蘇君。","雞鳴將狗盜，論德不論勳。"]', '诗', 'shi', '', NULL, '過函谷關 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64380cdd-355f-4278-bca5-bcb1eef4e7e1', '送朔方何侍郎', '送朔方何侍郎', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["聞道雲中使，乘驄往復還。","河兵守陽月，塞虜失陰山。","拜職嘗隨驃，銘功不讓班。","旋聞受降日，歌舞入蕭關。"]', '["闻道云中使，乘驄往复還。","河兵守陽月，塞虜失陰山。","拜職嘗隨驃，銘功不讓班。","旋闻受降日，歌舞入蕭关。"]', '诗', 'shi', '', NULL, '送朔方何侍郎 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7164e6c5-eac7-498b-ba14-2a47abe083bb', '送田道士使蜀投龍', '送田道士使蜀投龙', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["風馭忽泠然，雲臺路幾千。","蜀門峯勢斷，巴字水形連。","人隔壺中地，龍遊洞裏天。","贈言回馭日，圖畫彼山川。"]', '["风馭忽泠然，云台路幾千。","蜀门峯勢斷，巴字水形連。","人隔壺中地，龙游洞裏天。","贈言回馭日，圖畫彼山川。"]', '诗', 'shi', '', NULL, '送田道士使蜀投龍 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a10ca3c-7c87-4513-b60b-281d18679845', '送許州宋司馬赴任', '送許州宋司马赴任', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["潁郡水東流，荀陳兄弟遊。","偏傷茲日遠，獨向聚星州。","河潤在明德，人康非外求。","當聞力爲政，遙慰我心愁。"]', '["潁郡水东流，荀陳兄弟游。","偏傷茲日远，独向聚星州。","河潤在明德，人康非外求。","當闻力爲政，遙慰我心愁。"]', '诗', 'shi', '', NULL, '送許州宋司馬赴任 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96ee267a-9668-407f-8d84-6d3adeb5dff4', '送趙司馬赴蜀州', '送趙司马赴蜀州', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["餞子西南望，煙緜劒道微。","橋寒金雁落，林曙碧雞飛。","職拜輿方遠，仙成履會歸。","定知和氏璧，遙掩玉輪輝。"]', '["餞子西南望，煙緜劒道微。","橋寒金雁落，林曙碧雞飞。","職拜輿方远，仙成履會归。","定知和氏璧，遙掩玉輪輝。"]', '诗', 'shi', '', NULL, '送趙司馬赴蜀州 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bb21ead-7093-4ad9-8b3c-380421b7c337', '送永昌蕭贊府', '送永昌蕭贊府', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["柳變曲江頭，送君函谷遊。","弄琴寬別意，酌醴醉春愁。","戀本亦何極，贈言微所求。","莫令金谷水，不入故園流。"]', '["柳变曲江头，送君函谷游。","弄琴寬別意，酌醴醉春愁。","戀本亦何極，贈言微所求。","莫令金谷水，不入故园流。"]', '诗', 'shi', '', NULL, '送永昌蕭贊府 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63293760-017c-4a71-9c72-dd734cfb22d5', '送李侍御', '送李侍御', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["行李戀庭闈，乘軺振綵衣。","南登指吳服，北走出秦畿。","去國夏雲斷，還鄉秋雁飛。","旋聞郡計入，更有使臣歸。"]', '["行李戀庭闈，乘軺振綵衣。","南登指吳服，北走出秦畿。","去国夏云斷，還乡秋雁飞。","旋闻郡計入，更有使臣归。"]', '诗', 'shi', '', NULL, '送李侍御 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af031885-268c-478a-93ec-fdb2c98bf6c3', '餞湖州薛司馬', '餞湖州薛司马', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["別駕促嚴程，離筵多故情。","交深季作友，義重伯爲兄。","鎮靜移吳俗，風流在漢京。","會看陳仲舉，從此拜公卿。"]', '["別駕促嚴程，離筵多故情。","交深季作友，義重伯爲兄。","鎮静移吳俗，风流在漢京。","會看陳仲舉，從此拜公卿。"]', '诗', 'shi', '', NULL, '餞湖州薛司馬 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dec8ec2-83f7-4f0e-b7f7-b63f3b1b621e', '送杜審言', '送杜審言', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["臥病人事絕，嗟君萬里行。","河橋不相送，江樹遠含情。","別路追孫楚，維舟弔屈平。","可惜龍泉劒，流落在豐城。"]', '["臥病人事絕，嗟君万里行。","河橋不相送，江樹远含情。","別路追孫楚，維舟弔屈平。","可惜龙泉劒，流落在豐城。"]', '诗', 'shi', '', NULL, '送杜審言 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dccc6bb-e80c-4653-ba3c-03a07f4a2192', '送武進鄭明府', '送武進鄭明府', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["弦歌試宰日，城闕賞心違。","北謝蒼龍去，南隨黃鵠飛。","夏雲海中出，吳山江上微。","甿謠豈云遠，從此慶緇衣。"]', '["弦歌試宰日，城闕賞心違。","北謝蒼龙去，南隨黄鵠飞。","夏云海中出，吳山江上微。","甿謠豈云远，從此慶緇衣。"]', '诗', 'shi', '', NULL, '送武進鄭明府 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec844021-ff60-446a-95b6-fd5eb7be28c8', '送姚侍御出使江東', '送姚侍御出使江东', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["帝憂河朔郡，南發海陵倉。","坐歎青春別，逶迤碧水長。","飲冰朝受命，衣錦晝還鄉。","爲問東山桂，無人何自芳。"]', '["帝憂河朔郡，南發海陵倉。","坐歎青春別，逶迤碧水长。","饮冰朝受命，衣錦晝還乡。","爲问东山桂，無人何自芳。"]', '诗', 'shi', '', NULL, '送姚侍御出使江東 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c93605d-078d-4777-9ebf-b074a29fc678', '留別之望舍弟', '留別之望舍弟', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["同氣有三人，分飛在此晨。","西馳巴嶺徼，東去洛陽濱。","強飲離前酒，終傷別後神。","誰憐散花蕚，獨赴日南春。"]', '["同氣有三人，分飞在此晨。","西驰巴嶺徼，东去洛陽濱。","強饮離前酒，終傷別後神。","誰怜散花蕚，独赴日南春。"]', '诗', 'shi', '', NULL, '留別之望舍弟 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4c29355-b4e5-47b0-97bc-9a45419e7591', '漢江宴別', '漢江宴別', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["漢廣不分天，舟移杳若仙。","秋虹暎晚日，江鶴弄晴煙。","積水浮冠蓋，遙風逐管弦。","嬉遊不可極，留恨此山川。"]', '["漢廣不分天，舟移杳若仙。","秋虹暎晚日，江鹤弄晴煙。","積水浮冠蓋，遙风逐管弦。","嬉游不可極，留恨此山川。"]', '诗', 'shi', '', NULL, '漢江宴別 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d4df854-57d4-4514-b9d5-3adeec13e351', '初發荆府贈長史', '初發荆府贈长史', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["□□□□□，□□□□□。","仍隨五馬謫，載與兩禽奔。","明主無由見，羣公莫與言。","幸君逢聖日，何惜理虞翻。"]', '["□□□□□，□□□□□。","仍隨五马謫，載與兩禽奔。","明主無由见，羣公莫與言。","幸君逢聖日，何惜理虞翻。"]', '诗', 'shi', '', NULL, '初發荆府贈長史 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9b9b9c3-84b7-4066-a538-4c176a0a523c', '晚泊湘江', '晚泊湘江', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["五嶺恓惶客，三湘顦顇顏。","況復秋雨霽，表裏見衡山。","路逐鵬南轉，心依雁北還。","唯餘望鄉淚，更染竹成斑。"]', '["五嶺恓惶客，三湘顦顇顏。","況复秋雨霽，表裏见衡山。","路逐鵬南轉，心依雁北還。","唯餘望乡泪，更染竹成斑。"]', '诗', 'shi', '', NULL, '晚泊湘江 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d31dc2b-0af9-47e1-a9da-50b80681cf53', '過蠻洞', '過蠻洞', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["越嶺千重合，蠻谿十里斜。","竹迷樵子徑，萍匝釣人家。","林暗交楓葉，園香覆橘花。","誰憐在荒外，孤賞足雲霞。"]', '["越嶺千重合，蠻谿十里斜。","竹迷樵子徑，萍匝釣人家。","林暗交楓葉，园香覆橘花。","誰怜在荒外，孤賞足云霞。"]', '诗', 'shi', '', NULL, '過蠻洞 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('723497ef-1a08-4a80-8926-91f3c9896376', '經梧州', '經梧州', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["南國無霜霰，連年見物華。","青林暗換葉，紅橤續開花。","春去聞山鳥，秋來見海槎。","流芳雖可悅，會自泣長沙。"]', '["南国無霜霰，連年见物华。","青林暗換葉，紅橤續开花。","春去闻山鸟，秋来见海槎。","流芳雖可悅，會自泣长沙。"]', '诗', 'shi', '', NULL, '經梧州 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144a86f2-cd0d-4a70-9d00-3251df8cd5c8', '渡吳江別王長史', '渡吳江別王长史', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["倚櫂望茲川，銷魂獨黯然。","鄉連江北樹，雲斷日南天。","劒別龍初沒，書成雁不傳。","離舟意無限，催渡復催年。"]', '["倚櫂望茲川，銷魂独黯然。","乡連江北樹，云斷日南天。","劒別龙初沒，书成雁不傳。","離舟意無限，催渡复催年。"]', '诗', 'shi', '', NULL, '渡吳江別王長史 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8bd0fc6-9b38-4570-afcf-e53bc85d4c8e', '泛鏡湖南溪', '泛镜湖南溪', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["乘興入幽棲，舟行日向低。","巖花候冬發，谷鳥作春啼。","沓嶂開天小，叢篁夾路迷。","猶聞可憐處，更在若邪溪。"]', '["乘兴入幽棲，舟行日向低。","巖花候冬發，谷鸟作春啼。","沓嶂开天小，叢篁夾路迷。","猶闻可怜处，更在若邪溪。"]', '诗', 'shi', '', NULL, '泛鏡湖南溪 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46be27ea-afe5-4078-9175-59213f05ab5b', '途中寒食題黃梅臨江驛寄崔融', '途中寒食題黄梅臨江驛寄崔融', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["馬上逢寒食，愁中屬暮春。","可憐江浦望，不見洛陽人。","北極懷明主，南溟作逐臣。","故園腸斷處，日夜柳條新。"]', '["马上逢寒食，愁中屬暮春。","可怜江浦望，不见洛陽人。","北極懷明主，南溟作逐臣。","故园腸斷处，日夜柳條新。"]', '诗', 'shi', '', NULL, '途中寒食題黃梅臨江驛寄崔融 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5648eda-d6c5-420f-bda0-fec6e15867da', '遊韶州廣界寺', '游韶州廣界寺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["影殿臨丹壑，香臺隱翠霞。","巢飛銜象鳥，砌蹋雨空花。","寶鐸搖初霽，金池暎晚沙。","莫愁歸路遠，門外有三車。"]', '["影殿臨丹壑，香台隐翠霞。","巢飞銜象鸟，砌蹋雨空花。","寶鐸搖初霽，金池暎晚沙。","莫愁归路远，门外有三车。"]', '诗', 'shi', '', NULL, '遊韶州廣界寺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f14c55be-50b1-41b1-8063-51d1be9ae5bb', '宿清遠峽山寺', '宿清远峽山寺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["香岫懸金剎，飛泉屆石門。","空山唯習靜，中夜寂無喧。","說法初聞鳥，看心欲定猿。","寥寥隔塵市，何異武陵源。"]', '["香岫懸金剎，飞泉屆石门。","空山唯習静，中夜寂無喧。","说法初闻鸟，看心欲定猿。","寥寥隔塵市，何異武陵源。"]', '诗', 'shi', '', NULL, '宿清遠峽山寺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('058db0d1-0656-4e8f-ac49-87622e16b19b', '題大庾嶺北驛', '題大庾嶺北驛', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["陽月南飛雁，傳聞至此回。","我行殊未已，何日復歸來？","江靜潮初落，林昏瘴不開。","明朝望鄉處，應見隴頭梅。"]', '["陽月南飞雁，傳闻至此回。","我行殊未已，何日复归来？","江静潮初落，林昏瘴不开。","明朝望乡处，應见隴头梅。"]', '诗', 'shi', '', NULL, '題大庾嶺北驛 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0001725-2228-45b4-bc4c-76fa5b455343', '度大庾嶺', '度大庾嶺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["度嶺方辭國，停軺一望家。","魂隨南翥鳥，淚盡北枝花。","山雨初含霽，江雲欲變霞。","但令歸有日，不敢恨長沙。"]', '["度嶺方辞国，停軺一望家。","魂隨南翥鸟，泪尽北枝花。","山雨初含霽，江云欲变霞。","但令归有日，不敢恨长沙。"]', '诗', 'shi', '', NULL, '度大庾嶺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('721463b7-2205-4306-b3e7-70f2b06631b9', '端州別袁侍郎', '端州別袁侍郎', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["合浦途未極，端溪行蹔臨。","淚來空泣臉，愁至不知心。","客醉山月靜，猿啼江樹深。","明朝共分手，之子愛千金。"]', '["合浦途未極，端溪行蹔臨。","泪来空泣臉，愁至不知心。","客醉山月静，猿啼江樹深。","明朝共分手，之子愛千金。"]', '诗', 'shi', '', NULL, '端州別袁侍郎 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('504ce895-589e-4db8-bb0a-9bab24f22d5b', '過史正議宅', '過史正議宅', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["舊交此零落，雨泣訪遺塵。","劒几傳好事，池臺傷故人。","國香蘭已歇，里樹橘猶新。","不見吳中隱，空餘江海濱。"]', '["旧交此零落，雨泣訪遺塵。","劒几傳好事，池台傷故人。","国香蘭已歇，里樹橘猶新。","不见吳中隐，空餘江海濱。"]', '诗', 'shi', '', NULL, '過史正議宅 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dea4fd2-95e6-429f-941d-60f955b76718', '梁宣王挽詞三首 一', '梁宣王挽词三首 一', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["貴藩堯母族，外戚漢家親。","業重興王際，功高復辟辰。","愛賢唯報國，樂善不防身。","今日衣冠送，空傷置醴人。"]', '["貴藩堯母族，外戚漢家親。","業重兴王際，功高复辟辰。","愛賢唯報国，乐善不防身。","今日衣冠送，空傷置醴人。"]', '诗', 'shi', '', NULL, '梁宣王挽詞三首 一 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e260f448-425a-4c27-a97c-ec17228abb30', '梁宣王挽詞三首 二', '梁宣王挽词三首 二', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["金精何日閉，玉匣此時開。","東望連吾子，南瞻近帝臺。","地形龜食報，墳土燕銜來。","可歎虞歌夕，紛紛騎吹回。"]', '["金精何日閉，玉匣此时开。","东望連吾子，南瞻近帝台。","地形龟食報，墳土燕銜来。","可歎虞歌夕，紛紛騎吹回。"]', '诗', 'shi', '', NULL, '梁宣王挽詞三首 二 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a98a3aae-1958-4833-86cb-2dda74da2773', '梁宣王挽詞三首 三', '梁宣王挽词三首 三', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["像設千年在，平生萬事違。","綵旌翻葆吹，圭翣奠靈衣。","壠日寒無影，郊雲凍不飛。"]', '["像設千年在，平生万事違。","綵旌翻葆吹，圭翣奠靈衣。","壠日寒無影，郊云凍不飞。"]', '诗', 'shi', '', NULL, '梁宣王挽詞三首 三 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('949ae54d-39d8-4173-a4b2-343a9e6762ea', '魯忠王挽詞三首 一', '魯忠王挽词三首 一', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["同盟會五月，歸葬出三條。","日慘咸陽樹，天寒渭水橋。","稍看朱鷺轉，尚識紫騮驕。","寂寂泉臺恨，從茲罷玉簫。"]', '["同盟會五月，归葬出三條。","日慘咸陽樹，天寒渭水橋。","稍看朱鷺轉，尚識紫騮驕。","寂寂泉台恨，從茲罷玉簫。"]', '诗', 'shi', '', NULL, '魯忠王挽詞三首 一 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('591221b5-0dae-410b-9722-559443a166f2', '魯忠王挽詞三首 二', '魯忠王挽词三首 二', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["邦家錫寵光，存沒貴忠良。","遂裂山河地，追尊父子王。","人悲槐里月，馬踏槿原霜。","別向天京北，悠悠此路長。"]', '["邦家錫寵光，存沒貴忠良。","遂裂山河地，追尊父子王。","人悲槐里月，马踏槿原霜。","別向天京北，悠悠此路长。"]', '诗', 'shi', '', NULL, '魯忠王挽詞三首 二 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ef415ed-3b5c-4217-9488-d20fc5aba38c', '魯忠王挽詞三首 三', '魯忠王挽词三首 三', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["樹羽迎朝日，撞鐘望早霞。","故人悲宿草，中使慘晨笳。","氣有衝天劒，星無犯斗槎。","唯餘孔公宅，長接魯王家。"]', '["樹羽迎朝日，撞鐘望早霞。","故人悲宿草，中使慘晨笳。","氣有衝天劒，星無犯斗槎。","唯餘孔公宅，长接魯王家。"]', '诗', 'shi', '', NULL, '魯忠王挽詞三首 三 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('170bac88-fa66-4c49-ba43-3340921c913a', '范陽王挽詞二首 一', '范陽王挽词二首 一', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["賢相稱邦傑，清流舉代推。","公才掩諸夏，文體變當時。","賓弔飜成鶴，人亡惜喻龜。","洛陽今紙貴，猶寫太沖詞。"]', '["賢相稱邦傑，清流舉代推。","公才掩諸夏，文體变當时。","賓弔飜成鹤，人亡惜喻龟。","洛陽今紙貴，猶寫太沖词。"]', '诗', 'shi', '', NULL, '范陽王挽詞二首 一 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7d0d1dc-d225-45df-a916-e828ca37b79b', '范陽王挽詞二首 二', '范陽王挽词二首 二', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["贈秩徽章洽，求書秘草成。","客隨朝露盡，人逐夜舟驚。","蒿里衣冠送，松門印綬迎。","誰知楊伯起，今日重哀榮。"]', '["贈秩徽章洽，求书秘草成。","客隨朝露尽，人逐夜舟驚。","蒿里衣冠送，松门印綬迎。","誰知楊伯起，今日重哀榮。"]', '诗', 'shi', '', NULL, '范陽王挽詞二首 二 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69a7243f-3024-4922-98df-5841f56d6492', '故趙王屬贈黃門侍郎上官公挽詞二首 一', '故趙王屬贈黄门侍郎上官公挽词二首 一', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["韋門旌舊德，班氏業前書。","謫去因丞相，歸來爲倢伃。","周原烏相冢，越嶺雁隨車。","冥漠辭昭代，空憐賦子虛。"]', '["韋门旌旧德，班氏業前书。","謫去因丞相，归来爲倢伃。","周原烏相冢，越嶺雁隨车。","冥漠辞昭代，空怜賦子虛。"]', '诗', 'shi', '', NULL, '故趙王屬贈黃門侍郎上官公挽詞二首 一 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6521193-75a6-4aaa-979e-82d7b3b13b6c', '故趙王屬贈黃門侍郎上官公挽詞二首 二', '故趙王屬贈黄门侍郎上官公挽词二首 二', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["綠車隨帝子，青瑣翊宸機。","昔枉朝歌騎，今虛夕拜闈。","柳河悽挽曲，薤露濕靈衣。","一厝窮泉閉，雙鸞遂不飛。"]', '["綠车隨帝子，青瑣翊宸機。","昔枉朝歌騎，今虛夕拜闈。","柳河悽挽曲，薤露濕靈衣。","一厝窮泉閉，雙鸾遂不飞。"]', '诗', 'shi', '', NULL, '故趙王屬贈黃門侍郎上官公挽詞二首 二 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e4b4de9-1907-47f6-8ed8-3bba7bfc0a0c', '藥', '藥', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["有卉祕神仙，君臣有禮焉。","忻當苦口喻，不畏入腸偏。","扁鵲功成日，神農定品年。","丹成如可待，雞犬自聞天。"]', '["有卉祕神仙，君臣有禮焉。","忻當苦口喻，不畏入腸偏。","扁鵲功成日，神農定品年。","丹成如可待，雞犬自闻天。"]', '诗', 'shi', '', NULL, '藥 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7598f03c-92f0-43be-b9c7-7b414e5fd8aa', '奉和九日登慈恩寺浮圖應制', '奉和九日登慈恩寺浮圖應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["瑞塔千尋起，仙輿九日來。","萸房陳寶席，菊蘂散花臺。","御氣鵬霄近，升高鳳野開。","天歌將梵樂，空裏共裴回。"]', '["瑞塔千尋起，仙輿九日来。","萸房陳寶席，菊蘂散花台。","御氣鵬霄近，升高鳳野开。","天歌將梵乐，空裏共裴回。"]', '诗', 'shi', '', NULL, '奉和九日登慈恩寺浮圖應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa59244-2813-4551-9b1c-8e1d91b6831a', '送沙門泓景道俊玄奘還荆州應制', '送沙门泓景道俊玄奘還荆州應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["三乘歸淨域，萬騎餞通莊。","就日離亭近，彌天別路長。","荆南旋杖鉢，渭北限津梁。","何日紆真果，還來入帝鄉。"]', '["三乘归淨域，万騎餞通莊。","就日離亭近，彌天別路长。","荆南旋杖鉢，渭北限津梁。","何日紆真果，還来入帝乡。"]', '诗', 'shi', '', NULL, '送沙門泓景道俊玄奘還荆州應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27ab759-00d1-4e35-9bf5-f3860ccf873a', '春日芙蓉園侍宴應制', '春日芙蓉园侍宴應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["年光竹裏遍，春色杏間遙。","煙氣籠青閣，流文蕩畫橋。","飛花隨蝶舞，豔曲伴鶯嬌。","今日陪歡豫，還疑陟紫霄。"]', '["年光竹裏遍，春色杏间遙。","煙氣籠青閣，流文蕩畫橋。","飞花隨蝶舞，豔曲伴鶯嬌。","今日陪歡豫，還疑陟紫霄。"]', '诗', 'shi', '', NULL, '春日芙蓉園侍宴應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68377b20-f212-43eb-a581-dad642b27e92', '詠笛', '詠笛', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["羌笛寫龍聲，長吟入夜清。","關山孤月下，來向隴頭鳴。","逐吹梅花落，含春柳色驚。","行觀向子賦，坐憶舊鄰情。"]', '["羌笛寫龙声，长吟入夜清。","关山孤月下，来向隴头鳴。","逐吹梅花落，含春柳色驚。","行观向子賦，坐憶旧鄰情。"]', '诗', 'shi', '', NULL, '詠笛 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0821bd3-bae4-4693-824c-ca974c31da07', '詠鍾', '詠鍾', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["既接南鄰磬，還隨北里笙。","平陵通曙響，長樂警宵聲。","秋至含霜動，春歸應律鳴。","豈惟恆待扣，金簴有餘清。"]', '["既接南鄰磬，還隨北里笙。","平陵通曙响，长乐警宵声。","秋至含霜动，春归應律鳴。","豈惟恆待扣，金簴有餘清。"]', '诗', 'shi', '', NULL, '詠鍾 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf845483-2c08-46bf-94fb-3f3cd3263c52', '花落', '花落', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["鐵騎幾時迴，金閨怨早梅。","雪寒花已落，風暖葉還開。","夕逐新春管，香迎小歲桮。","盛時何足貴，書裏報輪臺。"]', '["鐵騎幾时迴，金閨怨早梅。","雪寒花已落，风暖葉還开。","夕逐新春管，香迎小歲桮。","盛时何足貴，书裏報輪台。"]', '诗', 'shi', '', NULL, '花落 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccc02b26-b0d1-4081-b371-dd3391ba5e02', '旅宿淮陽亭口號', '旅宿淮陽亭口號', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["日暮風亭上，悠悠旅思多。","故鄉臨桂水，今夜渺星河。","暗草霜華發，空亭鴈影過。","興來誰與語，勞者自爲歌。"]', '["日暮风亭上，悠悠旅思多。","故乡臨桂水，今夜渺星河。","暗草霜华發，空亭鴈影過。","兴来誰與語，勞者自爲歌。"]', '诗', 'shi', '', NULL, '旅宿淮陽亭口號 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2bbf7ba-9e76-40bf-b535-43306c88351b', '內題賦得巫山雨', '內題賦得巫山雨', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["神女向高唐，巫山下夕陽。","裴回作行雨，婉戀逐荆王。","電影江前落，雷聲峽外長。","霽雲無處所，臺館曉蒼蒼。"]', '["神女向高唐，巫山下夕陽。","裴回作行雨，婉戀逐荆王。","電影江前落，雷声峽外长。","霽云無处所，台館晓蒼蒼。"]', '诗', 'shi', '', NULL, '內題賦得巫山雨 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60a6c06a-af0e-4b2a-96bf-3b8844b44b89', '王昭君', '王昭君', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["非君惜鸞殿，非妾妬娥眉。","薄命由驕虜，無情是畫師。","嫁來胡地日，不竝漢宮時。","辛苦無聊賴，何堪上馬辭。"]', '["非君惜鸾殿，非妾妬娥眉。","薄命由驕虜，無情是畫師。","嫁来胡地日，不竝漢宮时。","辛苦無聊賴，何堪上马辞。"]', '诗', 'shi', '', NULL, '王昭君 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f65e833-3266-42a2-9580-af89a6d1761d', '銅雀臺', '銅雀台', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["昔年分鼎地，今日望陵臺。","一旦雄圖盡，千秋遺令開。","綺羅君不見，歌舞妾空來。","恩共漳河水，東流無重回。"]', '["昔年分鼎地，今日望陵台。","一旦雄圖尽，千秋遺令开。","綺羅君不见，歌舞妾空来。","恩共漳河水，东流無重回。"]', '诗', 'shi', '', NULL, '銅雀臺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('331fa932-e09b-4c0f-b8f7-f4990a598879', '巫山高', '巫山高', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["巫山峯十二，環合象昭回。","俯聽琵琶峽，平看雲雨臺。","古槎天外落，瀑水日邊來。","何忍猨啼夜，荆王枕席開。"]', '["巫山峯十二，环合象昭回。","俯听琵琶峽，平看云雨台。","古槎天外落，瀑水日邊来。","何忍猨啼夜，荆王枕席开。"]', '诗', 'shi', '', NULL, '巫山高 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0155d22-7644-4dcd-b67e-6739ccc389fb', '望月有懷', '望月有懷', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["天使下西樓，含光萬里秋。","臺前似挂鏡，簾外如懸鉤。","張尹將眉學，班姬取扇儔。","佳期應借問，爲報大刀頭。"]', '["天使下西楼，含光万里秋。","台前似挂镜，簾外如懸鉤。","張尹將眉学，班姬取扇儔。","佳期應借问，爲報大刀头。"]', '诗', 'shi', '', NULL, '望月有懷 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82741df3-0dde-45d4-8153-0c5ef638e018', '駕出長安', '駕出长安', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["聖德超千古，皇風扇九圍。","天回萬象出，駕動六龍飛。","淑氣來黃道，祥雲覆紫微。","太平多扈從，文物有光輝。"]', '["聖德超千古，皇风扇九圍。","天回万象出，駕动六龙飞。","淑氣来黄道，祥云覆紫微。","太平多扈從，文物有光輝。"]', '诗', 'shi', '', NULL, '駕出長安 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf379c1-d102-4d2b-bed6-52a2f2f60bba', '餞中書侍郎來濟', '餞中书侍郎来濟', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["曖曖去塵昏灞岸，飛飛輕蓋指河梁。","雲峰衣結千重葉，雪岫花開幾樹粧。","深悲黃鶴孤舟遠，獨對青山別路長。","却將分手霑襟淚，還用持添離席觴。"]', '["曖曖去塵昏灞岸，飞飞轻蓋指河梁。","云峰衣結千重葉，雪岫花开幾樹粧。","深悲黄鹤孤舟远，独对青山別路长。","却將分手霑襟泪，還用持添離席觴。"]', '诗', 'shi', '', NULL, '餞中書侍郎來濟 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e86ab6-083e-441f-8713-f25a131941ce', '奉和春初幸太平公主南莊應制', '奉和春初幸太平公主南莊應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["青門路接鳳凰臺，素滻宸遊龍騎來。","澗草自迎香輦合，巖花應待御筵開。","文移北斗成天象，酒遞南山作壽杯。","此日侍臣將石去，共歡明主賜金回。"]', '["青门路接鳳凰台，素滻宸游龙騎来。","澗草自迎香輦合，巖花應待御筵开。","文移北斗成天象，酒遞南山作壽杯。","此日侍臣將石去，共歡明主賜金回。"]', '诗', 'shi', '', NULL, '奉和春初幸太平公主南莊應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff0bcc77-7bdf-46fc-905f-d6c6e940fc10', '三陽宮侍宴應制得幽字', '三陽宮侍宴應制得幽字', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["離宮祕苑勝瀛洲，別有仙人洞壑幽。","巖邊樹色含風冷，石上泉聲帶雨秋。","鳥向歌筵來度曲，雲依帳殿結爲樓。","微臣昔忝方明御，今日還陪八駿遊。"]', '["離宮祕苑勝瀛洲，別有仙人洞壑幽。","巖邊樹色含风冷，石上泉声带雨秋。","鸟向歌筵来度曲，云依帳殿結爲楼。","微臣昔忝方明御，今日還陪八駿游。"]', '诗', 'shi', '', NULL, '三陽宮侍宴應制得幽字 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f47be854-5b15-4b04-8021-3384b603b674', '奉和晦日幸昆明池應制', '奉和晦日幸昆明池應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["春豫靈池會，滄波帳殿開。","舟淩石鯨度，槎拂斗牛回。","節晦蓂全落，春遲柳暗催。","象溟看浴景，燒劫辨沈灰。","鎬飲周文樂，汾歌漢武才。","不愁明月盡，自有夜珠來。"]', '["春豫靈池會，滄波帳殿开。","舟淩石鯨度，槎拂斗牛回。","節晦蓂全落，春遲柳暗催。","象溟看浴景，燒劫辨沈灰。","鎬饮周文乐，汾歌漢武才。","不愁明月尽，自有夜珠来。"]', '诗', 'shi', '', NULL, '奉和晦日幸昆明池應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1624027-5337-4f85-b636-c28ea14deaf9', '奉和幸大薦福寺', '奉和幸大薦福寺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["香剎中天起，宸遊滿路輝。","乘龍太子去，駕象法王歸。","殿飾金人影，窗搖玉女扉。","稍迷新草木，徧識舊庭闈。","水入禪心定，雲從寶思飛。","欲知皇劫遠，初拂六銖衣。"]', '["香剎中天起，宸游满路輝。","乘龙太子去，駕象法王归。","殿飾金人影，窗搖玉女扉。","稍迷新草木，徧識旧庭闈。","水入禪心定，云從寶思飞。","欲知皇劫远，初拂六銖衣。"]', '诗', 'shi', '', NULL, '奉和幸大薦福寺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f786cb2-4edf-480e-850b-9b96e19561bc', '奉和幸三會寺應制', '奉和幸三會寺應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["六飛回玉輦，雙樹謁金仙。","瑞鳥呈書字，神龍吐浴泉。","淨心遙證果，睿想獨超禪。","塔湧香花地，山圍日月天。","梵音迎漏徹，空樂倚雲懸。","今日登仁壽，長看法鏡圓。"]', '["六飞回玉輦，雙樹謁金仙。","瑞鸟呈书字，神龙吐浴泉。","淨心遙證果，睿想独超禪。","塔湧香花地，山圍日月天。","梵音迎漏徹，空乐倚云懸。","今日登仁壽，长看法镜圓。"]', '诗', 'shi', '', NULL, '奉和幸三會寺應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08d49d18-7848-422a-8398-2843f565c485', '奉和薦福寺應制', '奉和薦福寺應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["梵筵光聖邸，遊豫覽宏規。","不改靈光殿，因開功德池。","蓮生新步葉，桂長昔攀枝。","湧塔庭中見，飛樓海上移。","聞韶三月幸，觀象七星危。","欲識龍歸處，朝朝雲氣隨。"]', '["梵筵光聖邸，游豫覽宏規。","不改靈光殿，因开功德池。","蓮生新步葉，桂长昔攀枝。","湧塔庭中见，飞楼海上移。","闻韶三月幸，观象七星危。","欲識龙归处，朝朝云氣隨。"]', '诗', 'shi', '', NULL, '奉和薦福寺應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7a40cbd-04ba-450f-a4a6-86d636082b37', '奉和幸神皐亭應制', '奉和幸神皐亭應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["清蹕喧黃道，乘輿降紫宸。","霜戈凝曉日，雲管發陽春。","臺古全疑漢，林餘半識秦。","宴酣詩布澤，節改令行仁。","昔恃山河險，今依道德淳。","多慙獻嘉頌，空累屬車塵。"]', '["清蹕喧黄道，乘輿降紫宸。","霜戈凝晓日，云管發陽春。","台古全疑漢，林餘半識秦。","宴酣诗布澤，節改令行仁。","昔恃山河險，今依道德淳。","多慙獻嘉頌，空累屬车塵。"]', '诗', 'shi', '', NULL, '奉和幸神皐亭應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cb0c7e7-99a7-4dad-9951-4f59b8ac2788', '奉和幸長安故城未央宮應制', '奉和幸长安故城未央宮應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["漢王未息戰，蕭相乃營宮。","壯麗一朝盡，威靈千載空。","皇明悵前跡，置酒宴羣公。","寒輕綵仗外，春發幔城中。","樂思回斜日，歌詞繼大風。","今朝天子貴，不假叔孫通。"]', '["漢王未息戰，蕭相乃營宮。","壯丽一朝尽，威靈千載空。","皇明悵前跡，置酒宴羣公。","寒轻綵仗外，春發幔城中。","乐思回斜日，歌词繼大风。","今朝天子貴，不假叔孫通。"]', '诗', 'shi', '', NULL, '奉和幸長安故城未央宮應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adc370a5-b867-48e8-81a4-7994da5e9289', '奉和幸韋嗣立山莊侍宴應制', '奉和幸韋嗣立山莊侍宴應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["樞掖調梅暇，林園藝槿初。","入朝榮劒履，退食偶琴書。","地隱東巖室，天回北斗車。","旌門臨䆗窱，輦道屬扶疎。","雲罕明丹壑，霜笳徹紫虛。","水疑投石處，溪似釣璜餘。","帝澤頒巵酒，人歡頌里閭。","一承黃竹詠，長奉白茅居。"]', '["樞掖調梅暇，林园藝槿初。","入朝榮劒履，退食偶琴书。","地隐东巖室，天回北斗车。","旌门臨䆗窱，輦道屬扶疎。","云罕明丹壑，霜笳徹紫虛。","水疑投石处，溪似釣璜餘。","帝澤頒巵酒，人歡頌里閭。","一承黄竹詠，长奉白茅居。"]', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊侍宴應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e2540d-854b-4a0d-b7ec-6da22051d035', '扈從登封告成頌應制', '扈從登封告成頌應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["御路回中嶽，天營接下都。","百靈無後至，萬國競前驅。","文衞嚴清蹕，幽仙讀寶符。","貝花明漢果，芝草入堯廚。","濟濟衣冠會，喧喧夷夏俱。","宗禋仰神理，刊木望川途。","撫己貧非病，時來本不愚。","願陪丹鳳輦，率舞白雲衢。"]', '["御路回中嶽，天營接下都。","百靈無後至，万国競前驱。","文衞嚴清蹕，幽仙读寶符。","貝花明漢果，芝草入堯廚。","濟濟衣冠會，喧喧夷夏俱。","宗禋仰神理，刊木望川途。","撫己貧非病，时来本不愚。","願陪丹鳳輦，率舞白云衢。"]', '诗', 'shi', '', NULL, '扈從登封告成頌應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a1446a8-3f7b-4a57-8a28-1d4b2e123f67', '宴安樂公主宅得空字', '宴安乐公主宅得空字', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["英藩築外館，愛主出王宮。","賓至星槎落，仙來月宇空。","玳梁飜賀燕，金埒倚晴虹。","簫奏秦臺裏，書開魯壁中。","短歌能駐日，豔舞欲嬌風。","聞有淹留處，山阿滿桂叢。"]', '["英藩築外館，愛主出王宮。","賓至星槎落，仙来月宇空。","玳梁飜賀燕，金埒倚晴虹。","簫奏秦台裏，书开魯壁中。","短歌能駐日，豔舞欲嬌风。","闻有淹留处，山阿满桂叢。"]', '诗', 'shi', '', NULL, '宴安樂公主宅得空字 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb69c424-e7c9-402d-ae43-966443ddb04c', '春日鄭協律山亭陪宴餞鄭卿同用樓字', '春日鄭協律山亭陪宴餞鄭卿同用楼字', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["潘園枕郊郭，愛客坐相求。","尊酒東城外，驂騑南陌頭。","池平分洛水，林缺見嵩丘。","暗竹侵山徑，垂楊拂妓樓。","彩雲歌處斷，遲日舞前留。","此地何年別，蘭芳空自幽。"]', '["潘园枕郊郭，愛客坐相求。","尊酒东城外，驂騑南陌头。","池平分洛水，林缺见嵩丘。","暗竹侵山徑，垂楊拂妓楼。","彩云歌处斷，遲日舞前留。","此地何年別，蘭芳空自幽。"]', '诗', 'shi', '', NULL, '春日鄭協律山亭陪宴餞鄭卿同用樓字 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe8ef8a4-959c-444e-8e1b-91ea921ddc6d', '和姚給事寓直之作', '和姚給事寓直之作', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["清論滿朝陽，高才拜夕郎。","還從避馬路，來接珥貂行。","寵就黃扉日，威回白簡霜。","柏臺遷鳥茂，蘭署得人芳。","禁靜鐘初徹，更疎漏漸長。","曉河低武庫，流火度文昌。","寓直恩徽重，乘秋藻翰揚。","暗投空欲報，下調不成章。"]', '["清論满朝陽，高才拜夕郎。","還從避马路，来接珥貂行。","寵就黄扉日，威回白簡霜。","柏台遷鸟茂，蘭署得人芳。","禁静鐘初徹，更疎漏漸长。","晓河低武庫，流火度文昌。","寓直恩徽重，乘秋藻翰揚。","暗投空欲報，下調不成章。"]', '诗', 'shi', '', NULL, '和姚給事寓直之作 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0abfe385-6758-41b6-802c-0f37a93a4d9d', '和庫部李員外秋夜寓直之作', '和庫部李員外秋夜寓直之作', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["相庭貽慶遠，才子拜郎初。","起草徯仙閣，焚香臥直廬。","更深河欲斷，節勁柳偏疎。","氣耿凌雲筆，心搖待漏車。","叨榮廁儔侶，省己恧空虛。","徒裴陽春和，難參麗曲餘。"]', '["相庭貽慶远，才子拜郎初。","起草徯仙閣，焚香臥直廬。","更深河欲斷，節勁柳偏疎。","氣耿凌云笔，心搖待漏车。","叨榮廁儔侶，省己恧空虛。","徒裴陽春和，难參丽曲餘。"]', '诗', 'shi', '', NULL, '和庫部李員外秋夜寓直之作 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df23099-5d0d-4d73-9ea7-5b74ac61b4c6', '酬李丹徒見贈之作', '酬李丹徒见贈之作', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["鎮吳稱奧里，試劇仰通才。","近挹人披霧，遙聞境震雷。","一朝逢解榻，累日共銜杯。","連轡登山盡，浮舟望海回。","以予慙拙宦，期子遇良媒。","贈曲南鳧斷，征途北雁催。","更憐江上月，還入鏡中開。"]', '["鎮吳稱奧里，試劇仰通才。","近挹人披霧，遙闻境震雷。","一朝逢解榻，累日共銜杯。","連轡登山尽，浮舟望海回。","以予慙拙宦，期子遇良媒。","贈曲南鳧斷，征途北雁催。","更怜江上月，還入镜中开。"]', '诗', 'shi', '', NULL, '酬李丹徒見贈之作 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('007fb333-4320-469e-8def-1425e465a68a', '使過襄陽登鳳林寺閣', '使過襄陽登鳳林寺閣', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["香閣臨清漢，丹梯隱翠微。","林篁天際密，人世谷中違。","苔石銜仙洞，蓮舟泊釣磯。","山雲浮棟起，江雨入庭飛。","信美雖南國，嚴程限北歸。","幽尋不可再，留步惜芳菲。"]', '["香閣臨清漢，丹梯隐翠微。","林篁天際密，人世谷中違。","苔石銜仙洞，蓮舟泊釣磯。","山云浮棟起，江雨入庭飞。","信美雖南国，嚴程限北归。","幽尋不可再，留步惜芳菲。"]', '诗', 'shi', '', NULL, '使過襄陽登鳳林寺閣 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ac7401-65a5-408c-ac4b-44facc8a0293', '宋公宅送甯諫議', '宋公宅送甯諫議', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["宋公爰創宅，庾氏更誅茅。","間出人三秀，平臨楚四郊。","漢臣來絳節，荆牧動金鐃。","尊溢宜城酒，笙裁曲沃匏。","露荷秋變節，風柳夕鳴梢。","一散陽臺雨，方隨越鳥巢。"]', '["宋公爰創宅，庾氏更誅茅。","间出人三秀，平臨楚四郊。","漢臣来絳節，荆牧动金鐃。","尊溢宜城酒，笙裁曲沃匏。","露荷秋变節，风柳夕鳴梢。","一散陽台雨，方隨越鸟巢。"]', '诗', 'shi', '', NULL, '宋公宅送甯諫議 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce472cf0-c154-4f69-bf9a-2abb3e807187', '送合宮蘇明府頲', '送合宮蘇明府頲', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["鉉府誕英規，公才天下知。","謂乘羔雁族，繼入鳳皇池。","赤縣求人隱，青門起路岐。","翟回車少別，鳧化舃遙馳。","神哭周南境，童歌渭北垂。","賢哉荀奉倩，衮職佇來儀。"]', '["鉉府誕英規，公才天下知。","謂乘羔雁族，繼入鳳皇池。","赤縣求人隐，青门起路岐。","翟回车少別，鳧化舃遙驰。","神哭周南境，童歌渭北垂。","賢哉荀奉倩，衮職佇来儀。"]', '诗', 'shi', '', NULL, '送合宮蘇明府頲 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dfb4a49-d507-428d-84bd-ccfd35da8b71', '送楊六望赴金水', '送楊六望赴金水', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["借問梁山道，嶔岑幾萬重。","遙州刀作字，絕壁劒爲峰。","惜別路窮此，留歡意不從。","憂來生白髮，時晚愛青松。","勿以西南遠，夷歌寢盛容。","台階有高位，寧復久臨邛。"]', '["借问梁山道，嶔岑幾万重。","遙州刀作字，絕壁劒爲峰。","惜別路窮此，留歡意不從。","憂来生白髮，时晚愛青松。","勿以西南远，夷歌寢盛容。","台階有高位，寧复久臨邛。"]', '诗', 'shi', '', NULL, '送楊六望赴金水 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d42ffc26-f0f9-41af-bc33-17f5101a422a', '下桂江龍目灘', '下桂江龙目灘', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["停午出灘險，輕舟容易前。","峰攢入雲樹，崖噴落江泉。","巨石潛山怪，深篁隱洞仙。","鳥遊溪寂寂，猿嘯嶺娟娟。","揮袂日凡幾，我行途已千。","暝投蒼梧郡，愁枕白雲眠。"]', '["停午出灘險，轻舟容易前。","峰攢入云樹，崖噴落江泉。","巨石潛山怪，深篁隐洞仙。","鸟游溪寂寂，猿嘯嶺娟娟。","揮袂日凡幾，我行途已千。","暝投蒼梧郡，愁枕白云眠。"]', '诗', 'shi', '', NULL, '下桂江龍目灘 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2aa9cb4-0de8-49ce-9a69-774afafb9f2f', '入瀧州江', '入瀧州江', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["孤舟泛盈盈，江流日縱橫。","夜雜蛟螭寢，晨披瘴癘行。","潭蒸水沫起，山熱火雲生。","猿躩時能嘯，鳶飛莫敢鳴。","海窮南徼盡，鄉遠北魂驚。","泣向文身國，悲看鑿齒氓。","地偏多育蠱，風惡好相鯨。","余本巖栖客，悠哉慕玉京。","厚恩嘗願答，薄宦不祈成。","違隱乖求志，披荒爲近名。","鏡愁玄髮改，心負紫芝榮。","運啓中興曆，時逢外域清。","祗應保忠信，延促付神明。"]', '["孤舟泛盈盈，江流日縱橫。","夜杂蛟螭寢，晨披瘴癘行。","潭蒸水沫起，山熱火云生。","猿躩时能嘯，鳶飞莫敢鳴。","海窮南徼尽，乡远北魂驚。","泣向文身国，悲看鑿齒氓。","地偏多育蠱，风惡好相鯨。","余本巖栖客，悠哉慕玉京。","厚恩嘗願答，薄宦不祈成。","違隐乖求志，披荒爲近名。","镜愁玄髮改，心負紫芝榮。","運啓中兴曆，时逢外域清。","祗應保忠信，延促付神明。"]', '诗', 'shi', '', NULL, '入瀧州江 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8cff809-a000-45fb-878d-f8af4206f684', '始安秋日', '始安秋日', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["桂林風景異，秋似洛陽春。","晚霽江天好，分明愁殺人。","卷雲山𧥄𧥄，碎石水磷磷。","世業事黃老，妙年孤隱淪。","歸歟臥滄海，何物貴吾身。"]', '["桂林风景異，秋似洛陽春。","晚霽江天好，分明愁殺人。","卷云山𧥄𧥄，碎石水磷磷。","世業事黄老，妙年孤隐淪。","归歟臥滄海，何物貴吾身。"]', '诗', 'shi', '', NULL, '始安秋日 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b60386-1d8c-42ed-8bf2-e7d34ab67096', '桂州黃潭舜祠', '桂州黄潭舜祠', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["虞世巡百越，相傳葬九疑。","精靈遊此地，祠樹日光輝。","禋祭忽羣望，丹青圖二妃。","神來獸率舞，仙去鳳還飛。","日暝山氣落，江空潭靄微。","帝鄉三萬里，乘彼白雲歸。"]', '["虞世巡百越，相傳葬九疑。","精靈游此地，祠樹日光輝。","禋祭忽羣望，丹青圖二妃。","神来獸率舞，仙去鳳還飞。","日暝山氣落，江空潭靄微。","帝乡三万里，乘彼白云归。"]', '诗', 'shi', '', NULL, '桂州黃潭舜祠 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5a66103-ad71-4bca-9224-d44b616630a0', '登粵王臺', '登粵王台', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["江上粵王臺，登高望幾回。","南溟天外合，北戶日邊開。","地濕煙嘗起，山晴雨半來。","冬花採盧橘，夏果摘楊梅。","跡類虞翻枉，人非賈誼才。","歸心不可見，白髮重相催。"]', '["江上粵王台，登高望幾回。","南溟天外合，北戶日邊开。","地濕煙嘗起，山晴雨半来。","冬花採盧橘，夏果摘楊梅。","跡類虞翻枉，人非賈誼才。","归心不可见，白髮重相催。"]', '诗', 'shi', '', NULL, '登粵王臺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aeca15b-2c27-4947-a57d-5daab2082d8a', '早發始興江口至虛氏村作', '早發始兴江口至虛氏村作', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["候曉踰閩嶠，乘春望越臺。","宿雲鵬際落，殘月蚌中開。","薜荔搖青氣，桄榔翳碧苔。","桂香多露裛，石響細泉回。","抱葉玄猿嘯，銜花翡翠來。","南中雖可悅，北思日悠哉。","鬒髮俄成素，丹心已作灰。","何當首歸路，行剪故園萊。"]', '["候晓踰閩嶠，乘春望越台。","宿云鵬際落，殘月蚌中开。","薜荔搖青氣，桄榔翳碧苔。","桂香多露裛，石响細泉回。","抱葉玄猿嘯，銜花翡翠来。","南中雖可悅，北思日悠哉。","鬒髮俄成素，丹心已作灰。","何當首归路，行剪故园萊。"]', '诗', 'shi', '', NULL, '早發始興江口至虛氏村作 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67404753-0e0b-4556-bffa-7409521c6790', '發藤州', '發藤州', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["朝夕苦遄征，孤魂長自驚。","泛舟依雁渚，投館聽猿鳴。","石髮緣溪蔓，林衣埽地輕。","雲峰刻不似，苔蘚畫難成。","露裛千花氣，泉和萬籟聲。","攀幽紅處歇，躋險綠中行。","戀切芝蘭砌，悲纏松柏塋。","丹心江北死，白髮嶺南生。","魑魅天邊國，窮愁海上城。","勞歌意無限，今日爲誰明。"]', '["朝夕苦遄征，孤魂长自驚。","泛舟依雁渚，投館听猿鳴。","石髮緣溪蔓，林衣埽地轻。","云峰刻不似，苔蘚畫难成。","露裛千花氣，泉和万籟声。","攀幽紅处歇，躋險綠中行。","戀切芝蘭砌，悲纏松柏塋。","丹心江北死，白髮嶺南生。","魑魅天邊国，窮愁海上城。","勞歌意無限，今日爲誰明。"]', '诗', 'shi', '', NULL, '發藤州 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11ea7447-a550-497c-9fd5-549b11bdbf60', '遊稱心寺', '游稱心寺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["釋事懷三隱，清襟謁四禪。","江鳴潮未落，林曉日初懸。","寶葉交香雨，金沙吐細泉。","望諧舟客趣，思發海人煙。","顧櫪仍留馬，乘杯久棄船。","未憂龜負嶽，且識鳥耘田。","理契都無象，心冥不寄筌。","安期庶可揖，天地得齊年。"]', '["釋事懷三隐，清襟謁四禪。","江鳴潮未落，林晓日初懸。","寶葉交香雨，金沙吐細泉。","望諧舟客趣，思發海人煙。","顧櫪仍留马，乘杯久棄船。","未憂龟負嶽，且識鸟耘田。","理契都無象，心冥不寄筌。","安期庶可揖，天地得齊年。"]', '诗', 'shi', '', NULL, '遊稱心寺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d855d4fb-399f-45bf-85a6-1af6354a6b31', '遊法華寺', '游法华寺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["高岫擬耆闍，真乘引妙車。","空中結樓殿，意表出雲霞。","後果纏三足，前因感六牙。","宴林薰寶樹，水溜滴金沙。","寒谷梅猶淺，溫庭橘未華。","臺香紅藥亂，塔影綠篁遮。","果漸輪王族，緣超梵帝家。","晨行踏忍草，夜誦得靈花。","江郡將何匹，天都亦未加。","朝來沿泛所，應是逐仙槎。"]', '["高岫擬耆闍，真乘引妙车。","空中結楼殿，意表出云霞。","後果纏三足，前因感六牙。","宴林薰寶樹，水溜滴金沙。","寒谷梅猶淺，溫庭橘未华。","台香紅藥亂，塔影綠篁遮。","果漸輪王族，緣超梵帝家。","晨行踏忍草，夜誦得靈花。","江郡將何匹，天都亦未加。","朝来沿泛所，應是逐仙槎。"]', '诗', 'shi', '', NULL, '遊法華寺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d2629c-80eb-4f46-9754-f348af4eb59f', '夜渡吳松江懷古', '夜渡吳松江懷古', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["宿帆震澤口，曉渡松江濆。","櫂發魚龍氣，舟衝鴻雁羣。","寒潮頓覺滿，暗浦稍將分。","氣出海生日，光清湖起雲。","水鄉盡天衞，歎息爲吳君。","謀士伏劒死，至今悲所聞。"]', '["宿帆震澤口，晓渡松江濆。","櫂發鱼龙氣，舟衝鴻雁羣。","寒潮頓覺满，暗浦稍將分。","氣出海生日，光清湖起云。","水乡尽天衞，歎息爲吳君。","謀士伏劒死，至今悲所闻。"]', '诗', 'shi', '', NULL, '夜渡吳松江懷古 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61986a30-e365-4940-bb94-98027bc4d35d', '謁禹廟', '謁禹廟', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["夏王乘四載，茲地發金符。","峻命終不易，報功疇敢渝。","先驅總昌會，後至伏靈誅。","玉帛空天下，衣冠照海隅。","旋聞厭黃屋，更道出蒼梧。","林表祠轉茂，山阿井詎枯。","舟遷龍負壑，田變鳥芸蕪。","舊物森如在，天威肅未殊。","玄夷屆瑤席，玉女侍清都。","奕奕扃闈邃，軒軒杖衞趨。","氣青連曙海，雲白洗春湖。","猿嘯有時答，禽言常自呼。","靈歆異蒸糈，至樂匪笙竽。","茅殿今文襲，梅梁古製無。","運遙日崇麗，業盛答昭蘇。","伊昔力云盡，而今功尚敷。","揆材非美箭，精享愧生芻。","郡職昧爲理，邦空寧自誣。","下車霰已積，攝事露行濡。","人隱冀多祐，曷唯霑薄軀。"]', '["夏王乘四載，茲地發金符。","峻命終不易，報功疇敢渝。","先驱總昌會，後至伏靈誅。","玉帛空天下，衣冠照海隅。","旋闻厭黄屋，更道出蒼梧。","林表祠轉茂，山阿井詎枯。","舟遷龙負壑，田变鸟芸蕪。","旧物森如在，天威肅未殊。","玄夷屆瑤席，玉女侍清都。","奕奕扃闈邃，軒軒杖衞趨。","氣青連曙海，云白洗春湖。","猿嘯有时答，禽言常自呼。","靈歆異蒸糈，至乐匪笙竽。","茅殿今文襲，梅梁古製無。","運遙日崇丽，業盛答昭蘇。","伊昔力云尽，而今功尚敷。","揆材非美箭，精享愧生芻。","郡職昧爲理，邦空寧自誣。","下车霰已積，攝事露行濡。","人隐冀多祐，曷唯霑薄軀。"]', '诗', 'shi', '', NULL, '謁禹廟 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d7a182-2615-4dd2-9e59-457acb5e7a8f', '遊禹穴回出若邪', '游禹穴回出若邪', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["禹穴今朝到，邪溪此路通。","著書聞太史，鍊藥有仙翁。","鶴往籠猶掛，龍飛劒已空。","石帆搖海上，天鏡落湖中。","水低寒雲白，山邊墜葉紅。","歸舟何慮晚，日暮使樵風。"]', '["禹穴今朝到，邪溪此路通。","著书闻太史，鍊藥有仙翁。","鹤往籠猶掛，龙飞劒已空。","石帆搖海上，天镜落湖中。","水低寒云白，山邊墜葉紅。","归舟何慮晚，日暮使樵风。"]', '诗', 'shi', '', NULL, '遊禹穴回出若邪 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a9473a5-286c-48e5-9ded-f80f5e40c179', '靈隱寺”', '靈隐寺”', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["鷲嶺鬱岧嶢，龍宮鎖寂寥。","樓觀滄海日，門對浙江潮。","桂子月中落，天香雲外飄。","捫蘿登墖遠，刳木取泉遙。","霜薄花更發，冰輕葉未凋。","夙齡尚遐異，搜對滌煩囂。","待入天台路，看余度石橋。"]', '["鷲嶺鬱岧嶢，龙宮鎖寂寥。","楼观滄海日，门对浙江潮。","桂子月中落，天香云外飄。","捫蘿登墖远，刳木取泉遙。","霜薄花更發，冰轻葉未凋。","夙齡尚遐異，搜对滌煩囂。","待入天台路，看余度石橋。"]', '诗', 'shi', '', NULL, '靈隱寺” 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4908dd7f-5c8a-4818-a912-4a4109ad39a1', '遊雲門寺', '游云门寺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["維舟探靜域，作禮事尊經。","投跡一蕭散，爲心自杳冥。","龕依大禹穴，樓倚少微星。","沓嶂圍蘭若，回溪抱竹庭。","覺花塗砌白，甘露洗山青。","雁塔鶱金地，虹橋轉翠屏。","人天宵現景，神鬼晝潛形。","理勝常虛寂，緣空自感靈。","入禪從鴿遶，說法有龍聽。","劫累終期滅，塵躬且未寧。","搖搖不安寐，待月詠巖扃。"]', '["維舟探静域，作禮事尊經。","投跡一蕭散，爲心自杳冥。","龕依大禹穴，楼倚少微星。","沓嶂圍蘭若，回溪抱竹庭。","覺花塗砌白，甘露洗山青。","雁塔鶱金地，虹橋轉翠屏。","人天宵現景，神鬼晝潛形。","理勝常虛寂，緣空自感靈。","入禪從鴿遶，说法有龙听。","劫累終期滅，塵躬且未寧。","搖搖不安寐，待月詠巖扃。"]', '诗', 'shi', '', NULL, '遊雲門寺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('526d3ff1-9a30-418e-a017-f9629ee0c34d', '早發韶州', '早發韶州', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["炎徼行應盡，回瞻鄉路遙。","珠厓天外郡，銅柱海南標。","日夜清明少，春冬霧雨饒。","身經大火熱，顏入瘴江消。","觸影含沙怒，逢人女草搖。","露濃看菌濕，風颶覺船飄。","直禦魑將魅，寧論鴟與鴞。","虞翻思報國，許靖願歸朝。","綠樹秦京道，青雲洛水橋。","故園長在目，魂去不須招。"]', '["炎徼行應尽，回瞻乡路遙。","珠厓天外郡，銅柱海南標。","日夜清明少，春冬霧雨饒。","身經大火熱，顏入瘴江消。","觸影含沙怒，逢人女草搖。","露濃看菌濕，风颶覺船飄。","直禦魑將魅，寧論鴟與鴞。","虞翻思報国，許靖願归朝。","綠樹秦京道，青云洛水橋。","故园长在目，魂去不須招。"]', '诗', 'shi', '', NULL, '早發韶州 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e553fe91-93f1-46a9-a46e-9c6346bc9394', '早入清遠峽', '早入清远峽', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["傳聞峽山好，旭日櫂前沂。","雨色搖丹嶂，泉聲聒翠微。","兩巖天作帶，萬壑樹披衣。","秋菊迎霜序，春藤礙日輝。","翳潭花似織，緣嶺竹成圍。","寂歷環沙浦，蔥蘢轉石圻。","露餘江未熱，風落瘴初稀。","猿飲排虛上，禽驚掠水飛。","榜童夷唱合，樵女越吟歸。","良候斯爲美，邊愁自有違。","誰言望鄉國，流涕失芳菲。"]', '["傳闻峽山好，旭日櫂前沂。","雨色搖丹嶂，泉声聒翠微。","兩巖天作带，万壑樹披衣。","秋菊迎霜序，春藤礙日輝。","翳潭花似织，緣嶺竹成圍。","寂歷环沙浦，蔥蘢轉石圻。","露餘江未熱，风落瘴初稀。","猿饮排虛上，禽驚掠水飞。","榜童夷唱合，樵女越吟归。","良候斯爲美，邊愁自有違。","誰言望乡国，流涕失芳菲。"]', '诗', 'shi', '', NULL, '早入清遠峽 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d2d1bb-c188-4a1c-a083-0cd47f5cc853', '發端州初入西江', '發端州初入西江', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["問我將何去？清晨泝越溪。","翠微縣宿雨，丹壑飲晴霓。","樹影捎雲密，藤陰覆水低。","潮回出浦駛，洲轉望鄉迷。","人意長懷北，江行日向西。","破顏看鵲喜，拭淚聽猿嗁/。","骨肉初分愛，親朋忽解攜。","路遙魂欲斷，身辱理能齊。","疇日三山意，于茲萬緒暌。","金陵有仙館，即事尋丹梯。"]', '["问我將何去？清晨泝越溪。","翠微縣宿雨，丹壑饮晴霓。","樹影捎云密，藤陰覆水低。","潮回出浦駛，洲轉望乡迷。","人意长懷北，江行日向西。","破顏看鵲喜，拭泪听猿嗁/。","骨肉初分愛，親朋忽解携。","路遙魂欲斷，身辱理能齊。","疇日三山意，于茲万緒暌。","金陵有仙館，即事尋丹梯。"]', '诗', 'shi', '', NULL, '發端州初入西江 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb9530d2-e4c7-4c34-9214-06c28ca586bf', '渡漢江', '渡漢江', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["嶺外音書斷，經冬復歷春。","近鄉情更怯，不敢問來人。"]', '["嶺外音书斷，經冬复歷春。","近乡情更怯，不敢问来人。"]', '诗', 'shi', '', NULL, '渡漢江 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ba7cc1-7482-4aaa-8312-8b00ef30d567', '嵩山夜還', '嵩山夜還', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["家住嵩山下，好采舊山薇。","自省遊泉石，何曾不夜歸。"]', '["家住嵩山下，好采旧山薇。","自省游泉石，何曾不夜归。"]', '诗', 'shi', '', NULL, '嵩山夜還 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('351e8172-26b4-4057-b873-77ce777f7f47', '湖中別鑒上人', '湖中別鑒上人', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["願與道林近，在意逍遙篇。","自有靈佳寺，何用沃洲禪。"]', '["願與道林近，在意逍遙篇。","自有靈佳寺，何用沃洲禪。"]', '诗', 'shi', '', NULL, '湖中別鑒上人 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e649ebb-b819-4b66-871e-d5bfcd5b2782', '題鑒上人房二首 一', '題鑒上人房二首 一', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["落花雙樹積，芳草一庭春。","玩之堪興異，何必見幽人。"]', '["落花雙樹積，芳草一庭春。","玩之堪兴異，何必见幽人。"]', '诗', 'shi', '', NULL, '題鑒上人房二首 一 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b41486f-13da-4561-9dcc-da72979e7556', '題鑒上人房二首 二', '題鑒上人房二首 二', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["晚入應真理，經行尚未回。","房中無俗物，林下有青苔。"]', '["晚入應真理，經行尚未回。","房中無俗物，林下有青苔。"]', '诗', 'shi', '', NULL, '題鑒上人房二首 二 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7251108e-2dda-49e4-94cb-faa0033f5320', '答田徵君', '答田徵君', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["出遊杳何處？遲回伊洛間。","歸寢忽成夢，宛在嵩丘山。"]', '["出游杳何处？遲回伊洛间。","归寢忽成梦，宛在嵩丘山。"]', '诗', 'shi', '', NULL, '答田徵君 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf18b593-adc4-416c-9ec7-3d77b2437692', '傷曹娘二首 一', '傷曹娘二首 一', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["鳳飛樓伎絕，鸞死鏡臺空。","獨憐脂粉氣，猶著舞衣中。"]', '["鳳飞楼伎絕，鸾死镜台空。","独怜脂粉氣，猶著舞衣中。"]', '诗', 'shi', '', NULL, '傷曹娘二首 一 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f1412bd-f54f-4931-83b0-833a70b77233', '傷曹娘二首 二', '傷曹娘二首 二', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["河伯憐嬌態，馮夷要姝妓。","寄言遊戲人，莫弄黃河水。"]', '["河伯怜嬌態，馮夷要姝妓。","寄言游戲人，莫弄黄河水。"]', '诗', 'shi', '', NULL, '傷曹娘二首 二 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93fac48d-d564-4359-8953-6d49af89ecb5', '河陽', '河陽', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["昔日河陽縣，氛氳香氣多。","曹娘嬌態盡，春樹不堪過。"]', '["昔日河陽縣，氛氳香氣多。","曹娘嬌態尽，春樹不堪過。"]', '诗', 'shi', '', NULL, '河陽 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4fa7902-0797-41ac-a97e-dda1f68c5471', '燕巢軍幕', '燕巢軍幕', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["北關憐翠幕，不是厭朱樓。","故來呈燕頷，報道欲封侯。"]', '["北关怜翠幕，不是厭朱楼。","故来呈燕頷，報道欲封侯。"]', '诗', 'shi', '', NULL, '燕巢軍幕 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40336126-4c18-4de6-92a9-c73919cd8829', '苑中遇雪應制', '苑中遇雪應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["紫禁仙輿詰旦來，青旂遙倚望春臺。","不知庭霰今朝落，疑是林花昨夜開。"]', '["紫禁仙輿詰旦来，青旂遙倚望春台。","不知庭霰今朝落，疑是林花昨夜开。"]', '诗', 'shi', '', NULL, '苑中遇雪應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea215df-4774-4510-8e1f-65e31354d19a', '送司馬道士遊天台', '送司马道士游天台', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["羽客笙歌此地違，離筵數處白雲飛。","蓬萊闕下長相憶，桐柏山頭去不歸。"]', '["羽客笙歌此地違，離筵數处白云飞。","蓬萊闕下长相憶，桐柏山头去不归。"]', '诗', 'shi', '', NULL, '送司馬道士遊天台 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5ada7d-b0a4-45f6-8454-d8a4ef231824', '登逍遙樓', '登逍遙楼', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["逍遙樓上望鄉關，綠水泓澄雲霧間。","北去衡陽二千里，無因雁足繫書還。"]', '["逍遙楼上望乡关，綠水泓澄云霧间。","北去衡陽二千里，無因雁足繫书還。"]', '诗', 'shi', '', NULL, '登逍遙樓 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77751a08-31d2-442b-87d2-e74107e96640', '奉和春日玩雪應制', '奉和春日玩雪應制', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["北闕彤雲掩曙霞，東風吹雪舞山家。","瓊章定少千人和，銀樹長芳六出花。"]', '["北闕彤云掩曙霞，东风吹雪舞山家。","瓊章定少千人和，銀樹长芳六出花。"]', '诗', 'shi', '', NULL, '奉和春日玩雪應制 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb1fbfbf-5eb7-40cf-ae94-66b7afa11913', '傷曹娘二首 一', '傷曹娘二首 一', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["可憐冥漠去何之，獨立丰茸無見期。","君看水上芙蓉色，恰似生前歌舞時。"]', '["可怜冥漠去何之，独立丰茸無见期。","君看水上芙蓉色，恰似生前歌舞时。"]', '诗', 'shi', '', NULL, '傷曹娘二首 一 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e562b576-1601-42f5-a67a-58a7f93c33c5', '傷曹娘二首 二', '傷曹娘二首 二', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["前溪妙舞今應盡，子夜新歌遂不傳。","無復綺羅嬌白日，直將珠玉閉黃泉。"]', '["前溪妙舞今應尽，子夜新歌遂不傳。","無复綺羅嬌白日，直將珠玉閉黄泉。"]', '诗', 'shi', '', NULL, '傷曹娘二首 二 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a751a97f-a92c-423d-85ea-4357f7ab4798', '郡宅中齋', '郡宅中斋', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["郡宅枕層嶺，春湖繞芳甸。","雲甍出萬家，臥覽皆已徧。","漁商汗成雨，廨邑明若練。","越俗鏡中行，夏祠雲表見。","茲都信盤鬱，英遠常棲眄。","王子事黃老，獨樂恣遊衍。","謝公念蒼生，同憂感推薦。","靈越多秀士，運闊無由面。","神理翳青山，風流滿黃卷。","揆予謬承獎，自惜從纓弁。","瑤水執仙羈，金閨負時選。","晨趨博望苑，夜直明光殿。","一朝罷臺閣，萬里違鄉縣。","風土足慰心，況悅年芳變。","淮廩佇滋實，沂歌非所羨。","訟寢歸四明，齡頹親九轉。","微尚本江海，少留豈交戰。","唯餘後凋色，竊比東南箭。"]', '["郡宅枕層嶺，春湖繞芳甸。","云甍出万家，臥覽皆已徧。","漁商汗成雨，廨邑明若練。","越俗镜中行，夏祠云表见。","茲都信盤鬱，英远常棲眄。","王子事黄老，独乐恣游衍。","謝公念蒼生，同憂感推薦。","靈越多秀士，運闊無由面。","神理翳青山，风流满黄卷。","揆予謬承獎，自惜從纓弁。","瑤水執仙羈，金閨負时選。","晨趨博望苑，夜直明光殿。","一朝罷台閣，万里違乡縣。","风土足慰心，況悅年芳变。","淮廩佇滋實，沂歌非所羨。","訟寢归四明，齡頹親九轉。","微尚本江海，少留豈交戰。","唯餘後凋色，竊比东南箭。"]', '诗', 'shi', '', NULL, '郡宅中齋 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bc7692b-bd15-43ad-ac4c-7bb86d97d25a', '稱心寺', '稱心寺', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["步陟招提宮，北極山海觀。","千巖遞縈繞，萬壑殊悠漫。","喬木轉夕陽，文軒劃清渙。","泄雲多表裏，驚潮每昏旦。","問予金門客，何事滄洲畔。","謬以三署資，來刺百城半。","人隱尚未弭，歲華豈兼玩。","東山桂枝芳，明發坐盈歎。"]', '["步陟招提宮，北極山海观。","千巖遞縈繞，万壑殊悠漫。","喬木轉夕陽，文軒劃清渙。","泄云多表裏，驚潮每昏旦。","问予金门客，何事滄洲畔。","謬以三署資，来刺百城半。","人隐尚未弭，歲华豈兼玩。","东山桂枝芳，明發坐盈歎。"]', '诗', 'shi', '', NULL, '稱心寺 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('368fc6bb-1636-419e-8ddb-cdc1dd07a1ca', '新年作', '新年作', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["鄉心新歲切，天畔獨澘然。","老至居人下，春歸在客先。","嶺猨同旦暮，江柳共風煙。","已似長沙傅，從今又幾年。"]', '["乡心新歲切，天畔独澘然。","老至居人下，春归在客先。","嶺猨同旦暮，江柳共风煙。","已似长沙傅，從今又幾年。"]', '诗', 'shi', '', NULL, '新年作 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e95ada9f-e092-49a9-847d-a535158838ed', '剪綵', '剪綵', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["駐想持金錯，居然作管灰。","綺羅纖手製，桃李向春開。","拾藻蜂初泊，銜花鳥未回。","不言將巧笑，飜逐美人來。"]', '["駐想持金錯，居然作管灰。","綺羅纖手製，桃李向春开。","拾藻蜂初泊，銜花鸟未回。","不言將巧笑，飜逐美人来。"]', '诗', 'shi', '', NULL, '剪綵 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b32afc30-867f-4732-aa23-f56b89414aef', '七夕', '七夕', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["傳道仙星媛，年年會水隅。","停梭借蟋蟀，留巧付蜘蛛。","去晝從雲請，歸輪竚日輸。","莫言相見闊，天上日應殊。"]', '["傳道仙星媛，年年會水隅。","停梭借蟋蟀，留巧付蜘蛛。","去晝從云請，归輪竚日輸。","莫言相见闊，天上日應殊。"]', '诗', 'shi', '', NULL, '七夕 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a822e4-fffa-4886-9ac6-d7369f8f6407', '桂州陪王都督晦日宴逍遙樓', '桂州陪王都督晦日宴逍遙楼', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["晦節高樓望，山川一半春。","意隨蓂葉盡，愁共柳條新。","投刺登龍日，開懷納鳥晨。","兀然心似醉，不覺有吾身。"]', '["晦節高楼望，山川一半春。","意隨蓂葉尽，愁共柳條新。","投刺登龙日，开懷納鸟晨。","兀然心似醉，不覺有吾身。"]', '诗', 'shi', '', NULL, '桂州陪王都督晦日宴逍遙樓 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab0826a-73b5-45a6-b24d-2971633ec7af', '和趙員外桂陽橋遇佳人', '和趙員外桂陽橋遇佳人', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["江雨朝飛浥細塵，陽橋花柳不勝春。","金鞍白馬來從趙，玉面紅妝本姓秦。","妬女猶憐鏡中髮，侍兒堪感路傍人。","蕩舟爲樂非吾事，自歎空閨夢寐頻。"]', '["江雨朝飞浥細塵，陽橋花柳不勝春。","金鞍白马来從趙，玉面紅妝本姓秦。","妬女猶怜镜中髮，侍兒堪感路傍人。","蕩舟爲乐非吾事，自歎空閨梦寐頻。"]', '诗', 'shi', '', NULL, '和趙員外桂陽橋遇佳人 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7135ccc-8edb-46e3-9709-eecef6496118', '函谷關', '函谷关', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["至人□□識仙風，瑞靄丹光遠鬱蔥。","靈跡才辭周柱下，祥氛已入函關中。","不從紫氣臺端候，何得青華觀裏逢。","欲訪乘牛求寶籙，願隨鶴駕徧瑤空。"]', '["至人□□識仙风，瑞靄丹光远鬱蔥。","靈跡才辞周柱下，祥氛已入函关中。","不從紫氣台端候，何得青华观裏逢。","欲訪乘牛求寶籙，願隨鹤駕徧瑤空。"]', '诗', 'shi', '', NULL, '函谷關 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f23aff-2d5b-47be-aa3d-5e1d745f3a85', '詠省壁畫鶴', '詠省壁畫鹤', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["粉壁圖仙鶴，昂藏真氣多。","鶱飛竟不去，當是戀恩波。"]', '["粉壁圖仙鹤，昂藏真氣多。","鶱飞竟不去，當是戀恩波。"]', '诗', 'shi', '', NULL, '詠省壁畫鶴 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69ab265b-f508-433f-90ea-dfc1d9cf2edc', '廣州朱長史座觀妓', '廣州朱长史座观妓', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["歌舞須連夜，神仙莫放歸。","參差隨暮雨，前路濕人衣。"]', '["歌舞須連夜，神仙莫放归。","參差隨暮雨，前路濕人衣。"]', '诗', 'shi', '', NULL, '廣州朱長史座觀妓 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fe8887e-2239-44a7-807d-7328609e3104', '謁二妃廟', '謁二妃廟', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["還以金屋貴，留茲寶席尊。","江鳧嘯風雨，山鬼泣朝昏。"]', '["還以金屋貴，留茲寶席尊。","江鳧嘯风雨，山鬼泣朝昏。"]', '诗', 'shi', '', NULL, '謁二妃廟 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8100eca2-fc61-48c6-834b-d9e654cc741b', '贈嚴侍御', '贈嚴侍御', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["受脤清邊服，乘驄歷塞塵。","當聞漢雪恥，羞共虜和親。"]', '["受脤清邊服，乘驄歷塞塵。","當闻漢雪恥，羞共虜和親。"]', '诗', 'shi', '', NULL, '贈嚴侍御 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c790d955-dd59-4f5e-bc34-af137f0e4ec5', '在荆州重赴嶺南', '在荆州重赴嶺南', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["夢澤三秋日，蒼梧一片雲。","還將鵷鷺羽，重入鷓鴣羣。"]', '["梦澤三秋日，蒼梧一片云。","還將鵷鷺羽，重入鷓鴣羣。"]', '诗', 'shi', '', NULL, '在荆州重赴嶺南 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d94a2ea-6307-42fb-a73f-3c0a558d728a', '則天皇后挽歌', '則天皇后挽歌', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["象物行周禮，衣冠集漢都。","誰憐事虞舜，下里泣蒼梧。"]', '["象物行周禮，衣冠集漢都。","誰怜事虞舜，下里泣蒼梧。"]', '诗', 'shi', '', NULL, '則天皇后挽歌 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ded249cc-2194-4788-a429-04997aadce9f', '鄧國太夫人挽歌', '鄧国太夫人挽歌', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["鸞死鉛妝歇，人亡錦字空。","悲端若能減，渭水亦應窮。"]', '["鸾死鉛妝歇，人亡錦字空。","悲端若能減，渭水亦應窮。"]', '诗', 'shi', '', NULL, '鄧國太夫人挽歌 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caaac61c-34aa-4488-88fa-47475740435a', '楊將軍挽歌', '楊將軍挽歌', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["亭寒照苦月，隴暗積愁雲。","今日山門樹，何處有將軍。"]', '["亭寒照苦月，隴暗積愁云。","今日山门樹，何处有將軍。"]', '诗', 'shi', '', NULL, '楊將軍挽歌 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d91271-f7da-4561-94fc-af8fef298918', '塞垣行', '塞垣行', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["疾風卷溟海，萬里揚砂礫。","仰望不見天，昏昏竟朝夕。","是時軍兩進，東拒復西敵。","蔽山張旗鼓，間道潛鋒鏑。","精騎突曉圍，奇兵襲暗壁。","十月邊塞寒，四山沍陰積。","雨雪鴈南飛，風塵景西迫。","昔我事討論，未嘗怠經籍。","一朝棄筆硯，十年操矛戟。","豈要黃河誓，須勒燕然石。","可嗟牧羊臣，海上久爲客。"]', '["疾风卷溟海，万里揚砂礫。","仰望不见天，昏昏竟朝夕。","是时軍兩進，东拒复西敵。","蔽山張旗鼓，间道潛鋒鏑。","精騎突晓圍，奇兵襲暗壁。","十月邊塞寒，四山沍陰積。","雨雪鴈南飞，风塵景西迫。","昔我事討論，未嘗怠經籍。","一朝棄笔硯，十年操矛戟。","豈要黄河誓，須勒燕然石。","可嗟牧羊臣，海上久爲客。"]', '诗', 'shi', '', NULL, '塞垣行 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaed4e1f-e6e3-47de-bac5-42c37f84d666', '送梁卿王郎中使東蕃弔冊', '送梁卿王郎中使东蕃弔冊', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["梁侯上卿秀，王子中臺傑。","贈冊綏九夷，旌旃下雙闕。","西堂禮樂送，南陌軒車別。","征路入海雲，行舟泝江月。","茲邦久欽化，歷載歸朝謁。","皇心諒所嘉，寄爾宣風烈。"]', '["梁侯上卿秀，王子中台傑。","贈冊綏九夷，旌旃下雙闕。","西堂禮乐送，南陌軒车別。","征路入海云，行舟泝江月。","茲邦久欽化，歷載归朝謁。","皇心諒所嘉，寄爾宣风烈。"]', '诗', 'shi', '', NULL, '送梁卿王郎中使東蕃弔冊 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65f0369a-f41b-4901-b11d-6e6bc9d2709c', '餞唐州高使君赴任', '餞唐州高使君赴任', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["芳春桃李時，京都物華好。","爲岳豈不貴，所悲涉遠道。","遠道不可思，宿昔夢見之。","贈君雙佩刀，日夕視來期。"]', '["芳春桃李时，京都物华好。","爲岳豈不貴，所悲涉远道。","远道不可思，宿昔梦见之。","贈君雙佩刀，日夕視来期。"]', '诗', 'shi', '', NULL, '餞唐州高使君赴任 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102a9d8c-3ed1-4f24-b6f7-32ede2a814f2', '冀北春望', '冀北春望', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["迴首覽燕趙，春生兩河間。","曠然萬里餘，際海不見山。","雨歇青林潤，煙空綠野閑。","問鄉何處所，目送白雲還。"]', '["迴首覽燕趙，春生兩河间。","曠然万里餘，際海不见山。","雨歇青林潤，煙空綠野闲。","问乡何处所，目送白云還。"]', '诗', 'shi', '', NULL, '冀北春望 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('495d3ae4-4bc2-46f3-a2bd-1fda9353283f', '景龍二年余自門下平章事削階授江州員外司馬尋拜襄州刺史春日赴襄陽途中言志', '景龙二年余自门下平章事削階授江州員外司马尋拜襄州刺史春日赴襄陽途中言志', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["余本燕趙人，秉心愚且直。","羣籍備所見，孤貞每自飭。","徇祿期代耕，受任亦量力。","幸逢休明時，朝野兩薦推。","一朝趨金門，十載奉瑤墀。","入掌遷固筆，出參枚馬詞。","吏部既三踐，中書亦五期。","進無負鼎說，退慙補衮詩。","常恐嬰悔吝，不得少酬私。","嗷嗷路傍子，納謗紛無已。","上動明主疑，下貽大臣恥。","毫髮顧無累，冰壺邈自持。","天道何期平，幽冤終見明。","始佐廬陵郡，尋牧襄陽城。","彤幃荷新寵，朱黻蒙舊榮。","力薄慙任重，恩深知命輕。","飭徒留前路，行子悲且慕。","猶聞長樂鐘，尚辨青門樹。","慈親不忍訣，昆弟默相顧。","去去勿重陳，川長日云暮。"]', '["余本燕趙人，秉心愚且直。","羣籍備所见，孤貞每自飭。","徇祿期代耕，受任亦量力。","幸逢休明时，朝野兩薦推。","一朝趨金门，十載奉瑤墀。","入掌遷固笔，出參枚马词。","吏部既三踐，中书亦五期。","進無負鼎说，退慙補衮诗。","常恐嬰悔吝，不得少酬私。","嗷嗷路傍子，納謗紛無已。","上动明主疑，下貽大臣恥。","毫髮顧無累，冰壺邈自持。","天道何期平，幽冤終见明。","始佐廬陵郡，尋牧襄陽城。","彤幃荷新寵，朱黻蒙旧榮。","力薄慙任重，恩深知命轻。","飭徒留前路，行子悲且慕。","猶闻长乐鐘，尚辨青门樹。","慈親不忍訣，昆弟默相顧。","去去勿重陳，川长日云暮。"]', '诗', 'shi', '', NULL, '景龍二年余自門下平章事削階授江州員外司馬尋拜襄州刺史春日赴襄陽途中言志 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('557ff1f6-8ed9-4c9d-80ea-2d0ea82f54de', '大漠行', '大漠行', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["單于犯薊堧，驃騎略蕭邊。","南山木葉飛下地，北海蓬根亂上天。","科斗連營太原道，魚麗合陣武威川。","三軍遙倚杖，萬里相馳逐。","旌斾悠悠靜瀚源，鼙鼓喧喧動盧谷。","窮徼上幽陵，吁嗟倦寢興。","馬蹄凍溜石，胡毳暖生冰。","雲沙泱漭天光閉，河塞陰沈海色凝。","崆峒異國誰能托，蕭索邊心常不樂。","近見行人畏白龍，遙聞公主愁黃鶴。","陽春半，岐路間。","瑤臺苑，玉門關。","百花芳樹紅將歇，二月蘭皐綠未還。","陣雲不散魚龍水，雨雪猶飛鴻鴈山。","山嶂連緜不可極，路遠辛勤夢顏色。","北堂萱草不寄來，東園桃李長相憶。","漢將紛紜攻戰盈，胡寇蕭條幽朔清。","韓君拜節偏知遠，鄭吉驅旌坐見迎。","火絕煙沈右西極，谷靜山空左北平。","但使將軍能百戰，不須天子築長城。"]', '["單于犯薊堧，驃騎略蕭邊。","南山木葉飞下地，北海蓬根亂上天。","科斗連營太原道，鱼丽合陣武威川。","三軍遙倚杖，万里相驰逐。","旌斾悠悠静瀚源，鼙鼓喧喧动盧谷。","窮徼上幽陵，吁嗟倦寢兴。","马蹄凍溜石，胡毳暖生冰。","云沙泱漭天光閉，河塞陰沈海色凝。","崆峒異国誰能托，蕭索邊心常不乐。","近见行人畏白龙，遙闻公主愁黄鹤。","陽春半，岐路间。","瑤台苑，玉门关。","百花芳樹紅將歇，二月蘭皐綠未還。","陣云不散鱼龙水，雨雪猶飞鴻鴈山。","山嶂連緜不可極，路远辛勤梦顏色。","北堂萱草不寄来，东园桃李长相憶。","漢將紛紜攻戰盈，胡寇蕭條幽朔清。","韓君拜節偏知远，鄭吉驱旌坐见迎。","火絕煙沈右西極，谷静山空左北平。","但使將軍能百戰，不須天子築长城。"]', '诗', 'shi', '', NULL, '大漠行 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67b35d86-5ac2-4c72-aaf3-d112392f999e', '奉和登驪山高頂寓目應制', '奉和登驪山高頂寓目應制', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["名山何壯哉，玄覽一徘徊。","御路穿林轉，旌門倚石開。","煙霞肘後發，河塞掌中來。","不學蓬壺遠，經年猶未迴。"]', '["名山何壯哉，玄覽一徘徊。","御路穿林轉，旌门倚石开。","煙霞肘後發，河塞掌中来。","不学蓬壺远，經年猶未迴。"]', '诗', 'shi', '', NULL, '奉和登驪山高頂寓目應制 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8fdbfa3-921a-4d20-a25f-e7a81b18e928', '侍宴長寧公主東莊應制', '侍宴长寧公主东莊應制', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["沁園東郭外，鸞駕一遊盤。","水榭宜時陟，山樓向晚看。","席臨天女貴，杯接近臣歡。","聖藻懸宸象，微臣竊仰觀。"]', '["沁园东郭外，鸾駕一游盤。","水榭宜时陟，山楼向晚看。","席臨天女貴，杯接近臣歡。","聖藻懸宸象，微臣竊仰观。"]', '诗', 'shi', '', NULL, '侍宴長寧公主東莊應制 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c038f3b7-f5e0-41a7-841d-7a00592ed751', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["懷戎前策備，降女舊因修。","簫鼓辭家怨，旌旃出塞愁。","尚孩中念切，方遠御慈留。","顧乏謀臣用，仍勞聖主憂。"]', '["懷戎前策備，降女旧因修。","簫鼓辞家怨，旌旃出塞愁。","尚孩中念切，方远御慈留。","顧乏謀臣用，仍勞聖主憂。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b93786a3-98e5-4f85-9e0a-1e580187a660', '幸白鹿觀應制', '幸白鹿观應制', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["御旗探紫籙，仙杖闢丹丘。","捧藥芝童下，焚香桂女留。","鸞歌無歲月，鶴語記春秋。","臣朔真何幸，常陪漢武遊。"]', '["御旗探紫籙，仙杖闢丹丘。","捧藥芝童下，焚香桂女留。","鸾歌無歲月，鹤語記春秋。","臣朔真何幸，常陪漢武游。"]', '诗', 'shi', '', NULL, '幸白鹿觀應制 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9140947f-72ac-49e2-90f9-42f04f3bc302', '幸梨園亭觀打毬應制', '幸梨园亭观打毬應制', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["年光陌上發，香輦禁中遊。","草綠鴛鴦殿，花明翡翠樓。","寶杯承露酌，仙管雜風流。","今日陪歡豫，皇恩不可酬。"]', '["年光陌上發，香輦禁中游。","草綠鴛鴦殿，花明翡翠楼。","寶杯承露酌，仙管杂风流。","今日陪歡豫，皇恩不可酬。"]', '诗', 'shi', '', NULL, '幸梨園亭觀打毬應制 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0f005e8-33d2-41da-b44b-55654e121f20', '慈恩寺九日應制', '慈恩寺九日應制', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["帝里重陽節，香園萬乘來。","却邪萸結佩，獻壽菊傳杯。","塔類承天湧，門疑待佛開。","睿詞懸日月，長得仰昭回。"]', '["帝里重陽節，香园万乘来。","却邪萸結佩，獻壽菊傳杯。","塔類承天湧，门疑待佛开。","睿词懸日月，长得仰昭回。"]', '诗', 'shi', '', NULL, '慈恩寺九日應制 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1442648-fc60-4566-a97a-ca92f87af08f', '折楊柳', '折楊柳', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["二月風光半，三邊戍不還。","年華妾自惜，楊柳爲君攀。","落絮縈衫袖，垂條拂髻鬟。","那堪音信斷，流涕望陽關。"]', '["二月风光半，三邊戍不還。","年华妾自惜，楊柳爲君攀。","落絮縈衫袖，垂條拂髻鬟。","那堪音信斷，流涕望陽关。"]', '诗', 'shi', '', NULL, '折楊柳 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('566f5337-3b5a-450c-9f88-26bc86ed4f0f', '邊愁', '邊愁', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["九月蓬根斷，三邊草葉腓。","風塵馬變色，霜雪劒生衣。","客思愁陰晚，邊書驛騎歸。","殷勤鳳樓上，還袂及春暉。"]', '["九月蓬根斷，三邊草葉腓。","风塵马变色，霜雪劒生衣。","客思愁陰晚，邊书驛騎归。","殷勤鳳楼上，還袂及春暉。"]', '诗', 'shi', '', NULL, '邊愁 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2211c73d-27d4-4232-a437-1e314f37234b', '婕妤怨', '婕妤怨', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["不分君恩斷，新妝視鏡中。","容華尚春日，嬌愛已秋風。","枕席臨窗曉，帷屏向月空。","年年後庭樹，榮落在深宮。"]', '["不分君恩斷，新妝視镜中。","容华尚春日，嬌愛已秋风。","枕席臨窗晓，帷屏向月空。","年年後庭樹，榮落在深宮。"]', '诗', 'shi', '', NULL, '婕妤怨 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95969eff-695e-4eca-884a-677b8596a385', '酬杜麟臺春思', '酬杜麟台春思', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["春還上林苑，花滿洛陽城。","鴛衾夜凝思，龍鏡曉含情。","憶夢殘燈落，離魂暗馬驚。","可憐朝與暮，樓上獨盈盈。"]', '["春還上林苑，花满洛陽城。","鴛衾夜凝思，龙镜晓含情。","憶梦殘灯落，離魂暗马驚。","可怜朝與暮，楼上独盈盈。"]', '诗', 'shi', '', NULL, '酬杜麟臺春思 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('375fef6a-8fdf-4728-8ec1-02f1467bcad7', '寄天台司馬先生', '寄天台司马先生', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["聞有三元客，祈仙九轉成。","人間白雲返，天上赤龍迎。","尚惜金芝晚，仍攀琪樹榮。","何年緱嶺上，一謝洛陽城。"]', '["闻有三元客，祈仙九轉成。","人间白云返，天上赤龙迎。","尚惜金芝晚，仍攀琪樹榮。","何年緱嶺上，一謝洛陽城。"]', '诗', 'shi', '', NULL, '寄天台司馬先生 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c782ff7-202f-4c0f-8e8e-cbcd922e3dff', '唐都尉山池', '唐都尉山池', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["曲渚颺輕舟，前谿釣晚流。","鴈翻蒲葉起，魚撥荇花遊。","金子懸湘柚，珠房折海榴。","幽尋惜未已，清月半西樓。"]', '["曲渚颺轻舟，前谿釣晚流。","鴈翻蒲葉起，鱼撥荇花游。","金子懸湘柚，珠房折海榴。","幽尋惜未已，清月半西楼。"]', '诗', 'shi', '', NULL, '唐都尉山池 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b75a1a8f-0e5f-44f6-849a-ca8032ef04ad', '江樓夕望', '江楼夕望', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["試陟江樓望，悠悠去國情。","楚山霞外斷，漢水月中平。","公子留遺邑，夫人有舊城。"]', '["試陟江楼望，悠悠去国情。","楚山霞外斷，漢水月中平。","公子留遺邑，夫人有旧城。"]', '诗', 'shi', '', NULL, '江樓夕望 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe978521-5853-4eac-916a-a46ab192914c', '襄城即事', '襄城即事', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["子牟懷魏闕，元凱滯襄城。","冠蓋仍爲里，沙臺尚識名。","山光晴後綠，江色晚來清。"]', '["子牟懷魏闕，元凱滯襄城。","冠蓋仍爲里，沙台尚識名。","山光晴後綠，江色晚来清。"]', '诗', 'shi', '', NULL, '襄城即事 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee5eb3d-c967-496e-a456-47bf7b4cfaa2', '秦州薛都督挽詞', '秦州薛都督挽词', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["十里絳山幽，千年汾水流。","碑傳門客見，劒是故人留。","隴樹煙含夕，山門月照秋。","古來鐘鼎盛，共盡一嵩丘。"]', '["十里絳山幽，千年汾水流。","碑傳门客见，劒是故人留。","隴樹煙含夕，山门月照秋。","古来鐘鼎盛，共尽一嵩丘。"]', '诗', 'shi', '', NULL, '秦州薛都督挽詞 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed09bc3f-c8fb-46b8-9e97-1f01efd60dfc', '奉和春日幸望春宮', '奉和春日幸望春宮', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["澹蕩春光滿曉空，逍遙御輦入離宮。","山河眺望雲天外，臺榭參差煙霧中。","庭際花飛錦繡合，枝間鳥囀管弦同。","即此歡娛齊鎬宴，唯應率舞樂薰風。"]', '["澹蕩春光满晓空，逍遙御輦入離宮。","山河眺望云天外，台榭參差煙霧中。","庭際花飞錦繡合，枝间鸟囀管弦同。","即此歡娛齊鎬宴，唯應率舞乐薰风。"]', '诗', 'shi', '', NULL, '奉和春日幸望春宮 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4436fa66-3d89-46ef-a1d5-60382ad35ac5', '奉和幸韋嗣立山莊侍宴應制', '奉和幸韋嗣立山莊侍宴應制', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["丞相登前府，尚書啓舊林。","式閭明主睿，榮族聖嬪心。","川狹旌門抵，巖高蔽帳臨。","閑窗憑柳暗，小徑入松深。","雲卷千峰色，泉和萬籟吟。","蘭迎天女佩，竹礙侍臣簪。","宸翰三光燭，朝榮四海欽。","還嗟絕機叟，白首漢川陰。"]', '["丞相登前府，尚书啓旧林。","式閭明主睿，榮族聖嬪心。","川狹旌门抵，巖高蔽帳臨。","闲窗憑柳暗，小徑入松深。","云卷千峰色，泉和万籟吟。","蘭迎天女佩，竹礙侍臣簪。","宸翰三光燭，朝榮四海欽。","還嗟絕機叟，白首漢川陰。"]', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊侍宴應制 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bbde0ae-0e7c-41b1-819b-2854346b93c2', '同李員外春閨', '同李員外春閨', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["落日啼連夜，孤燈坐徹明。","捲簾雙燕入，披幌百花驚。","隴上寒應晚，閨中織未成。","管弦愁不意，梳洗懶無情。","去歲聞西伐，今年送北征。","容顏離別盡，流恨滿長城。"]', '["落日啼連夜，孤灯坐徹明。","捲簾雙燕入，披幌百花驚。","隴上寒應晚，閨中织未成。","管弦愁不意，梳洗懶無情。","去歲闻西伐，今年送北征。","容顏離別尽，流恨满长城。"]', '诗', 'shi', '', NULL, '同李員外春閨 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e42c8d-4bc4-4517-96e9-b72fe359c296', '襄陽早秋寄岑侍郎', '襄陽早秋寄岑侍郎', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["江城秋氣早，旭旦坐南闈。","落葉驚衰鬢，清霜換旅衣。","時來矜早達，事往覺前非。","體道徒推理，防身終昧微。","故人金華省，肅穆秉天機。","誰念江漢廣，蹉跎心事違。"]', '["江城秋氣早，旭旦坐南闈。","落葉驚衰鬢，清霜換旅衣。","时来矜早達，事往覺前非。","體道徒推理，防身終昧微。","故人金华省，肅穆秉天機。","誰念江漢廣，蹉跎心事違。"]', '诗', 'shi', '', NULL, '襄陽早秋寄岑侍郎 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70ee0407-6eb0-4f97-ba38-f3b755088467', '贈蘇少府赴任江南余時還京', '贈蘇少府赴任江南余时還京', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["丈夫不歎別，達士自安卑。","攬泣固無趣，銜杯空爾爲。","流雲春窈窕，去水暮逶迤。","行舟忽東泛，歸騎亦西馳。","秦地多芳草，江潭有桂枝。","誰言阻遐闊，所貴在相知。"]', '["丈夫不歎別，達士自安卑。","攬泣固無趣，銜杯空爾爲。","流云春窈窕，去水暮逶迤。","行舟忽东泛，归騎亦西驰。","秦地多芳草，江潭有桂枝。","誰言阻遐闊，所貴在相知。"]', '诗', 'shi', '', NULL, '贈蘇少府赴任江南余時還京 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f32574bf-7764-44ea-8d8c-b452873142d2', '登總持寺閣', '登總持寺閣', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["宿雨清龍界，晨暉滿鳳城。","升攀重閣迥，憑覽四郊明。","井邑周秦地，山河今古情。","紆餘一水合，寥落五陵平。","處處風煙起，欣欣草木榮。","故人不可見，冠蓋滿東京。"]', '["宿雨清龙界，晨暉满鳳城。","升攀重閣迥，憑覽四郊明。","井邑周秦地，山河今古情。","紆餘一水合，寥落五陵平。","处处风煙起，欣欣草木榮。","故人不可见，冠蓋满东京。"]', '诗', 'shi', '', NULL, '登總持寺閣 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a132bab1-1809-4f43-b8d5-373952635083', '早春邊城懷歸', '早春邊城懷归', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["大漠羽書飛，長城未解圍。","山川凌玉嶂，旌節下金微。","路向南庭遠，書因北鴈稀。","鄉關搖別思，風雪散戎衣。","歲盡仍爲客，春還尚未歸。","明年征騎返，歌舞及芳菲。"]', '["大漠羽书飞，长城未解圍。","山川凌玉嶂，旌節下金微。","路向南庭远，书因北鴈稀。","乡关搖別思，风雪散戎衣。","歲尽仍爲客，春還尚未归。","明年征騎返，歌舞及芳菲。"]', '诗', 'shi', '', NULL, '早春邊城懷歸 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733604f9-89e9-4f48-a246-44d3ba77129d', '至桃林塞作', '至桃林塞作', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["去國未千里，離家已再旬。","丹心恆戀闕，白首更辭親。","懷璧常貽訓，捐金詎得鄰。","抱冤非忤物，罹謗豈由人。","不濫辭終辨，無瑕理竟伸。","黻還中省舊，符與外臺新。","塞上同遷客，江潭異逐臣。","淚垂非屬峴，腸斷固由秦。","歲月行遒盡，山川難重陳。","始知亭伯去，還是拙謀身。"]', '["去国未千里，離家已再旬。","丹心恆戀闕，白首更辞親。","懷璧常貽訓，捐金詎得鄰。","抱冤非忤物，罹謗豈由人。","不濫辞終辨，無瑕理竟伸。","黻還中省旧，符與外台新。","塞上同遷客，江潭異逐臣。","泪垂非屬峴，腸斷固由秦。","歲月行遒尽，山川难重陳。","始知亭伯去，還是拙謀身。"]', '诗', 'shi', '', NULL, '至桃林塞作 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b9bdae-4258-425f-9a77-a77297bc4e6a', '襄陽作', '襄陽作', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["廟堂初解印，郡邸忽腰章。","按節巡河右，鳴騶入漢陽。","城臨南峴出，樹繞北津長。","好學風猶扇，誇才俗未忘。","江山跨七澤，煙雨接三湘。","蛟浦菱荷淨，漁舟橘柚香。","醉中求習氏，夢裏憶襄王。","宅壞仍思鳳，碑存更憶羊。","下車慙政美，閉閣幸時康。","多謝南征術，于今尚不亡。"]', '["廟堂初解印，郡邸忽腰章。","按節巡河右，鳴騶入漢陽。","城臨南峴出，樹繞北津长。","好学风猶扇，誇才俗未忘。","江山跨七澤，煙雨接三湘。","蛟浦菱荷淨，漁舟橘柚香。","醉中求習氏，梦裏憶襄王。","宅壞仍思鳳，碑存更憶羊。","下车慙政美，閉閣幸时康。","多謝南征術，于今尚不亡。"]', '诗', 'shi', '', NULL, '襄陽作 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98fc8978-fa5f-4064-8df3-a6cd9ddc0b4f', '喜入長安', '喜入长安', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["雲日能催曉，風光不惜年。","賴逢征客盡，歸在落花前。"]', '["云日能催晓，风光不惜年。","賴逢征客尽，归在落花前。"]', '诗', 'shi', '', NULL, '喜入長安 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b0be1ca-b0fa-435b-8e7c-0c804daf7afd', '奉和幸韋嗣立山莊應制', '奉和幸韋嗣立山莊應制', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["竹徑桃源本出塵，松軒茅棟別驚新。","御蹕何須林下駐，山公不是俗中人。"]', '["竹徑桃源本出塵，松軒茅棟別驚新。","御蹕何須林下駐，山公不是俗中人。"]', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊應制 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4922d1-0dc1-4e89-9abb-59d9e1fdeb7f', '踏歌詞二首 一', '踏歌词二首 一', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["綵女迎金屋，仙姬出畫堂。","鴛鴦裁錦袖，翡翠貼花黃。","歌響舞分行，豔色動流光。"]', '["綵女迎金屋，仙姬出畫堂。","鴛鴦裁錦袖，翡翠貼花黄。","歌响舞分行，豔色动流光。"]', '诗', 'shi', '', NULL, '踏歌詞二首 一 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08d57185-e426-4c15-bf32-851a865e8f1d', '踏歌詞二首 二', '踏歌词二首 二', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["庭際花微落，樓前漢已橫。","金臺催夜盡，羅袖拂寒輕。","樂笑暢歡情，未半著天明。"]', '["庭際花微落，楼前漢已橫。","金台催夜尽，羅袖拂寒轻。","乐笑暢歡情，未半著天明。"]', '诗', 'shi', '', NULL, '踏歌詞二首 二 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf500489-3156-4261-87d8-d3e3b0d1bc62', '代春閨', '代春閨', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["江南日暖鴻始來，柳條初碧葉半開。","玉關遙遙戍未迴，金閨日夕生綠苔。","寂寂春花煙色暮，簷燕雙雙落花度。","青樓明鏡晝無光，紅帳羅衣徒自香。","妾恨十年長獨守，君情萬里在漁陽。"]', '["江南日暖鴻始来，柳條初碧葉半开。","玉关遙遙戍未迴，金閨日夕生綠苔。","寂寂春花煙色暮，簷燕雙雙落花度。","青楼明镜晝無光，紅帳羅衣徒自香。","妾恨十年长独守，君情万里在漁陽。"]', '诗', 'shi', '', NULL, '代春閨 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c190c99b-4dca-499d-9946-0c86b15b2384', '上元夜六首 一', '上元夜六首 一', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["玉漏銀壺且莫催，鐵關金鎖徹明開。","誰家見月能閒坐，何處聞燈不看来。"]', '["玉漏銀壺且莫催，鐵关金鎖徹明开。","誰家见月能閒坐，何处闻灯不看来。"]', '诗', 'shi', '', NULL, '上元夜六首 一 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a69d67cc-b295-47ce-b55a-c37641f19bc8', '上元夜六首 二', '上元夜六首 二', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["神燈佛火百輪張，刻像圖形七寶裝。","影裏如聞金口說，空中似散玉毫光。"]', '["神灯佛火百輪張，刻像圖形七寶裝。","影裏如闻金口说，空中似散玉毫光。"]', '诗', 'shi', '', NULL, '上元夜六首 二 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47507272-4baa-4590-89f0-519c044865a6', '上元夜六首 三', '上元夜六首 三', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["今年春色勝常年，此夜風光最可憐。","鳷鵲樓前新月滿，鳳皇臺上寶燈燃。"]', '["今年春色勝常年，此夜风光最可怜。","鳷鵲楼前新月满，鳳皇台上寶灯燃。"]', '诗', 'shi', '', NULL, '上元夜六首 三 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaf10198-98c3-40da-89cb-71e9c9bb6f32', '上元夜六首 四', '上元夜六首 四', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["金勒銀鞍控紫騮，玉輪珠幰駕青牛。","驂驔始散東城曲，倏忽還來南陌頭。"]', '["金勒銀鞍控紫騮，玉輪珠幰駕青牛。","驂驔始散东城曲，倏忽還来南陌头。"]', '诗', 'shi', '', NULL, '上元夜六首 四 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d7761c4-5488-4585-895e-9fb2d904329e', '上元夜六首 五', '上元夜六首 五', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["公子王孫意氣驕，不論相識也相邀。","最憐長袖風前弱，更賞新弦暗裏調。"]', '["公子王孫意氣驕，不論相識也相邀。","最怜长袖风前弱，更賞新弦暗裏調。"]', '诗', 'shi', '', NULL, '上元夜六首 五 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('179bb9e7-363c-47e3-8285-c79653ecdb62', '上元夜六首 六', '上元夜六首 六', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["星移漢轉日將微，露灑煙飄燈漸稀。","猶惜路傍歌舞處，躊躕相顧不能歸。"]', '["星移漢轉日將微，露灑煙飄灯漸稀。","猶惜路傍歌舞处，躊躕相顧不能归。"]', '诗', 'shi', '', NULL, '上元夜六首 六 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('821997f5-b3ba-4c3c-b41e-0c343c960d1f', '冀北春望', '冀北春望', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["迴首覽燕趙，春生兩河間。","曠然餘萬里，際海不見山。","雨歇青林潤，煙空綠野閑。","問鄉無處所，目送白雲關。"]', '["迴首覽燕趙，春生兩河间。","曠然餘万里，際海不见山。","雨歇青林潤，煙空綠野闲。","问乡無处所，目送白云关。"]', '诗', 'shi', '', NULL, '冀北春望 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf76a945-5999-49b2-a421-dabc3390f512', '擬古神女宛轉歌二首 一', '擬古神女宛轉歌二首 一', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["風已清，月朗琴復明。","掩抑悲千態，殷勤是一聲。","歌宛轉，宛轉和更長。","願爲雙鴻鵠，比翼共翱翔。"]', '["风已清，月朗琴复明。","掩抑悲千態，殷勤是一声。","歌宛轉，宛轉和更长。","願爲雙鴻鵠，比翼共翱翔。"]', '诗', 'shi', '', NULL, '擬古神女宛轉歌二首 一 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb186930-154b-479e-8d6f-108b6aeb8e1c', '擬古神女宛轉歌二首 二', '擬古神女宛轉歌二首 二', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["日已暮，長簷鳥應度。","此時望君君不來，此時思君君不顧。","歌宛轉，宛轉那能異棲宿。","願爲形與影，出入恆相逐。"]', '["日已暮，长簷鸟應度。","此时望君君不来，此时思君君不顧。","歌宛轉，宛轉那能異棲宿。","願爲形與影，出入恆相逐。"]', '诗', 'shi', '', NULL, '擬古神女宛轉歌二首 二 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6640be9f-5f63-4307-a324-d71833ed2641', '望韓公堆', '望韓公堆', 'cca91858-a419-40aa-bddf-4a78645dcbb2', '唐', '["韓公堆上望秦川，渺渺關山西接連。","孤客一身千里外，未知歸日是何年。"]', '["韓公堆上望秦川，渺渺关山西接連。","孤客一身千里外，未知归日是何年。"]', '诗', 'shi', '', NULL, '望韓公堆 崔滌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca416e26-96be-49ca-ab46-5c91d4ff42a1', '倬彼我系 一', '倬彼我系 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["倬彼我系，出自有周。","分疆錫社，派別支流。","居衞仕宋，臣嬴相劉。","廼武廼文，或公或侯。"]', '["倬彼我系，出自有周。","分疆錫社，派別支流。","居衞仕宋，臣嬴相劉。","廼武廼文，或公或侯。"]', '诗', 'shi', '', NULL, '倬彼我系 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('113ed00f-61c6-49e3-8898-7f13441c3a2b', '倬彼我系 二', '倬彼我系 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["晉曆崩坼，衣冠擾弊。","粵自太原，播徂江澨。","禮喪賢隱，時屯道閉。","王室如燬，生人多殪。"]', '["晉曆崩坼，衣冠擾弊。","粵自太原，播徂江澨。","禮喪賢隐，时屯道閉。","王室如燬，生人多殪。"]', '诗', 'shi', '', NULL, '倬彼我系 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4514bc5b-b6b6-4fe4-8341-6951a73ba76f', '倬彼我系 三', '倬彼我系 三', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["伊我有器，思逢其主。","自東施西，擇木開宇。","田彼河曲，家乎汾浦。","天未厭亂，吾將誰輔。"]', '["伊我有器，思逢其主。","自东施西，擇木开宇。","田彼河曲，家乎汾浦。","天未厭亂，吾將誰輔。"]', '诗', 'shi', '', NULL, '倬彼我系 三 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3757a306-bb29-4354-a8c5-171649777e80', '倬彼我系 四', '倬彼我系 四', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["伊我祖德，思濟九埏。","不常厥所，于茲五遷。","欲及時也，夫豈願焉。","其位雖屈，其言則傳。"]', '["伊我祖德，思濟九埏。","不常厥所，于茲五遷。","欲及时也，夫豈願焉。","其位雖屈，其言則傳。"]', '诗', 'shi', '', NULL, '倬彼我系 四 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46a0bd86-6784-43ed-bcf6-3d75028768aa', '倬彼我系 五', '倬彼我系 五', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["爰述帝制，大蒐王道。","曰天曰人，是祖是考。","禮樂咸若，詩書具草。","貽厥孫謀，永爲家寶。"]', '["爰述帝制，大蒐王道。","曰天曰人，是祖是考。","禮乐咸若，诗书具草。","貽厥孫謀，永爲家寶。"]', '诗', 'shi', '', NULL, '倬彼我系 五 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7156f64-3797-4f4c-a5ac-f6314ba08155', '倬彼我系 六', '倬彼我系 六', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["伊余小子，信慙明哲。","彼網有條，彼車有轍。","思屏人事，克終前烈。","于嗟代網，卒余來絏。"]', '["伊余小子，信慙明哲。","彼網有條，彼车有轍。","思屏人事，克終前烈。","于嗟代網，卒余来絏。"]', '诗', 'shi', '', NULL, '倬彼我系 六 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469f2d52-ff14-45c2-a8b9-e958e05c38dd', '倬彼我系 七', '倬彼我系 七', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["來絏伊何，謂余曰仕。","我瞻先達，三十方起。","夫豈不懷，高山仰止。","願言毓德，啜菽飲水。"]', '["来絏伊何，謂余曰仕。","我瞻先達，三十方起。","夫豈不懷，高山仰止。","願言毓德，啜菽饮水。"]', '诗', 'shi', '', NULL, '倬彼我系 七 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b534cfc1-e3de-405e-836d-c1d56b812bd9', '倬彼我系 八', '倬彼我系 八', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["有鳥反哺，其聲嗷嗷。","言念舊德，憂心忉忉。","今我不養，歲月其滔。","僶俛從役，豈敢告勞。"]', '["有鸟反哺，其声嗷嗷。","言念旧德，憂心忉忉。","今我不養，歲月其滔。","僶俛從役，豈敢告勞。"]', '诗', 'shi', '', NULL, '倬彼我系 八 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea64690f-de70-4759-81e4-01e782adfc41', '倬彼我系 九', '倬彼我系 九', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["從役伊何，薄求卑位。","告勞伊何，來參卿事。","名存實爽，負信愆義。","靜言遐思，中心是愧。"]', '["從役伊何，薄求卑位。","告勞伊何，来參卿事。","名存實爽，負信愆義。","静言遐思，中心是愧。"]', '诗', 'shi', '', NULL, '倬彼我系 九 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5d1d42-f2d5-49ff-aa3e-c5743800c3a2', '上巳浮江宴韻得阯字', '上巳浮江宴韻得阯字', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["披觀玉京路，駐賞金臺阯。","逸興懷九仙，良辰傾四美。","松吟白雲際，桂馥青溪裏。","別有江海心，日暮情何已。"]', '["披观玉京路，駐賞金台阯。","逸兴懷九仙，良辰傾四美。","松吟白云際，桂馥青溪裏。","別有江海心，日暮情何已。"]', '诗', 'shi', '', NULL, '上巳浮江宴韻得阯字 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('931f1f81-3209-4a11-9984-9138dd07a97b', '春日宴樂遊園賦韻得接字', '春日宴乐游园賦韻得接字', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["帝里寒光盡，神臯春望浹。","梅郊落晚英，柳甸驚初葉。","流水抽奇弄，崩雲灑芳牒。","清尊湛不空，暫喜平生接。"]', '["帝里寒光尽，神臯春望浹。","梅郊落晚英，柳甸驚初葉。","流水抽奇弄，崩云灑芳牒。","清尊湛不空，暫喜平生接。"]', '诗', 'shi', '', NULL, '春日宴樂遊園賦韻得接字 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74b7e4a8-af8e-4845-8e8c-7290b0a650c8', '山亭夜宴', '山亭夜宴', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["桂宇幽襟積，山亭涼夜永。","森沈野徑寒，肅穆巖扉靜。","竹晦南汀色，荷翻北潭影。","清興殊未闌，林端照初景。"]', '["桂宇幽襟積，山亭涼夜永。","森沈野徑寒，肅穆巖扉静。","竹晦南汀色，荷翻北潭影。","清兴殊未闌，林端照初景。"]', '诗', 'shi', '', NULL, '山亭夜宴 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98c8b8e6-005b-4164-9099-f1a7e4d0d51d', '詠風', '詠风', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["肅肅涼景生，加我林壑清。","驅煙尋磵戶，卷霧出山楹。","去來固無跡，動息如有情。","日落山水靜，爲君起松聲。"]', '["肅肅涼景生，加我林壑清。","驱煙尋磵戶，卷霧出山楹。","去来固無跡，动息如有情。","日落山水静，爲君起松声。"]', '诗', 'shi', '', NULL, '詠風 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c40dd19-7c9f-4d54-820f-3e219872de74', '懷仙', '懷仙', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["鶴岑有奇徑，麟洲富仙家。","紫泉漱珠液，玄巖列丹葩。","常希披塵網，眇然登雲車。","鸞情極霄漢，鳳想疲煙霞。","道存蓬瀛近，意愜朝市賒。","無爲坐惆悵，虛此江上華。"]', '["鹤岑有奇徑，麟洲富仙家。","紫泉漱珠液，玄巖列丹葩。","常希披塵網，眇然登云车。","鸾情極霄漢，鳳想疲煙霞。","道存蓬瀛近，意愜朝市賒。","無爲坐惆悵，虛此江上华。"]', '诗', 'shi', '', NULL, '懷仙 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3554a29f-272a-4828-8437-4b3823468690', '忽夢遊仙', '忽梦游仙', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["僕本江上客，牽跡在方內。","寤寐霄漢間，居然有靈對。","翕爾登霞首，依然躡雲背。","電策驅龍光，煙途儼鸞態。","乘月披金帔，連星解瓊珮。","浮識俄易歸，真遊邈難再。","寥廓沈遐想，周遑奉遺誨。","流俗非我鄉，何當釋塵昧。"]', '["僕本江上客，牽跡在方內。","寤寐霄漢间，居然有靈对。","翕爾登霞首，依然躡云背。","電策驱龙光，煙途儼鸾態。","乘月披金帔，連星解瓊珮。","浮識俄易归，真游邈难再。","寥廓沈遐想，周遑奉遺誨。","流俗非我乡，何當釋塵昧。"]', '诗', 'shi', '', NULL, '忽夢遊仙 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('756d6122-bd88-4235-9adb-3ec5c2700b27', '雜曲', '杂曲', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["智瓊神女，來訪文君。","蛾眉始約，羅袖初薰。","歌齊曲韻，舞亂行紛。","若向陽臺薦枕，何啻得勝朝雲。"]', '["智瓊神女，来訪文君。","蛾眉始約，羅袖初薰。","歌齊曲韻，舞亂行紛。","若向陽台薦枕，何啻得勝朝云。"]', '诗', 'shi', '', NULL, '雜曲 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9f294b-1b9b-4cb5-ac3a-a6d847405d33', '秋夜長', '秋夜长', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["秋夜長，殊未央。","月明白露澄清光，層城綺閣遙相望。","遙相望，川無梁。","北風受節南雁翔，崇蘭委質時菊芳。","鳴環曳履出長廊，爲君秋夜擣衣裳。","纖羅對鳳皇，丹綺雙鴛鴦。","調砧亂杵思自傷，思自傷，征夫萬里戍他鄉。","鶴關音信斷，龍門道路長。","君在天一方，寒衣徒自香。"]', '["秋夜长，殊未央。","月明白露澄清光，層城綺閣遙相望。","遙相望，川無梁。","北风受節南雁翔，崇蘭委質时菊芳。","鳴环曳履出长廊，爲君秋夜擣衣裳。","纖羅对鳳皇，丹綺雙鴛鴦。","調砧亂杵思自傷，思自傷，征夫万里戍他乡。","鹤关音信斷，龙门道路长。","君在天一方，寒衣徒自香。"]', '诗', 'shi', '', NULL, '秋夜長 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0820a352-463f-4da9-a96a-8dd3dcc56c5f', '採蓮曲', '採蓮曲', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["採蓮歸，綠水芙蓉衣。","秋風起浪鳧雁飛，桂櫂蘭橈下長浦。","羅裙玉腕輕搖櫓，葉嶼花潭極望平。","江謳越吹相思苦，相思苦，佳期不可駐。","塞外征夫猶未還，江南採蓮今已暮。","今已暮，採蓮花，渠今那必盡娼家。","官道城南把桑葉，何如江上採蓮花。","蓮花復蓮花，花葉何稠疊。","葉翠本羞眉，花紅強如頰。","佳人不在茲，悵望別離時。","牽花憐共蒂，折藕愛連絲。","故情無處所，新物從華滋。","不惜西津交佩解，還羞北海雁書遲。","採蓮歌有節，採蓮夜未歇。","正逢浩蕩江上風，又值裴回江上月。","裴回蓮浦夜相逢，吳姬越女何丰茸。","共問寒江千里外，征客關山路幾重。"]', '["採蓮归，綠水芙蓉衣。","秋风起浪鳧雁飞，桂櫂蘭橈下长浦。","羅裙玉腕轻搖櫓，葉嶼花潭極望平。","江謳越吹相思苦，相思苦，佳期不可駐。","塞外征夫猶未還，江南採蓮今已暮。","今已暮，採蓮花，渠今那必尽娼家。","官道城南把桑葉，何如江上採蓮花。","蓮花复蓮花，花葉何稠叠。","葉翠本羞眉，花紅強如頰。","佳人不在茲，悵望別離时。","牽花怜共蒂，折藕愛連絲。","故情無处所，新物從华滋。","不惜西津交佩解，還羞北海雁书遲。","採蓮歌有節，採蓮夜未歇。","正逢浩蕩江上风，又值裴回江上月。","裴回蓮浦夜相逢，吳姬越女何丰茸。","共问寒江千里外，征客关山路幾重。"]', '诗', 'shi', '', NULL, '採蓮曲 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7040e3b-0326-4ad0-a23c-411c4ff51c76', '臨高臺', '臨高台', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["臨高臺，高臺迢遰絕浮埃。","瑤軒綺構何崔嵬，鸞歌鳳吹清且哀。","俯瞰長安道，萋萋御溝草。","斜對甘泉路，蒼蒼茂陵樹。","高臺四望同，帝鄉佳氣鬱蔥蔥。","紫閣丹樓紛照耀，璧房錦殿相玲瓏。","東彌長樂觀，西指未央宮。","赤城映朝日，綠樹搖春風。","旗亭百隧開新市，甲第千甍分戚里。","朱輪翠蓋不勝春，疊榭層楹相對起。","復有青樓大道中，繡戶文窗雕綺櫳。","錦衾夜不襞，羅帷晝未空。","歌屏朝揜翠，妝鏡晚窺紅。","爲君安寶髻，蛾眉罷花叢。","塵間狹路黯將暮，雲間月色明如素。","鴛鴦池上兩兩飛，鳳凰樓下雙雙度。","物色正如此，佳期那不顧。","銀鞍繡轂盛繁華，可憐今夜宿娼家。","娼家少婦不須顰，東園桃李片時春。","君看舊日高臺處，柏梁銅雀生黃塵。"]', '["臨高台，高台迢遰絕浮埃。","瑤軒綺構何崔嵬，鸾歌鳳吹清且哀。","俯瞰长安道，萋萋御溝草。","斜对甘泉路，蒼蒼茂陵樹。","高台四望同，帝乡佳氣鬱蔥蔥。","紫閣丹楼紛照耀，璧房錦殿相玲瓏。","东彌长乐观，西指未央宮。","赤城映朝日，綠樹搖春风。","旗亭百隧开新市，甲第千甍分戚里。","朱輪翠蓋不勝春，叠榭層楹相对起。","复有青楼大道中，繡戶文窗雕綺櫳。","錦衾夜不襞，羅帷晝未空。","歌屏朝揜翠，妝镜晚窺紅。","爲君安寶髻，蛾眉罷花叢。","塵间狹路黯將暮，云间月色明如素。","鴛鴦池上兩兩飞，鳳凰楼下雙雙度。","物色正如此，佳期那不顧。","銀鞍繡轂盛繁华，可怜今夜宿娼家。","娼家少婦不須顰，东园桃李片时春。","君看旧日高台处，柏梁銅雀生黄塵。"]', '诗', 'shi', '', NULL, '臨高臺 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f023a30-3a31-4262-9ee7-ade9e4e591c8', '滕王閣', '滕王閣', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["滕王高閣臨江渚，珮玉鳴鸞罷歌舞。","畫棟朝飛南浦雲，珠簾暮捲西山雨。","閑雲潭影日悠悠，物換星移幾度秋。","閣中帝子今何在？檻外長江空自流。"]', '["滕王高閣臨江渚，珮玉鳴鸾罷歌舞。","畫棟朝飞南浦云，珠簾暮捲西山雨。","闲云潭影日悠悠，物換星移幾度秋。","閣中帝子今何在？檻外长江空自流。"]', '诗', 'shi', '', NULL, '滕王閣 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('387f7a5f-6abb-48f9-9ecb-0be7b27428f8', '江南弄', '江南弄', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["江南弄，巫山連楚夢，行雨行雲幾相送。","瑤軒金谷上春時，玉童仙女無見期。","紫露香煙渺難託，清風明月遙相思。","遙相思，草徒綠，爲聽雙飛鳳凰曲。"]', '["江南弄，巫山連楚梦，行雨行云幾相送。","瑤軒金谷上春时，玉童仙女無见期。","紫露香煙渺难託，清风明月遙相思。","遙相思，草徒綠，爲听雙飞鳳凰曲。"]', '诗', 'shi', '', NULL, '江南弄 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('051ff52b-2c24-44ef-a0b9-37659e0fe680', '聖泉宴', '聖泉宴', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["披襟乘石磴，列籍俯春泉。","蘭氣熏山酌，松聲韻野弦。","影飄垂葉外，香度落花前。","興洽林塘晚，重巖起夕煙。"]', '["披襟乘石磴，列籍俯春泉。","蘭氣熏山酌，松声韻野弦。","影飄垂葉外，香度落花前。","兴洽林塘晚，重巖起夕煙。"]', '诗', 'shi', '', NULL, '聖泉宴 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7565a1fd-cb08-488b-b456-01ff54330636', '尋道觀', '尋道观', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["芝廛光分野，蓬闕盛規模。","碧壇清桂閾，丹洞肅松樞。","玉笈三山記，金箱五嶽圖。","蒼虬不可得，空望白雲衢。"]', '["芝廛光分野，蓬闕盛規模。","碧壇清桂閾，丹洞肅松樞。","玉笈三山記，金箱五嶽圖。","蒼虬不可得，空望白云衢。"]', '诗', 'shi', '', NULL, '尋道觀 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bed2740-0644-4ffc-9661-77173b742ef3', '散關晨度', '散关晨度', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["關山凌旦開，石路無塵埃。","白馬高譚去，青牛真氣來。","重門臨巨壑，連棟起崇隈。","即今揚策度，非是棄繻回。"]', '["关山凌旦开，石路無塵埃。","白马高譚去，青牛真氣来。","重门臨巨壑，連棟起崇隈。","即今揚策度，非是棄繻回。"]', '诗', 'shi', '', NULL, '散關晨度 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56cf7e31-5924-43f8-9c1a-0a4e556fc13b', '別薛華', '別薛华', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["送送多窮路，遑遑獨問津。","悲涼千里道，悽斷百年身。","心事同漂泊，生涯共苦辛。","無論去與住，俱是夢中人。"]', '["送送多窮路，遑遑独问津。","悲涼千里道，悽斷百年身。","心事同漂泊，生涯共苦辛。","無論去與住，俱是梦中人。"]', '诗', 'shi', '', NULL, '別薛華 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c0439ad-bbc9-408c-801f-de7c948631b7', '重別薛華', '重別薛华', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["明月沈珠浦，秋風濯錦川。","樓臺臨絕岸，洲渚亙長天。","旅泊成千里，棲遑共百年。","窮途唯有淚，還望獨潸然。"]', '["明月沈珠浦，秋风濯錦川。","楼台臨絕岸，洲渚亙长天。","旅泊成千里，棲遑共百年。","窮途唯有泪，還望独潸然。"]', '诗', 'shi', '', NULL, '重別薛華 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d04bd9-0163-4f26-ae0a-f380469488ad', '遊梵宇三覺寺', '游梵宇三覺寺', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["杏閣披青磴，琱臺控紫岑。","葉齊山路狹，花積野壇深。","蘿幌棲禪影，松門聽梵音。","遽忻陪妙躅，延賞滌煩襟。"]', '["杏閣披青磴，琱台控紫岑。","葉齊山路狹，花積野壇深。","蘿幌棲禪影，松门听梵音。","遽忻陪妙躅，延賞滌煩襟。"]', '诗', 'shi', '', NULL, '遊梵宇三覺寺 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58794d4f-58da-49cb-95cd-e827daf10a61', '麻平晚行', '麻平晚行', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["百年懷土望，千里倦遊情。","高低尋戍道，遠近聽泉聲。","磵葉纔分色，山花不辨名。","羈心何處盡？風急暮猨清。"]', '["百年懷土望，千里倦游情。","高低尋戍道，远近听泉声。","磵葉纔分色，山花不辨名。","羈心何处尽？风急暮猨清。"]', '诗', 'shi', '', NULL, '麻平晚行 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4254f08-9b3f-4717-b8e1-30808345afeb', '送盧主簿', '送盧主簿', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["窮途非所恨，虛室自相依。","城闕居年滿，琴尊俗事稀。","開襟方未已，分袂忽多違。","東巖富松竹，歲暮幸同歸。"]', '["窮途非所恨，虛室自相依。","城闕居年满，琴尊俗事稀。","开襟方未已，分袂忽多違。","东巖富松竹，歲暮幸同归。"]', '诗', 'shi', '', NULL, '送盧主簿 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a20c4064-a898-4265-bc47-d41d8e0c9fd6', '餞韋兵曹', '餞韋兵曹', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["征驂臨野次，別袂慘江垂。","川霽浮煙歛，山明落照移。","鷹風凋晚葉，蟬露泣秋枝。","亭臯分遠望，延想間雲涯。"]', '["征驂臨野次，別袂慘江垂。","川霽浮煙歛，山明落照移。","鷹风凋晚葉，蟬露泣秋枝。","亭臯分远望，延想间云涯。"]', '诗', 'shi', '', NULL, '餞韋兵曹 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c01b049-07ab-4898-8963-920c7c66c266', '白下驛餞唐少府', '白下驛餞唐少府', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["下驛窮交日，昌亭旅食年。","相知何用早，懷抱即依然。","浦樓低晚照，鄉路隔風煙。","去去如何道，長安在日邊。"]', '["下驛窮交日，昌亭旅食年。","相知何用早，懷抱即依然。","浦楼低晚照，乡路隔风煙。","去去如何道，长安在日邊。"]', '诗', 'shi', '', NULL, '白下驛餞唐少府 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6f4b72-855c-43b9-8883-8b3fe3cd8bd4', '杜少府之任蜀州', '杜少府之任蜀州', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["城闕輔三秦，風煙望五津。","與君離別意，同是宦遊人。","海內存知己，天涯若比隣。","無爲在岐路，兒女共霑巾。"]', '["城闕輔三秦，风煙望五津。","與君離別意，同是宦游人。","海內存知己，天涯若比隣。","無爲在岐路，兒女共霑巾。"]', '诗', 'shi', '', NULL, '杜少府之任蜀州 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dd6cd60-5ecb-4b13-86ba-f05f9789e62c', '仲春郊外', '仲春郊外', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["東園垂柳徑，西堰落花津。","物色連三月，風光絕四隣。","鳥飛村覺曙，魚戲水知春。"]', '["东园垂柳徑，西堰落花津。","物色連三月，风光絕四隣。","鸟飞村覺曙，鱼戲水知春。"]', '诗', 'shi', '', NULL, '仲春郊外 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f33c79f-8e0c-4817-8a2b-edea6ad23208', '郊興', '郊兴', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["空園歌獨酌，春日賦閑居。","澤蘭侵小徑，河柳覆長渠。","雨去花光濕，風歸葉影疎。","山人不惜醉，唯畏綠尊虛。"]', '["空园歌独酌，春日賦闲居。","澤蘭侵小徑，河柳覆长渠。","雨去花光濕，风归葉影疎。","山人不惜醉，唯畏綠尊虛。"]', '诗', 'shi', '', NULL, '郊興 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b014596b-1c6a-4bb5-8631-0c37866d340b', '郊園即事', '郊园即事', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["煙霞春旦賞，松竹故年心。","斷山疑畫障，縣溜瀉鳴琴。","草徧南亭合，花開北院深。","閑居饒酒賦，隨興欲抽簪。"]', '["煙霞春旦賞，松竹故年心。","斷山疑畫障，縣溜瀉鳴琴。","草徧南亭合，花开北院深。","闲居饒酒賦，隨兴欲抽簪。"]', '诗', 'shi', '', NULL, '郊園即事 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a707aa-a8dd-4fbf-9b4a-91797e03d525', '觀佛跡寺', '观佛跡寺', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["蓮座神容儼，松崖聖趾餘。","年長金跡淺，地久石文疎。","頹華臨曲磴，傾影赴前除。","共嗟陵谷遠，俄視化城虛。"]', '["蓮座神容儼，松崖聖趾餘。","年长金跡淺，地久石文疎。","頹华臨曲磴，傾影赴前除。","共嗟陵谷远，俄視化城虛。"]', '诗', 'shi', '', NULL, '觀佛跡寺 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('654d2706-43c2-4df0-a952-20d97de421f2', '山居晚眺贈王道士', '山居晚眺贈王道士', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["金壇疎俗宇，玉洞侶仙羣。","花枝棲晚露，峰葉度晴雲。","斜照移山影，回沙擁籀文。","琴尊方待興，竹樹已迎曛。"]', '["金壇疎俗宇，玉洞侶仙羣。","花枝棲晚露，峰葉度晴云。","斜照移山影，回沙擁籀文。","琴尊方待兴，竹樹已迎曛。"]', '诗', 'shi', '', NULL, '山居晚眺贈王道士 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f53618f-7d8c-4df3-969f-a53963594ea7', '八仙逕', '八仙逕', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["柰園欣八正，松巖訪九仙。","援蘿窺霧術，攀林俯雲烟。","代北鸞驂至，遼西鶴騎旋。","終希脫塵網，連翼下芝田。"]', '["柰园欣八正，松巖訪九仙。","援蘿窺霧術，攀林俯云烟。","代北鸾驂至，遼西鹤騎旋。","終希脫塵網，連翼下芝田。"]', '诗', 'shi', '', NULL, '八仙逕 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b8464f8-3be3-40ad-b632-6b7027f8edcc', '春日還郊', '春日還郊', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["閑情兼嘿語，攜杖赴巖泉。","草綠縈新帶，榆青綴古錢。","魚牀侵岸水，鳥路入山煙。","還題平子賦，花樹滿春田。"]', '["闲情兼嘿語，携杖赴巖泉。","草綠縈新带，榆青綴古錢。","鱼牀侵岸水，鸟路入山煙。","還題平子賦，花樹满春田。"]', '诗', 'shi', '', NULL, '春日還郊 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('286d31c9-8d14-408e-a339-cdd05a4d36b2', '對酒春園作', '对酒春园作', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["投簪下山閣，攜酒對河梁。","狹水牽長鏡，高花送斷香。","繁鶯歌似曲，疎蝶舞成行。","自然催一醉，非但閱年光。"]', '["投簪下山閣，携酒对河梁。","狹水牽长镜，高花送斷香。","繁鶯歌似曲，疎蝶舞成行。","自然催一醉，非但閱年光。"]', '诗', 'shi', '', NULL, '對酒春園作 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f05ef11d-52d9-4684-a9c4-c6b7c7c92352', '觀內懷仙', '观內懷仙', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["玉架殘書隱，金壇舊跡迷。","牽花尋紫澗，步葉下清谿。","瓊漿猶類乳，石髓尚如泥。","自能成羽翼，何必仰雲梯。"]', '["玉架殘书隐，金壇旧跡迷。","牽花尋紫澗，步葉下清谿。","瓊漿猶類乳，石髓尚如泥。","自能成羽翼，何必仰云梯。"]', '诗', 'shi', '', NULL, '觀內懷仙 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1107ead7-1271-44d9-9354-4ea61a605cdc', '秋日別王長史', '秋日別王长史', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["別路餘千里，深恩重百年。","正悲西候日，更動北梁篇。","野色籠寒霧，山光歛暮煙。","終知難再奉，懷德自潸然。"]', '["別路餘千里，深恩重百年。","正悲西候日，更动北梁篇。","野色籠寒霧，山光歛暮煙。","終知难再奉，懷德自潸然。"]', '诗', 'shi', '', NULL, '秋日別王長史 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('118a90d5-3a84-47d0-8261-5d92fb2da00a', '上巳浮江宴韻得遙字', '上巳浮江宴韻得遙字', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["上巳年光促，中川興緒遙。","綠齊山葉滿，紅洩片花銷。","泉聲喧後澗，虹影照前橋。","遽悲春望遠，江路積波潮。"]', '["上巳年光促，中川兴緒遙。","綠齊山葉满，紅洩片花銷。","泉声喧後澗，虹影照前橋。","遽悲春望远，江路積波潮。"]', '诗', 'shi', '', NULL, '上巳浮江宴韻得遙字 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c78f0ab8-ba60-4844-ae25-6b5f4a7e4cca', '長柳', '长柳', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["晨征犯煙磴，夕憩在雲關。","晚風清近壑，新月照澄灣。","郊童樵唱返，津叟釣歌還。","客行無與晤，賴此釋愁顏。"]', '["晨征犯煙磴，夕憩在云关。","晚风清近壑，新月照澄灣。","郊童樵唱返，津叟釣歌還。","客行無與晤，賴此釋愁顏。"]', '诗', 'shi', '', NULL, '長柳 王勃 shi');
